INSERT INTO `games` (`id`, `title`, `slug`, `iframe_url`, `image_url`, `description`, `category`, `views`, `status`, `created_at`) VALUES
(1, 'Panda Dash Auto Shooting', '5b5d6fb2a240493f8b6dd34cb798d612', 'https://html5.gamedistribution.com/5b5d6fb2a240493f8b6dd34cb798d612/', 'assets/thumbs/5b5d6fb2a240493f8b6dd34cb798d612.jpg', 'Jump straight into explosive action with Panda Dash Auto Shooting! In this fast-paced side-scrolling shooting adventure, you guide a fearless panda warrior into chaotic arenas packed with endless zombie waves. Each battle throws you into intense combat where survival depends on positioning and strategy. Every round feels stronger, faster, and more thrilling than the last! Get ready, grab your gear, and dash into zombie chaos!', 'Adventure', 8, 'publish', '2026-04-18 14:28:28'),
(3, 'Office Knight 3D: Castle Defense', '1fc5b3cb598b4d52802bb5003e4f1e79', 'https://html5.gamedistribution.com/1fc5b3cb598b4d52802bb5003e4f1e79/', 'assets/thumbs/1fc5b3cb598b4d52802bb5003e4f1e79.jpg', 'Office Warrior: Wield swords and axes as skillfully as a stapler!\r\nAction Battles: Fight various enemies in dynamic 3D environments.\r\nProgression System: Level up, improve health and damage right in the heat of battle.\r\nWeapon &amp; Upgrade Shop: Collect coins to buy hero upgrades and equip yourself.\r\nEndless Challenge: Deflect waves of enemies and prove you are the ultimate defender!', 'Adventure', 4, 'publish', '2026-04-18 14:33:41'),
(5, 'Clash &amp; Run', 'f3f2340b6fd74c5c8ef4eaaa88781746', 'https://html5.gamedistribution.com/f3f2340b6fd74c5c8ef4eaaa88781746/', 'assets/thumbs/f3f2340b6fd74c5c8ef4eaaa88781746.jpg', 'One chance, no turning back. Speed is your only ally in a world that won’t wait. Race through ever-shifting terrain where every jump could be your last. Collect coins and unlock unique looks. Precision and quick thinking will keep you in the game longer.', 'Casual', 7, 'publish', '2026-04-18 14:35:58'),
(6, 'Bublix: Bubble Hit', '908ed6a402314c1e8dc62b8103dd4adf', 'https://html5.gamedistribution.com/908ed6a402314c1e8dc62b8103dd4adf/', 'assets/thumbs/908ed6a402314c1e8dc62b8103dd4adf.jpg', 'Bublix: Bubble Hit is a fast-paced bubble shooter where precision and strategy matter. Aim, shoot, and match 3 or more bubbles to clear the board. Use clever angles, wall bounces, and combos to boost your score. With endless gameplay and rising difficulty, it’s perfect for quick, addictive sessions.', 'Bubble Shooter', 2, 'publish', '2026-04-18 14:35:59'),
(7, 'Math Master', '1bd7a44469c84c65b2d95f2289ee7007', 'https://html5.gamedistribution.com/1bd7a44469c84c65b2d95f2289ee7007/', 'assets/thumbs/1bd7a44469c84c65b2d95f2289ee7007.jpg', 'Unleash your inner math whiz! Math Master turns numbers into art—solve fun math problems to unlock drawing tools, sketch colorful shapes, and bring numerical puzzles to life. Perfect for learners and creativity lovers alike!', 'Puzzle', 5, 'publish', '2026-04-18 14:36:08'),
(8, 'Rainbow Friends. Survival', 'f9c16276d8794eb7a1f2cd293e7937a7', 'https://html5.gamedistribution.com/f9c16276d8794eb7a1f2cd293e7937a7/', 'assets/thumbs/f9c16276d8794eb7a1f2cd293e7937a7.jpg', 'A fun and dangerous game about Rainbow Friends!\r\nYou are in a dangerous place. You need to survive 5 days and 5 nights, but the deadly obstacle will be the terrifying and bloodthirsty monsters Rainbow Friends!\r\nComplete all the missions, move fast, perform actions carefully and run away from the monstrous monsters!', 'Adventure', 3, 'publish', '2026-04-18 14:36:09'),
(9, 'Hidden Object Adventure', 'afbb219bce514948ad6fa5ac47c65567', 'https://html5.gamedistribution.com/afbb219bce514948ad6fa5ac47c65567/', 'assets/thumbs/afbb219bce514948ad6fa5ac47c65567.jpg', 'Are you ready to solve puzzles and uncover hidden secrets? Become a detective in Find Hidden Object Game and test your observation skills! Explore detailed scenes in schools, houses, amusement parks, and zoos. Search for cleverly hidden items, challenge your brain, and enjoy fun, relaxing gameplay. Perfect for casual players and puzzle lovers alike. Train your mind and become the ultimate detective!', 'Puzzle', 6, 'publish', '2026-04-18 14:36:09'),
(10, 'Max Speed', '48f3d14ced3646b781e256ca7f9bfa30', 'https://html5.gamedistribution.com/48f3d14ced3646b781e256ca7f9bfa30/', 'assets/thumbs/48f3d14ced3646b781e256ca7f9bfa30.jpg', 'Race shiny sports cars on thrilling 3D tracks full of jumps, stunts, and intense battles. Explore exciting locations with unique challenges, perform daring tricks, upgrade and customize your cars, and test your skills in fast-paced arcade races. Enjoy high-speed action, stunning visuals, and nonstop adrenaline right in your browser.', 'Racing &amp; Driving', 9, 'publish', '2026-04-18 14:36:12'),
(11, 'Hidden Objects: Island Secrets', '7ffd63337f514fd1bb16fa54f15d1f68', 'https://html5.gamedistribution.com/7ffd63337f514fd1bb16fa54f15d1f68/', 'assets/thumbs/7ffd63337f514fd1bb16fa54f15d1f68.jpg', 'Hidden Objects: Island Secrets is an exciting hidden object game where magic and time intertwine in a thrilling adventure. Everything changed when a mysterious magical crystal activated, scattering objects across time! You\'ll enter a world of riddles, hidden objects, and temporal paradoxes.', 'Puzzle', 6, 'publish', '2026-04-18 14:36:12'),
(12, 'Solitaire Klondike: Eternal Russian Classic', 'c6eb54e8432a480bab89a517bd1a897e', 'https://html5.gamedistribution.com/c6eb54e8432a480bab89a517bd1a897e/', 'assets/thumbs/c6eb54e8432a480bab89a517bd1a897e.jpg', 'Rediscover the captivating world of Solitaire Klondike!\r\n\r\nThis timeless card game not only entertains but also enhances logical thinking, offering hours of engaging pastime. Play your favorite solitaire anytime, anywhere.\r\n\r\nJoin the community of enthusiasts and prove your mastery in Klondike!\r\n\r\nKeep an eye on the leaderboard and become the top player among all!', 'Cards', 1, 'publish', '2026-04-18 14:36:12'),
(13, 'Papas Burger Cook', '2aca341bfc73469285c8a674931a13d6', 'https://html5.gamedistribution.com/2aca341bfc73469285c8a674931a13d6/', 'assets/thumbs/2aca341bfc73469285c8a674931a13d6.jpg', 'Cook and travel through amazing burger restaurants, discover delicious recipes, prepare tasty meals, and serve hungry customers in the best burger shop.\r\nThis is a crazy cooking game full of fast kitchen action, burger fever, and food madness. Papas Burger Cook - fun cooking simulation game.\r\nBecome the ultimate burger chef, master every recipe, and reach the highest rank in this exciting food cooking adventure.', 'Cooking', 3, 'publish', '2026-04-18 14:36:14'),
(14, 'Dino Hunter King', 'a0dc9b2fcdb442faaaed550554ee370d', 'https://html5.gamedistribution.com/a0dc9b2fcdb442faaaed550554ee370d/', 'assets/thumbs/a0dc9b2fcdb442faaaed550554ee370d.jpg', 'Action-packed FPS games have long attracted players. Enjoy dinosaur hunting in Dino Hunter King. Enter a wild prehistoric world, become an elite hunter tracking powerful dinosaurs across open grasslands.', 'Adventure', 10, 'publish', '2026-04-18 14:36:15'),
(15, 'Food Tower Defense', '342812ed45d04664b62121a0ef09c2cb', 'https://html5.gamedistribution.com/342812ed45d04664b62121a0ef09c2cb/', 'assets/thumbs/342812ed45d04664b62121a0ef09c2cb.jpg', '? Welcome to Food Tower Defense – The Tastiest Tower Defense Ever! ?? Prepare your appetite and sharpen your strategy because Food Tower Defense is here to serve you the most delicious tower defense experience ever!', 'Casual', 4, 'publish', '2026-04-18 14:36:20'),
(16, 'Break the block there, Brainrot!', '08d7ed5c17d14024b28223eebfc9049f', 'https://html5.gamedistribution.com/08d7ed5c17d14024b28223eebfc9049f/', 'assets/thumbs/08d7ed5c17d14024b28223eebfc9049f.jpg', 'Break the block there, Brainrot! — Break blocks and collect the entire Brainrot collection.\r\nSell Brainrots to earn points to upgrade your axe.\r\nFind rare Brainrots in blocks. The further you go to collect the blocks, the greater the reward, but beware of the block guard.', 'Casual', 6, 'publish', '2026-04-18 14:36:21'),
(17, 'Car Jam Escape', '377ba74813184e51b6dc6d3f0d2b6e3b', 'https://html5.gamedistribution.com/377ba74813184e51b6dc6d3f0d2b6e3b/', 'assets/thumbs/377ba74813184e51b6dc6d3f0d2b6e3b.jpg', 'Car Jam Escape is a puzzle game where players clear a crowded parking lot by moving cars in the correct order. Each vehicle can only move forward in the direction it faces, so players must study the layout and plan carefully. The goal is to guide every car out without collisions or blockages. As levels progress, the puzzles become more complex, requiring logical thinking and strategy.', 'Puzzle', 8, 'publish', '2026-04-18 14:36:23'),
(18, 'Dinosaurs vs Asteroids', '489c7d19a55e4cfebfa779f2d57837c4', 'https://html5.gamedistribution.com/489c7d19a55e4cfebfa779f2d57837c4/', 'assets/thumbs/489c7d19a55e4cfebfa779f2d57837c4.jpg', 'Giant asteroids are crashing down on Earth. But the dinosaurs have a plan! They have special mounts on their backs where you can attach a variety of weapons: from miniguns and flamethrowers to alien shotguns and blasters. Additionally, there are special species of dinosaurs that can shoot powerful spikes or break asteroids with their claws.', 'Agility', 4, 'publish', '2026-04-18 14:36:25'),
(19, 'Ninja Wars: Battle Simulator', '16d4b103ede245a0af3eda7193f33e41', 'https://html5.gamedistribution.com/16d4b103ede245a0af3eda7193f33e41/', 'assets/thumbs/16d4b103ede245a0af3eda7193f33e41.jpg', 'Ninja Wars: Battle Simulator is a 3D strategy battle game where planning is the key to victory. Build your army of Swordsmen, Spearmen, and Archers, analyze enemy formations, and lead your ninja forces to triumph across challenging levels.', 'Battle', 5, 'publish', '2026-04-18 14:36:26'),
(20, 'EQ Test Puzzle', '6ff512507f1244b5812b84926aea6c40', 'https://html5.gamedistribution.com/6ff512507f1244b5812b84926aea6c40/', 'assets/thumbs/6ff512507f1244b5812b84926aea6c40.jpg', 'A puzzle game that tests emotional intelligence through emotion recognition and jigsaw puzzles. Match emotional icons, scenarios, and puzzle pieces to train your emotional awareness and problem-solving skills.', 'Puzzle', 8, 'publish', '2026-04-18 14:36:27'),
(21, 'Sid &amp; Ginny Y2K Glam Clash', 'e49735c5f31d42ca9403e7af7cac3723', 'https://html5.gamedistribution.com/e49735c5f31d42ca9403e7af7cac3723/', 'assets/thumbs/e49735c5f31d42ca9403e7af7cac3723.jpg', 'Welcome to the Y2K style fashion world! Two charismatic heroines are waiting for you, ready to try on fashion trends from the 2000s. Create spectacular makeup for them with lip gloss, shining shadows and glossy skin; choose stylish hairstyles - from smooth straight hair to playful ponytails and fashionable hairpins. Experiment with low-cut jeans, crop tops, mini skirts, shiny fabrics, and bold combinations. Complete the resulting image with iconic accessories of those years.', 'Dress-up', 6, 'publish', '2026-04-18 14:36:35'),
(22, 'Pyramidz2', '651ca0101b5e4c2da461a51abd8d5772', 'https://html5.gamedistribution.com/651ca0101b5e4c2da461a51abd8d5772/', 'assets/thumbs/651ca0101b5e4c2da461a51abd8d5772.jpg', 'PyramidZ 2 is, as the name suggests, the sequel to PyramidZ. It\'s a Match-3 game where you have to slide a row or column to align Egyptian symbols. This version is faster and allows for more combos.', 'Match-3', 6, 'publish', '2026-04-18 14:36:36'),
(23, 'Farm Animal Sort Puzzle', '47a0a5a7b1d8499ab5ab0cef4499f72e', 'https://html5.gamedistribution.com/47a0a5a7b1d8499ab5ab0cef4499f72e/', 'assets/thumbs/47a0a5a7b1d8499ab5ab0cef4499f72e.jpg', 'Welcome to Farm Animal Sort Puzzle, a fun and relaxing casual puzzle game set on a lively farm. Your mission is simple but addictive: match the appropriate animal or vegetable to the customer\'s needs. Sort adorable farm animals into the correct spaces and enjoy the satisfying challenge of smart organization.', 'Puzzle', 5, 'publish', '2026-04-18 14:36:38'),
(24, 'Animal Swipe', '96936ee47199450096ce978ca8d287e3', 'https://html5.gamedistribution.com/96936ee47199450096ce978ca8d287e3/', 'assets/thumbs/96936ee47199450096ce978ca8d287e3.jpg', 'Animal Swipe is a fun and addictive puzzle game where players match adorable animal pairs on a colorful board. With easy-to-learn controls and exciting power-ups, the game offers a challenge for both casual and strategic players. Use your wits and boosts to clear levels and achieve your objectives!', 'Match-3', 6, 'publish', '2026-04-18 14:36:40'),
(25, 'Ink Shop: Dress &amp; Tattoo', '1a54e3218d574573a05e778df682913a', 'https://html5.gamedistribution.com/1a54e3218d574573a05e778df682913a/', 'assets/thumbs/1a54e3218d574573a05e778df682913a.jpg', 'Welcome to Ink Shop: Dress &amp; Tattoo, a unique and immersive game that lets you unleash your inner tattoo artist. This isn\'t just any game; it\'s your gateway to a world where art meets relaxation, and where your creativity can truly shine. Prepare to immerse yourself in the satisfying and intricate process of tattooing, all at the tip of your fingers!', 'Casual', 5, 'publish', '2026-04-18 14:36:40'),
(26, 'Yoga Master', 'a2b786db40474e8ba3961e76b9ca3b45', 'https://html5.gamedistribution.com/a2b786db40474e8ba3961e76b9ca3b45/', 'assets/thumbs/a2b786db40474e8ba3961e76b9ca3b45.jpg', 'Yoga is a great way to improve your quality of life. It is also a great way to entertain yourself in this game: Yoga Master.\r\n\r\nYoga Master is an addictive 3D running game with different levels that will challenge even the fastest reflex.', 'Casual', 10, 'publish', '2026-04-18 14:36:40'),
(27, 'Sort Balls - Cones', '8c028d59fd2946289d5582a4eee6f850', 'https://html5.gamedistribution.com/8c028d59fd2946289d5582a4eee6f850/', 'assets/thumbs/8c028d59fd2946289d5582a4eee6f850.jpg', 'Immerse yourself in a calming logic puzzle where your goal is to sort colored balls into separate tubes. Plan each move carefully so that every tube contains balls of only one color. The straightforward mechanics gradually evolve into more challenging levels that test your focus and strategic thinking.', 'Puzzle', 8, 'publish', '2026-04-18 14:36:41'),
(28, 'i8 City Driver', 'f6acd919192c441c9aca2d20a18e04c6', 'https://html5.gamedistribution.com/f6acd919192c441c9aca2d20a18e04c6/', 'assets/thumbs/f6acd919192c441c9aca2d20a18e04c6.jpg', 'Get ready to skid the wheels of a stunning supercar through an expansive morning city map! Customize and upgrade your sports car with cool upgradables and become the best driver in the city. Take your dog with you in 3 driving challenges and conquer the missions together. Use nitro to beat slow traffic and beat all speed, stunt and drift triggers spread across the map. Are you ready to show your driving skills? Prove yourself!', 'Racing &amp; Driving', 4, 'publish', '2026-04-18 14:36:46'),
(29, 'World Cup 2026 Soccer Game', 'ad37a85f16e246fabdc818f375a5eb45', 'https://html5.gamedistribution.com/ad37a85f16e246fabdc818f375a5eb45/', 'assets/thumbs/ad37a85f16e246fabdc818f375a5eb45.jpg', 'Choose your national team and enter the excitement of the World Cup! \r\nPlay as your favorite heroes like Cristiano Ronald, Lionel Messi or Kylian Mbappe and jump into fast-paced 1v1 soccer battles to claim the cup! \r\nDefend your goal, watch for the perfect opening, and strike to score!\r\nChallenge the CPU or compete against friends, sharpen your skills, and climb your way to the top. Victory is just a goal away!', 'Sports', 4, 'publish', '2026-04-18 14:36:47'),
(30, 'Home Block Story', 'f32dfc95b9054cccbd6b187f9596e220', 'https://html5.gamedistribution.com/f32dfc95b9054cccbd6b187f9596e220/', 'assets/thumbs/f32dfc95b9054cccbd6b187f9596e220.jpg', 'Step into a world of renovation! Match blocks, clear the board and unlock new decor to design your house just the way you want. With each new challenge, show your unique style and make your dream home a reality.', 'Puzzle', 12, 'publish', '2026-04-18 14:36:48'),
(31, 'My Arcade Center 2', '54aca2f7503041c0bd97e74d7e316a67', 'https://html5.gamedistribution.com/54aca2f7503041c0bd97e74d7e316a67/', 'assets/thumbs/54aca2f7503041c0bd97e74d7e316a67.jpg', 'My Arcade Center 2 is a fast-paced arcade management tycoon game.\r\n\r\nBuild, customize, and expand your own arcade across 7 unique maps. Earn by day, upgrade by night, unlock new machines, hire staff, optimize layouts, and grow your business. Switch between centers anytime, unlock new characters and skins, complete daily missions, and boost your long-term progress with rewarding upgrades.', 'Casual', 4, 'publish', '2026-04-18 14:36:51'),
(32, 'Dead Paradise', '5612231ac5184ecda617c334cbb46878', 'https://html5.gamedistribution.com/5612231ac5184ecda617c334cbb46878/', 'assets/thumbs/5612231ac5184ecda617c334cbb46878.jpg', 'Dead Paradise: Race Shooter is an apocalyptic car game where you drive, shoot enemies, and try to survive until the finish. Completing levels gives you coins to upgrade your car’s missiles, armor, engine, and fuel. You can also buy new vehicles, take missions, and complete daily tasks for extra rewards. Use your resources wisely to make your car stronger and improve your chances of survival.', 'Racing &amp; Driving', 5, 'publish', '2026-04-18 14:36:52'),
(33, 'Jumper\'s Quest', 'f0f4d71949e347249950f163cfb40d4b', 'https://html5.gamedistribution.com/f0f4d71949e347249950f163cfb40d4b/', 'assets/thumbs/f0f4d71949e347249950f163cfb40d4b.jpg', 'Jump into a world full of unique obstacles that will test you both mentally and physically. Your quick thinking and reflexes will be put to the test as you decipher puzzles and navigate through each level with finesse.\r\n\r\nEncounter a diverse array of enemies, each with their own unique challenges that you must conquer. Intuitive one-touch controls empower you to effortlessly jump through the levels in record time.', 'Puzzle', 6, 'publish', '2026-04-18 14:36:53'),
(34, 'Hospital Inc', 'd0148861138c4ebd94045cf139a5d5eb', 'https://html5.gamedistribution.com/d0148861138c4ebd94045cf139a5d5eb/', 'assets/thumbs/d0148861138c4ebd94045cf139a5d5eb.jpg', 'Step into the fast-paced world of Hospital Inc, an exciting management simulator. This addictive idle tycoon casual game lets you build, expand, and manage your own hospital while earning profits even when you\'re away.', 'Simulation', 6, 'publish', '2026-04-18 14:37:00'),
(35, 'Bimka Drive - Smash cars into splinters!', 'b210ded71717487780f38cc96f5d20b4', 'https://html5.gamedistribution.com/b210ded71717487780f38cc96f5d20b4/', 'assets/thumbs/b210ded71717487780f38cc96f5d20b4.jpg', 'Game created in the style of racing, where you will have no restrictions. But it\'s not that simple. The fact is that the basis here is based on the physics of actions, because every collision of your car with any obstacle will significantly affect its both external and internal condition. The damage model is made very realistically. Your choice will be a variety of different types of car models that you can test on all kinds of racing tracks. The game is very similar to &quot;BeamNG Drive&quot;.', 'Racing &amp; Driving', 5, 'publish', '2026-04-18 14:37:00'),
(36, 'Liquid Sort Deluxe', '58e6757fa9544adaa4a7ea037c4ae444', 'https://html5.gamedistribution.com/58e6757fa9544adaa4a7ea037c4ae444/', 'assets/thumbs/58e6757fa9544adaa4a7ea037c4ae444.jpg', 'Liquid Sort Deluxe is a relaxing and addictive color sorting puzzle game where you sort colorful liquids into tubes until each tube contains only one color. Plan your moves carefully and challenge your brain with unlimited levels. Unlock an extra tube by watching a short reward ad to make the puzzle easier, or get unlimited time to complete tricky levels.', 'Puzzle', 8, 'publish', '2026-04-18 14:37:01'),
(37, 'Gun Shooting Games Sniper 3D', 'c8a93a1e1e964e11b3d9803cad9e9c2c', 'https://html5.gamedistribution.com/c8a93a1e1e964e11b3d9803cad9e9c2c/', 'assets/thumbs/c8a93a1e1e964e11b3d9803cad9e9c2c.jpg', 'Step into the battlefield and test your precision in Gun Shooting Games: Sniper 3D, an exciting fps experience packed with nonstop action. This immersive first person shooting game puts you in the role of an elite sniper armed with powerful weapons and challenging missions.', 'Shooter', 5, 'publish', '2026-04-18 14:37:01'),
(38, 'Obby: Tsunami Escape +1 by Car', 'b0dceb9ce1b248f797cebcc0faa95005', 'https://html5.gamedistribution.com/b0dceb9ce1b248f797cebcc0faa95005/', 'assets/thumbs/b0dceb9ce1b248f797cebcc0faa95005.jpg', 'A giant tsunami is approaching - and only you can outrun it! Dodge the waves, upgrade your car, and race to the finish line. The faster you get, the further you can go.\r\n\r\nBuy new cars - each one gives you more speed, control, and capabilities.\r\nUpgrade your vehicles to survive the most challenging races.\r\nDefeat brainrots - from common to rare and legendary ones.\r\nPractice, improve your reactions, and find the perfect strategy.', 'Racing &amp; Driving', 4, 'publish', '2026-04-18 14:37:04'),
(39, 'Romantic K-Pop Transformation', 'd12c496117f64174bc2b9800a285f92f', 'https://html5.gamedistribution.com/d12c496117f64174bc2b9800a285f92f/', 'assets/thumbs/d12c496117f64174bc2b9800a285f92f.jpg', 'In this game, the stars of K-pop are preparing for a romantic transformation. Create a unique images for girls, full of tenderness and brilliance of the stage. Experiment with makeup; change the hairstyles and hair color of the girls. Choose the perfect outfit: from cute dresses and stylish tops to trendy skirts and trousers. Complete the look with fashion accessories. Compare the resulting images and decide which of the heroines of the game has become the real queen of romantic K-pop style.', 'Dress-up', 5, 'publish', '2026-04-18 14:37:05'),
(40, 'Cow Jam Farm puzzle', '284894477327459b95bf8e2a54c9d681', 'https://html5.gamedistribution.com/284894477327459b95bf8e2a54c9d681/', 'assets/thumbs/284894477327459b95bf8e2a54c9d681.jpg', 'In Cow Jam Farm Puzzle, the peaceful farm turns into a tricky traffic jam that only your logic skills can solve. Cows are stuck in crowded paths, and your mission is to help every one of them escape safely.', 'Puzzle', 6, 'publish', '2026-04-18 14:37:08'),
(41, 'Stick Kill 3D', '724f9f245a0e47308239bf37795141e6', 'https://html5.gamedistribution.com/724f9f245a0e47308239bf37795141e6/', 'assets/thumbs/724f9f245a0e47308239bf37795141e6.jpg', 'Play as a stickman armed with a pistol in this puzzle-based shooter, where precision and clever thinking are key. Find the right angle, line up your shots, and eliminate enemies in creative ways. Each level becomes more challenging, testing your accuracy and problem-solving skills.', 'Puzzle', 7, 'publish', '2026-04-18 14:37:12'),
(42, 'Diamondz', '4f0be8dddab5440b9011a238ac03db35', 'https://html5.gamedistribution.com/4f0be8dddab5440b9011a238ac03db35/', 'assets/thumbs/4f0be8dddab5440b9011a238ac03db35.jpg', 'DiamondZ is a special variant of Match-3. Here, the goal is not to directly manipulate jewels on the board but to insert them on the left or right side to eliminate groups and make diamonds fall into the mine carts. Help the little miner collect as much wealth as possible!', 'Match-3', 5, 'publish', '2026-04-18 14:37:14'),
(43, 'Brawl Stars Battle', 'fab6523bfe89443d89f7425f946c691d', 'https://html5.gamedistribution.com/fab6523bfe89443d89f7425f946c691d/', 'assets/thumbs/fab6523bfe89443d89f7425f946c691d.jpg', 'Brawl Stars Battle is an exciting action shooting game where you control powerful heroes armed with guns and special abilities to defeat opponents in fast-paced combat! Select 3v3 battle mode and fight alongside your teammates. The team that kills fifteen opponents first wins. Use guns and powerful abilities in intense battles.', 'Adventure', 6, 'publish', '2026-04-18 14:37:15'),
(44, 'Two RX7 Drifters', 'f85eee6b515c4aecb0ef6c6563d05e39', 'https://html5.gamedistribution.com/f85eee6b515c4aecb0ef6c6563d05e39/', 'assets/thumbs/f85eee6b515c4aecb0ef6c6563d05e39.jpg', 'Drift through 3 stunning drift tracks and show how well you can steer the wheels of a powerful rx7. Go head to head with your friend in a drift battle and see whose a better drift racer, customize your ride with stunning body colors, underglows and cool rims. Are you ready to showcase your drifting skills?', 'Racing &amp; Driving', 5, 'publish', '2026-04-18 14:37:16'),
(45, 'Slicer Duo', '4aefd2cd9aba4cae8c1e839dedfccadd', 'https://html5.gamedistribution.com/4aefd2cd9aba4cae8c1e839dedfccadd/', 'assets/thumbs/4aefd2cd9aba4cae8c1e839dedfccadd.jpg', 'Slicer Duo is a satisfying ASMR game where precision, timing, and rhythm come together in a sharp slicing adventure. Move through level-based stages, cut through fruits and all kinds of objects, collect points, and try to keep your knife in motion for as long as possible. While the controls are simple, every section demands focus because one bad move can send your knife straight into danger.', 'Agility', 7, 'publish', '2026-04-18 14:37:16'),
(46, 'Number Bubble Shooter Wild West', 'e676d4440f084d9e9d241781cbb494b1', 'https://html5.gamedistribution.com/e676d4440f084d9e9d241781cbb494b1/', 'assets/thumbs/e676d4440f084d9e9d241781cbb494b1.jpg', 'Saddle up for a Wild West number bubble shooter! Shoot and match numbers to merge them into higher values, creating bigger combos and clearing the board. Plan your shots, stack smart, and ride through dusty levels full of challenge and fun!', 'Bubble Shooter', 4, 'publish', '2026-04-18 14:37:17'),
(47, 'Tic Tac Toe Merge', '838b62dc8b334050b6c169a294673f72', 'https://html5.gamedistribution.com/838b62dc8b334050b6c169a294673f72/', 'assets/thumbs/838b62dc8b334050b6c169a294673f72.jpg', 'Tic-Tac-Toe Merge is a revolutionary twist on the classic game! Unlike traditional tic-tac-toe, pieces have power levels from 1 to 3. Place higher-level pieces to capture your opponent\'s weaker ones!\r\n\r\nMERGE TO DOMINATE\r\nCombine two level-1 pieces to create level-2, and two level-2 to forge powerful level-3. Create chain reactions when 3+ same-level pieces align — they merge into an even stronger piece!', 'Boardgames', 2, 'publish', '2026-04-18 14:37:21'),
(48, 'Cute Craft Lab', '89129ae061a342cdb454d6ae599a2b6b', 'https://html5.gamedistribution.com/89129ae061a342cdb454d6ae599a2b6b/', 'assets/thumbs/89129ae061a342cdb454d6ae599a2b6b.jpg', 'Step into the colorful world of Cute Craft Lab, a super casual game where creativity shines and every girl can become a true crafting designer. If you love relaxing gameplay mixed with adorable creativity, this cute design adventure is made just for you. In Cute Craft Lab, enter a magical workshop filled with charming tools, sparkling decorations, and endless crafting possibilities.', 'Dress-up', 5, 'publish', '2026-04-18 14:37:29'),
(49, 'Goods Sorting Shopping Master', 'f238798742a540e187939910790bd729', 'https://html5.gamedistribution.com/f238798742a540e187939910790bd729/', 'assets/thumbs/f238798742a540e187939910790bd729.jpg', 'In Goods Sorting Shopping Master, you organize messy goods by moving and matching them into neat groups. It’s a fun puzzle game that combines smart thinking with relaxing gameplay. In the game, you’ll face shelves filled with mixed goods such as drinks, snacks, and daily items. Match and sort three identical items to clear the space and proceed, based on the customer\'s needs. Manage space carefully to keep sorting.', 'Puzzle', 6, 'publish', '2026-04-18 14:37:30'),
(50, 'Hunter Underwater Spearfishing', '37080f0a91924d12b91ef072e965497f', 'https://html5.gamedistribution.com/37080f0a91924d12b91ef072e965497f/', 'assets/thumbs/37080f0a91924d12b91ef072e965497f.jpg', 'Hunter Underwater Spearfishing is an immersive simulator hunting game that takes you deep beneath the ocean for an exciting underwater adventure. Grab your spearfishing arrow, dive in, and experience the thrill of becoming a true underwater hunter!', 'Adventure', 6, 'publish', '2026-04-18 14:37:31'),
(51, 'Find Hidden Cats', '892fa29a7d4145958b37ea309752bf1b', 'https://html5.gamedistribution.com/892fa29a7d4145958b37ea309752bf1b/', 'assets/thumbs/892fa29a7d4145958b37ea309752bf1b.jpg', 'Explore charming black-and-white scenes inspired by iconic European cities in this relaxing yet addictive hidden object game. Every corner is packed with clever details and playful surprises - can you spot all 20 mischievous cats hiding in plain sight? Test your observation skills, take your time, and enjoy the satisfying thrill of discovering each well-hidden feline!', 'Casual', 7, 'publish', '2026-04-18 14:37:39'),
(52, 'Dark Myth: Monkey Merge', '5b5ee9d5712c4d88b68ebeb3d1c25ebd', 'https://html5.gamedistribution.com/5b5ee9d5712c4d88b68ebeb3d1c25ebd/', 'assets/thumbs/5b5ee9d5712c4d88b68ebeb3d1c25ebd.jpg', 'Merge warriors, build your army, and fight through hordes of monsters as the Monkey King! Your master and companions have been captured — combine strategy and action to rescue them all. From Common to Legendary, every merge makes you stronger.', 'Adventure', 6, 'publish', '2026-04-18 14:37:41'),
(53, 'Soccer Duel', '3c96c6a76dc94cedbe3d4bc519e0a7ce', 'https://html5.gamedistribution.com/3c96c6a76dc94cedbe3d4bc519e0a7ce/', 'assets/thumbs/3c96c6a76dc94cedbe3d4bc519e0a7ce.jpg', 'An exciting game in the style of table football, which you can play both alone and with friends on the same device or over the network.', 'Football', 10, 'publish', '2026-04-18 14:37:42'),
(54, 'Dessert DIY', 'fbfeecb1e2344c839c7a47096f974fe5', 'https://html5.gamedistribution.com/fbfeecb1e2344c839c7a47096f974fe5/', 'assets/thumbs/fbfeecb1e2344c839c7a47096f974fe5.jpg', 'Step into a sweet little food studio and craft desserts for hungry customers! Follow simple step-by-step recipes, pick the right ingredients, and assemble tasty treats exactly as requested. Satisfy each guest to earn coins, then spend your rewards in the shop to unlock more items, upgrades, and delicious options. Easy to learn, relaxing to play, and full of colorful desserts!', 'Casual', 4, 'publish', '2026-04-18 14:37:44'),
(55, 'Archery Master - Bow and Arrow', '7d11673fe1224713984cee86d2ba3bca', 'https://html5.gamedistribution.com/7d11673fe1224713984cee86d2ba3bca/', 'assets/thumbs/7d11673fe1224713984cee86d2ba3bca.jpg', 'Join archery adventure and become a bowmaster! Aim, shoot and hit the bullseye!\r\n\r\nPick your bow, defeat other archery masters and don’t let them take you down! Join in this fun and challenging adventure and have fun. Bow masters can really challenge your casual game skills but have no fear! If you enjoy bow and arrow games, then prepare to defeat other bow masters, earn coins, score, and become the ultimate bow master!', 'Shooter', 10, 'publish', '2026-04-18 14:37:45'),
(56, 'Mafia Sniper Crime Shooting', '5083a63adc7248d8b04dd72cde2eb78c', 'https://html5.gamedistribution.com/5083a63adc7248d8b04dd72cde2eb78c/', 'assets/thumbs/5083a63adc7248d8b04dd72cde2eb78c.jpg', 'Ready to become the coldest, deadliest sniper in the entire city? Mafia Sniper Crime Shooting is a FPS action shooting simulator where you complete high-risk missions. Use powerful guns to eliminate dangerous mafia targets.', 'Shooter', 7, 'publish', '2026-04-18 14:37:46'),
(57, 'Earth Defender', '5916a7fd3b4843018f2f96c7780017f2', 'https://html5.gamedistribution.com/5916a7fd3b4843018f2f96c7780017f2/', 'assets/thumbs/5916a7fd3b4843018f2f96c7780017f2.jpg', 'Earth Defender is a fast-paced arcade game where you control a spaceship orbiting around planet Earth. Deadly meteors are flying toward the planet, and it\'s your mission to stop them before they crash into Earth.\r\n\r\nYour ship circles the planet. Time your moves carefully and collide with incoming meteors to destroy them\r\n\r\nTap to change your orbit direction and intercept as many meteors as possible. Survive the meteor storm and defend Earth for as long as you can!', 'Casual', 10, 'publish', '2026-04-18 14:37:51'),
(58, 'Arcade GP', '3fc01c17076c44149e3e4b6d79b3134f', 'https://html5.gamedistribution.com/3fc01c17076c44149e3e4b6d79b3134f/', 'assets/thumbs/3fc01c17076c44149e3e4b6d79b3134f.jpg', 'ARCADE GP is a retro-style top-down Formula 1 racing game with strategic tire management and pit stop mechanics. Race against AI opponents, manage tire wear, and make tactical decisions to claim victory!', 'Racing &amp; Driving', 10, 'publish', '2026-04-18 14:37:51'),
(59, 'Ayla World Princess life', 'b669b89f311c4cecab7f740a744484da', 'https://html5.gamedistribution.com/b669b89f311c4cecab7f740a744484da/', 'assets/thumbs/b669b89f311c4cecab7f740a744484da.jpg', 'Step into the magical world of Ayla World: Princess Life, where you can live the ultimate princess adventure! This exciting game lets you dress up your avatar, create stunning outfits, and design beautiful nails with endless styles.', 'Dress-up', 10, 'publish', '2026-04-18 14:37:52'),
(60, 'Cars with Guns: Wasteland Showdown', '0bd1e5d745554a4c9d1defd57dd91aa5', 'https://html5.gamedistribution.com/0bd1e5d745554a4c9d1defd57dd91aa5/', 'assets/thumbs/0bd1e5d745554a4c9d1defd57dd91aa5.jpg', 'Accept the challenge of the post-apocalyptic wasteland. Take on contracts, earn money and reputation, and collect valuable loot.\r\nSurvival belongs to those with the fastest ride and the biggest gun.', 'Racing &amp; Driving', 10, 'publish', '2026-04-18 14:37:53'),
(61, 'Lost Things - Hidden Objects', 'e2bc621dcad54cfa91e86c241167a0d2', 'https://html5.gamedistribution.com/e2bc621dcad54cfa91e86c241167a0d2/', 'assets/thumbs/e2bc621dcad54cfa91e86c241167a0d2.jpg', 'Embark on an exciting adventure where your powers of observation are your main tool!\r\nThis is a relaxing hidden object game created for those who appreciate slow-paced gameplay and enjoy exploring detailed worlds. Forget about time pressure! Here you can explore huge, colorful maps filled with hundreds of artfully hidden objects at your own pace.', 'Puzzle', 11, 'publish', '2026-04-18 14:37:55'),
(62, 'Clash Crowd Game', 'a204ab90b6f641569b6d5f4b0f62072e', 'https://html5.gamedistribution.com/a204ab90b6f641569b6d5f4b0f62072e/', 'assets/thumbs/a204ab90b6f641569b6d5f4b0f62072e.jpg', 'Clash Crowd Game is an addictive arcade runner game where you tap to run, survive obstacles, and reach the destination. Control your crowd, avoid traps, and face thrilling challenges in every level. Easy controls, engaging gameplay, and colorful 3D graphics make this game perfect for quick fun. Run smart, grow your crowd, and prove your survival skills.', 'Casual', 7, 'publish', '2026-04-18 14:37:56'),
(63, 'Dream Kitchen', 'd2ce23ee185643db8f3831aba3971c1c', 'https://html5.gamedistribution.com/d2ce23ee185643db8f3831aba3971c1c/', 'assets/thumbs/d2ce23ee185643db8f3831aba3971c1c.jpg', 'Dream Kitchen is a fun and fast-paced restaurant simulation game inspired by shawarma-style cooking gameplay. Take customer orders, cook the right food, and serve every dish on time to keep customers happy. Complete levels with 3-star ratings, earn coins, upgrade your kitchen equipment, and unlock new recipes. Explore multiple themed chapters, including a Pancake Shop, Street Stall, Fast Food Restaurant, and Western Restaurant, each with unique dishes and challenges!', 'Cooking', 5, 'publish', '2026-04-18 14:37:56'),
(64, 'Mahjong build INSERT INTO `games` (`id`, `title`, `slug`, `iframe_url`, `image_url`, `description`, `category`, `views`, `status`, `created_at`) VALUES
(93, 'Animal Racing Idle Park', '6949c2adc8c64879bf9676109eb9bfea', 'https://html5.gamedistribution.com/6949c2adc8c64879bf9676109eb9bfea/', 'assets/thumbs/6949c2adc8c64879bf9676109eb9bfea.jpg', 'Animal Racing: Idle Park is an addictive racing animal transform game that will keep you playing for hours. In this game, you’ll train multiple animal racers such as lions, eagles, orangutans, dolphins, and more!', 'Casual', 4, 'publish', '2026-04-19 08:47:27'),
(94, 'Dart Hero', '1412394a892d49f5a41763899ca6354e', 'https://html5.gamedistribution.com/1412394a892d49f5a41763899ca6354e/', 'assets/thumbs/1412394a892d49f5a41763899ca6354e.jpg', 'Do you have the reflexes of a Hero? Step up to the line in Dart Hero, the fast-paced arcade game where timing is everything. Forget about complex aiming—just wait for the perfect moment and Tap to Shoot!', 'Casual', 8, 'publish', '2026-04-19 08:47:28'),
(95, 'Obby Parkour Racing', 'b9238092e03340e395f3985be2fadba1', 'https://html5.gamedistribution.com/b9238092e03340e395f3985be2fadba1/', 'assets/thumbs/b9238092e03340e395f3985be2fadba1.jpg', 'Welcome to Obby Parkour Racing – the game where speed, agility, and style collide to create the ultimate racing challenge!\r\n\r\nJump, grind, and dodge through dynamic obstacle courses on your snowboard! Prove your mastery in a world where parkour isn\'t just on foot\r\nit\'s on a board. Every race is a new test, and only the fastest and most agile champions will claim victory.', 'Casual', 7, 'publish', '2026-04-19 08:47:30'),
(96, 'TapKO', 'ac6a598abb184816af3be3acec546fb5', 'https://html5.gamedistribution.com/ac6a598abb184816af3be3acec546fb5/', 'assets/thumbs/ac6a598abb184816af3be3acec546fb5.jpg', 'One-tap fighter game. From the creators of Fruit Ninja and Jetpack Joyride, get ready to rumble with TapKO - the knockout idle game that packs a punch! Jab, bob, and weave your way to the top, and train your fighter to become the ultimate boxer.', 'Casual', 7, 'publish', '2026-04-19 08:47:33'),
(97, 'My Cat Restaurant', 'e842fa22ef0e4801840db85cbeba72d7', 'https://html5.gamedistribution.com/e842fa22ef0e4801840db85cbeba72d7/', 'assets/thumbs/e842fa22ef0e4801840db85cbeba72d7.jpg', 'Welcome to My Cat Restaurant, a casual kids cooking simulator game that you can play for free. Act as a chef and restaurant manager. Take orders, cook food, serve customers, and collect money. Plan your moves and workload in advance, and figure out an efficient routine.', 'Casual', 6, 'publish', '2026-04-19 08:47:34'),
(98, 'Obby Yard Sale', '92245cd524f44468bffc0b790f855e80', 'https://html5.gamedistribution.com/92245cd524f44468bffc0b790f855e80/', 'assets/thumbs/92245cd524f44468bffc0b790f855e80.jpg', 'Open your own trade right in the yard of your house! Order boxes with mysterious goods, unpack them and put them up for sale to passers-by. Each item can be common or rare and legendary, which makes every purchase special.\r\nKeep an eye on your yard: buyers not only buy goods, but also try to steal them. Your task is to stop the thief in time and collect a collection of all types of items, turning simple yard trading into an exciting adventure.', 'Casual', 6, 'publish', '2026-04-19 08:47:36'),
(99, 'Fish Love Pins', 'bc1f30dfe09445d7846658feaeaacb4d', 'https://html5.gamedistribution.com/bc1f30dfe09445d7846658feaeaacb4d/', 'assets/thumbs/bc1f30dfe09445d7846658feaeaacb4d.jpg', 'Fish Love Pins is a physics-based game that requires players to actively use their brains to figure out how to complete each level. The game is very easy to play, but as you progress through the levels, the difficulty gradually increases.', 'Casual', 5, 'publish', '2026-04-19 08:47:38'),
(100, 'Accurate 2D', '28cddc44643242c49335fbe7dbd4354d', 'https://html5.gamedistribution.com/28cddc44643242c49335fbe7dbd4354d/', 'assets/thumbs/28cddc44643242c49335fbe7dbd4354d.jpg', 'Accurate 2D is a fun 2D game where the player must destroy all his enemies.\r\n\r\nFeatures:\r\n• many levels;\r\n• casual gameplay;\r\n• good graphics.', 'Casual', 6, 'publish', '2026-04-19 08:47:41'),
(101, 'Italian Brainrot Drag Merge Puzzle', '55785052e82e4de482f84cdccc1be4bb', 'https://html5.gamedistribution.com/55785052e82e4de482f84cdccc1be4bb/', 'assets/thumbs/55785052e82e4de482f84cdccc1be4bb.jpg', 'A Revolutionary Jigsaw Experience. Each level, one image is randomly selected and split into 3×3, 4×4, 5×5, or 6×6 pieces, then completely shuffled. Your goal is simple: restore the picture by placing every piece in its correct position. But this is no ordinary jigsaw. When two neighboring pieces are placed correctly next to each other, they merge into a single movable cluster. Instead of slow, one-by-one placement, you can drag any piece or merged group onto another to instantly swap positions.', 'Casual', 5, 'publish', '2026-04-19 08:47:49'),
(102, 'Shadowman Runner', '7cc51214cfd74d40b405013d0f8eda6c', 'https://html5.gamedistribution.com/7cc51214cfd74d40b405013d0f8eda6c/', 'assets/thumbs/7cc51214cfd74d40b405013d0f8eda6c.jpg', 'Shadowman Runner is a dark, atmospheric endless runner inspired by the minimalist silhouette style of Limbo and the fast-paced arcade spirit of games like Soul Knight and Alto’s Adventure. Set in a mysterious black-and-shadow world, the game challenges your reflexes, timing, and focus.\r\nYou play as a lone runner sprinting through a dangerous jungle landscape. Your goal is simple yet addictive: run as far as you can, collect potions to score points, and survive.', 'Casual', 5, 'publish', '2026-04-19 08:47:53'),
(103, 'Valentines Hidden Alphawords', '41fb9c32a74c4068acf0a04d08b36fd6', 'https://html5.gamedistribution.com/41fb9c32a74c4068acf0a04d08b36fd6/', 'assets/thumbs/41fb9c32a74c4068acf0a04d08b36fd6.jpg', 'Valentines Hidden Alphawords is a charming and relaxing Valentine’s Day–themed puzzle game where love meets word discovery. Explore beautifully designed romantic scenes filled with hidden letters waiting to be found. Each completed level reveals a sweet and heartwarming caption that perfectly matches the image. With 30 engaging levels, increasing challenges, and a ticking clock with useful hints, the game keeps players entertained while celebrating the spirit of love.', 'Casual', 6, 'publish', '2026-04-19 08:47:55'),
(104, 'Italian Animals: Create Your Own Brainrot!', 'f18ca724486f4049a8f92ce7387f7826', 'https://html5.gamedistribution.com/f18ca724486f4049a8f92ce7387f7826/', 'assets/thumbs/f18ca724486f4049a8f92ce7387f7826.jpg', 'Create your own crazy Brainrot! Mix bodies, heads, and legs to create absurd Italian creatures, listen to their &quot;passports&quot; and keep your masterpieces as keepsakes. Creative chaos is in your hands!', 'Casual', 6, 'publish', '2026-04-19 08:47:57'),
(105, 'Super Brain', '43a1c23743184ec8befbb7a221c87c93', 'https://html5.gamedistribution.com/43a1c23743184ec8befbb7a221c87c93/', 'assets/thumbs/43a1c23743184ec8befbb7a221c87c93.jpg', 'In the game, you\'ll control a character sprinting down a track, but your path is blocked by a series of &quot;Gates of Knowledge.&quot; Each gate presents an interesting question, and you must choose the lane corresponding to the correct answer in a short amount of time to pass through. A wrong choice ends the run! As you get faster, the questions become trickier. This game tests not only your knowledge but also your on-the-spot reaction skills. Come join this dual challenge of brain and speed!', 'Casual', 6, 'publish', '2026-04-19 08:47:58'),
(106, 'Cookie monster', '3bfa9e2ebbab4259a9799be4b00a5dae', 'https://html5.gamedistribution.com/3bfa9e2ebbab4259a9799be4b00a5dae/', 'assets/thumbs/3bfa9e2ebbab4259a9799be4b00a5dae.jpg', 'What more could you ask for?! Puzzle, brain teaser, monsters, snacks...wait what? That\'s right MONSTERS and SNACKS! Feed the hungry monsters snacks to pass the level! You have to make sure all the snacks get into the monster\'s mouth though or you will see a sad face! Let\'s keep these monsters happy! If you like the game, leave us a review! That will help us continue to bring you many more challenging levels, new monsters, maybe some new twizzler lines.', 'Casual', 4, 'publish', '2026-04-19 08:48:01'),
(107, 'Fashion Stylist Salon Makeover', 'bf627763f84546df90b07a3379ab6902', 'https://html5.gamedistribution.com/bf627763f84546df90b07a3379ab6902/', 'assets/thumbs/bf627763f84546df90b07a3379ab6902.jpg', 'Do you want to create your own fashion styles? Join our best hair salon simulator game and enjoy the utmost fun. You will act as a fashion stylist who does haircuts, hairstyling, and skin care. Welcome customers with different requirements and use your hairstyling skills to make them satisfied and happy!', 'Casual', 6, 'publish', '2026-04-19 08:48:08'),
(108, 'Obby Football Soccer 3D', '7c03475573ec4a31b3926cc32b29bff1', 'https://html5.gamedistribution.com/7c03475573ec4a31b3926cc32b29bff1/', 'assets/thumbs/7c03475573ec4a31b3926cc32b29bff1.jpg', 'Online football / soccer and real sport — play with friends or random opponents.\r\nPenalties and matches — score amazing goals, save shots, and become your team’s hero.\r\nObby challenges — train your reaction and speed while passing football obstacles.\r\nColorful 3D graphics and the atmosphere of a real stadium.\r\n\r\nGo from rookie to champion. Prove that you are the best player in the world of football and sport.', 'Casual', 7, 'publish', '2026-04-19 08:48:12'),
(109, 'Tap It Away 3D', '87cb43c5492049b49b01491248d9ced1', 'https://html5.gamedistribution.com/87cb43c5492049b49b01491248d9ced1/', 'assets/thumbs/87cb43c5492049b49b01491248d9ced1.jpg', 'Tap It Away 3D is a fun and relaxing 3D block puzzle game. Tap the arrows to move and clear blocks, solve brain-teasing puzzles, and plan your moves carefully as blocks can block each other. Enjoy smooth, stress-free gameplay with no time limits. Play this free online puzzle game to relax, sharpen your logic, and train your brain anytime.', 'Casual', 5, 'publish', '2026-04-19 08:48:13'),
(110, 'Goods Triple Match 3D', '931dfd68632142c7b3e882009866d288', 'https://html5.gamedistribution.com/931dfd68632142c7b3e882009866d288/', 'assets/thumbs/931dfd68632142c7b3e882009866d288.jpg', 'Begin a super satisfying match 3 puzzle challenge. Goods Triple Match 3D is a colorful and addictive casual logic game where all items appear in beautiful and realistic 3D. Your table is filled with tons of cute 3D drinks.', 'Casual', 6, 'publish', '2026-04-19 08:48:16'),
(111, '99 Balls', 'dd6edfff840a4c38ae69596cf0ce314e', 'https://html5.gamedistribution.com/dd6edfff840a4c38ae69596cf0ce314e/', 'assets/thumbs/dd6edfff840a4c38ae69596cf0ce314e.jpg', '99 Balls 3D is an endless arcade game that mixes brick breaker and bubble shooter action in full 3D. Launch balls to smash numbered cylinders before they reach the bottom. Collect stars to unlock fun ball skins like sports balls, gems, or fruit. Simple to play, endlessly challenging, and highly addictive!', 'Casual', 6, 'publish', '2026-04-19 08:48:22'),
(112, 'Sweet Dessert Hole', 'e1308b7ecfe0461a864dc847e33d66f6', 'https://html5.gamedistribution.com/e1308b7ecfe0461a864dc847e33d66f6/', 'assets/thumbs/e1308b7ecfe0461a864dc847e33d66f6.jpg', 'Ready to make cute and tasty desserts? In Sweet Dessert Hole, you control a hole that sucks up various sweet toppings. Move the hole around to collect chocolate, cream, fruits, cookies, dan many more. Collect everything on the base before time runs out. Use your coins to upgrade the hole and make the gameplay faster and easier. After making one or more cakes, you can arrange them neatly on a tray. This game is simple, relaxing, and very satisfying to play.', 'Casual', 6, 'publish', '2026-04-19 08:48:30'),
(113, 'Dinosaur Rampage', '0ed83e6a1e7846db9eb4b04d96146f6a', 'https://html5.gamedistribution.com/0ed83e6a1e7846db9eb4b04d96146f6a/', 'assets/thumbs/0ed83e6a1e7846db9eb4b04d96146f6a.jpg', 'When the rampage ends, you’ll compete against other dinosaurs in the same arena and get ranked based on your destruction performance. Unlock many different dinosaur types, collect cool skins in the shop, and prove you’re the ultimate king of chaos. Fast, satisfying, and perfect for stress relief—just stomp, smash, and climb the leaderboard!', 'Casual', 4, 'publish', '2026-04-19 08:48:33'),
(114, 'Seat Puzzle Cut The Rope', '24becac37a04406c8f6c44c28513c09c', 'https://html5.gamedistribution.com/24becac37a04406c8f6c44c28513c09c/', 'assets/thumbs/24becac37a04406c8f6c44c28513c09c.jpg', 'Face a wildly satisfying brain challenge in Seat Puzzle - Cut The Rope. This addictive puzzle game blends smart logic with relaxing casual gameplay, creating the perfect experience for those who love thinking fast and solving clever challenges! In each level, chairs are bound by ropes. Your task is to cut the ropes according to the passengers\' colors.', 'Puzzle', 6, 'publish', '2026-04-19 08:49:26'),
(115, 'Bunny Blox', '1ac9302aebc64320af6a0e089c9c724f', 'https://html5.gamedistribution.com/1ac9302aebc64320af6a0e089c9c724f/', 'assets/thumbs/1ac9302aebc64320af6a0e089c9c724f.jpg', 'Help the Bunny collect as many blox as possible. Match 3 or more items. Slide left or right to move the item. Slide up to rotate and slide down to drop the item. Special rewards appear during the game. Use them wisely to destroy strategic areas.', 'Puzzle', 7, 'publish', '2026-04-19 08:49:26'),
(116, 'Jigsaw Cards: Daily Puzzles', '5eac6df2561f49d1ac2992d130900bca', 'https://html5.gamedistribution.com/5eac6df2561f49d1ac2992d130900bca/', 'assets/thumbs/5eac6df2561f49d1ac2992d130900bca.jpg', 'Jigsaw Cards: Daily Puzzles is a relaxing jigsaw-style puzzle game where you assemble beautiful images piece by piece. Enjoy a calming experience as each picture comes to life under your fingertips!\r\nWho It\'s For\r\nIdeal for puzzle lovers, casual players, and anyone who enjoys peaceful, visually pleasing gameplay.\r\nStart assembling now with Jigsaw Cards: Daily Puzzles — discover a cozy world of delightful puzzles!', 'Puzzle', 7, 'publish', '2026-04-19 08:49:28'),
(117, 'Puzzle Blocks', '8b2128d383444348804bd88f50e32283', 'https://html5.gamedistribution.com/8b2128d383444348804bd88f50e32283/', 'assets/thumbs/8b2128d383444348804bd88f50e32283.jpg', 'Race against time in tense speed battles, employ tactical thinking in rescue missions, and unwind by creating massive structures in free-play mode. Hone your skills assembling perfect puzzles or challenge the ever-accelerating chaos.\r\n\r\nPuzzle Blocks is more than a game; it\'s a curated collection of perfectly crafted puzzles for any mood. The world of puzzles awaits its hero. Can you conquer every challenge?', 'Puzzle', 8, 'publish', '2026-04-19 08:49:30'),
(118, 'Bottle Logic', '05b170aa3a7c44078e543d5c04c80f62', 'https://html5.gamedistribution.com/05b170aa3a7c44078e543d5c04c80f62/', 'assets/thumbs/05b170aa3a7c44078e543d5c04c80f62.jpg', 'Bottle Logic is a satisfying drag-and-drop puzzle where you move and organize bottles into the correct places with smooth, intuitive controls. Enjoy 500+ handcrafted levels that steadily increase in challenge—providing the perfect daily brain cardio—plus an endless mode for non-stop play. Perfect for quick sessions or long relaxing runs, this game is designed for puzzle lovers who enjoy strategic thinking and clean, minimalist visuals.', 'Puzzle', 5, 'publish', '2026-04-19 08:49:37'),
(119, 'Magic Bottles', 'd91602efd33a46d59afe4eea53f6eacf', 'https://html5.gamedistribution.com/d91602efd33a46d59afe4eea53f6eacf/', 'assets/thumbs/d91602efd33a46d59afe4eea53f6eacf.jpg', 'Magic Bottles is a calming yet cleverly challenging color-sorting puzzle game. Pour liquids between bottles until each one contains only a single color. While the rules are simple, levels become increasingly complex, introducing new bottle types, tricky layouts, and situations that demand careful planning. Perfect for puzzle fans and players who enjoy logical challenges, Magic Bottles offers a relaxing yet engaging brain-training experience. Restore perfect order, one puzzle at a time.', 'Puzzle', 6, 'publish', '2026-04-19 08:49:51'),
(120, '2048 Merge World', 'a8ecea31288d4f6581ae36db798ce9ac', 'https://html5.gamedistribution.com/a8ecea31288d4f6581ae36db798ce9ac/', 'assets/thumbs/a8ecea31288d4f6581ae36db798ce9ac.jpg', 'The numbers are multiplying and the board is filling up. It\'s up to you to manage the chaos! Think quickly, act strategically and merge numbers to create bigger and better values. Be smart, but don’t forget to trust your intuition when making moves on the board.', 'Puzzle', 7, 'publish', '2026-04-19 08:49:54'),
(121, 'Draw One Part Brain Puzzle', '4c35db256f3c4f5bbf041169c0465a3c', 'https://html5.gamedistribution.com/4c35db256f3c4f5bbf041169c0465a3c/', 'assets/thumbs/4c35db256f3c4f5bbf041169c0465a3c.jpg', 'Ready to test your creativity and logic? Draw One Part: Brain Puzzle is a fun and clever brain teaser puzzle game that combines thinking with drawing. Each level shows an incomplete picture, and your task is to draw the missing part to solve the puzzle.', 'Puzzle', 6, 'publish', '2026-04-19 08:49:58'),
(122, 'Number Place Travel', '87950d31e22149b0a7ad8abd27832778', 'https://html5.gamedistribution.com/87950d31e22149b0a7ad8abd27832778/', 'assets/thumbs/87950d31e22149b0a7ad8abd27832778.jpg', 'Fill the grid with numbers 1–9 so that no same number appears in any row, column, or 3×3 block!\r\nTap a cell and choose a number to place it.\r\nYou can make up to 3 mistakes. Fill in everything correctly to clear the puzzle!', 'Puzzle', 5, 'publish', '2026-04-19 08:50:01'),
(123, 'Soda Block Jam', 'f4cf848dffd54e94832f2810618a17e1', 'https://html5.gamedistribution.com/f4cf848dffd54e94832f2810618a17e1/', 'assets/thumbs/f4cf848dffd54e94832f2810618a17e1.jpg', 'Slide soda crates, collect bottles, and deliver to the right\r\nexits. A smooth, colorful puzzler that blends motion and\r\ncolor-matching', 'Puzzle', 10, 'publish', '2026-04-19 08:50:07'),
(124, 'Pool Merge', '9fd0bb2225334fc69d2ae8d5aa953096', 'https://html5.gamedistribution.com/9fd0bb2225334fc69d2ae8d5aa953096/', 'assets/thumbs/9fd0bb2225334fc69d2ae8d5aa953096.jpg', 'This is an arcade puzzle with billiard physics and 2048 merge mechanics. Shoot balls, combine identical ones and score points!\r\nGame modes:\r\nClassic: plan your moves, avoid overflowing the field. With each new open ball level, the limit of allowed balls on the playing field increases.\r\nArcade: play for time, do not let the balls fall into the holes. Merging balls adds time to the timer, balls that fall into the holes take time away.', 'Puzzle', 7, 'publish', '2026-04-19 08:50:09'),
(125, 'Cubica', 'f21bb49bbea446af8dbbfc3d61d2ee14', 'https://html5.gamedistribution.com/f21bb49bbea446af8dbbfc3d61d2ee14/', 'assets/thumbs/f21bb49bbea446af8dbbfc3d61d2ee14.jpg', 'Get lost in a tranquil atmosphere with Cubica, a fun puzzle game designed to relax with a simple brain teaser. It\'s very simple! Blast blocks of identical colored cubes to make them disappear, making room for new ones. No rush, no complicated rules, just enjoy the game.\r\nImmerse yourself in soft colors, pleasant sounds, and smooth gameplay that will allow you to forget about the hustle and bustle.', 'Puzzle', 8, 'publish', '2026-04-19 08:50:15'),
(126, 'Draw Bridge Puzzle', '516ceca89758466fa613fa96980eef76', 'https://html5.gamedistribution.com/516ceca89758466fa613fa96980eef76/', 'assets/thumbs/516ceca89758466fa613fa96980eef76.jpg', 'Draw Bridge Puzzle is a creative and exciting puzzle game that combines drawing and rescue gameplay into one addictive experience. You become a bridge designer, using your finger to draw safe paths and complete thrilling rescue missions. Enter the car mode, draw a strong bridge to help a motor cross gaps, broken roads, and dangerous obstacles to reach the goal.', 'Puzzle', 7, 'publish', '2026-04-19 08:50:18'),
(127, 'Wood Screw Puzzle', '334b4139271f4f84853307086906a805', 'https://html5.gamedistribution.com/334b4139271f4f84853307086906a805/', 'assets/thumbs/334b4139271f4f84853307086906a805.jpg', 'Wood Screw Puzzle is a satisfying logic game where you untangle wood screws, nuts, and bolts from clever wooden structures. Each level challenges your spatial thinking as you analyze, plan, and carefully unscrew fasteners in the right order. Beautiful visuals and tactile mechanics make every puzzle feel rewarding and immersive.', 'Puzzle', 5, 'publish', '2026-04-19 08:50:21'),
(128, 'Arrow Slide Puzzle', 'b25e864c4aae4d21af2a31ecc01c3759', 'https://html5.gamedistribution.com/b25e864c4aae4d21af2a31ecc01c3759/', 'assets/thumbs/b25e864c4aae4d21af2a31ecc01c3759.jpg', 'Arrow Slide Puzzle — Logic Puzzle Game\r\nArrow Slide Puzzle is a clean and engaging logic puzzle game where you slide arrows across the board to clear the field and reveal a hidden picture. Simple rules turn into deep challenges that test your logic, planning, and spatial thinking. Perfect for fans of arrow puzzles, sliding logic games, and relaxing brain teasers.\r\n\r\n? Download now and start solving today!', 'Puzzle', 7, 'publish', '2026-04-19 08:50:25'),
(129, 'Fruit Sort Logic', '54794eb4734d4c0cb480bc876a5851cf', 'https://html5.gamedistribution.com/54794eb4734d4c0cb480bc876a5851cf/', 'assets/thumbs/54794eb4734d4c0cb480bc876a5851cf.jpg', 'Fruit Sort Logic is a fun and relaxing puzzle game where you sort colorful fruit juices on shelves. Move the juices around and match three of the same kind to clear a shelf. Space is limited, so each move matters. Clear all shelves to finish the level and unlock new ones. With smooth controls, bright visuals, and endless levels, the game is easy to play and satisfying to master. Perfect for a calm but clever puzzle experience.', 'Puzzle', 6, 'publish', '2026-04-19 08:50:35'),
(130, 'Blockibo: Color Blocks', '9b9fe715b48c419da0a62ad5af3edc73', 'https://html5.gamedistribution.com/9b9fe715b48c419da0a62ad5af3edc73/', 'assets/thumbs/9b9fe715b48c419da0a62ad5af3edc73.jpg', 'Blockibo: Color Blocks is a fun and thoughtful puzzle game where every move matters.\r\nMove colorful blocks, unlock gates, overcome obstacles and use boosters to clear the board.', 'Puzzle', 6, 'publish', '2026-04-19 08:50:38'),
(131, 'Obby vs Zombies', 'bbb134e346924f8ba823e5a674a3e0aa', 'https://html5.gamedistribution.com/bbb134e346924f8ba823e5a674a3e0aa/', 'assets/thumbs/bbb134e346924f8ba823e5a674a3e0aa.jpg', 'Obby vs Zombies is an innovative, fun-filled action game that captivated the gaming world. It challenges players to create mazes of different characters to fend off hordes of incoming zombies. The wide variety of options for attack and defense make this a highly strategic game with lots of replay value.', 'Puzzle', 7, 'publish', '2026-04-19 08:50:42'),
(132, 'Daily Match', 'a523b0c0ab444333b57347b6604f10c6', 'https://html5.gamedistribution.com/a523b0c0ab444333b57347b6604f10c6/', 'assets/thumbs/a523b0c0ab444333b57347b6604f10c6.jpg', 'Connect tiles with a great number of pictures in pairs within the limited time. As you crush all the tiles on the board, you can win the level! Become a tile master level by level! Play faster and faster to train your brain and exercise the link technology!', 'Puzzle', 5, 'publish', '2026-04-19 08:50:47'),
(133, 'Thread Match 2', '58e78963f24c4305931be1bffa305a19', 'https://html5.gamedistribution.com/58e78963f24c4305931be1bffa305a19/', 'assets/thumbs/58e78963f24c4305931be1bffa305a19.jpg', 'Thread Match 2 is a satisfying logic puzzle game that combines color matching, layered challenges, and calming embroidery visuals.\r\n\r\nSolve clever thread puzzles by planning the correct order of moves and dismantling complex constructions. Each level challenges your brain with blocked and unlocked elements, where strategy and attention matter more than speed.', 'Puzzle', 11, 'publish', '2026-04-19 08:50:52'),
(134, 'Fruit Jam Master', '1b51fe92070b442c94733486154b4ab5', 'https://html5.gamedistribution.com/1b51fe92070b442c94733486154b4ab5/', 'assets/thumbs/1b51fe92070b442c94733486154b4ab5.jpg', 'Enter the juiciest and most addictive puzzle adventure ever. Enjoy a fun logic puzzle game in Fruit Jam Master. You need to help all the animals leave the grassland to win. Pay attention to the color of the food. Animals can only pass through when the food matches their own color.', 'Puzzle', 11, 'publish', '2026-04-19 08:50:58'),
(135, 'Mojo Emoji', '6f599a127fc14957b282b0c1e594358a', 'https://html5.gamedistribution.com/6f599a127fc14957b282b0c1e594358a/', 'assets/thumbs/6f599a127fc14957b282b0c1e594358a.jpg', 'Moji Emoji is a fun and clever word/emoji puzzle game where each level challenges you to guess the hidden word or phrase from a set of expressive emojis. Think fast, connect the clues, and test your emoji decoding skills across hundreds of creative puzzles.', 'Puzzle', 7, 'publish', '2026-04-19 08:50:59'),
(136, 'Little Bugs', '83310a1bca264cfd8d1284b7d94b7adb', 'https://html5.gamedistribution.com/83310a1bca264cfd8d1284b7d94b7adb/', 'assets/thumbs/83310a1bca264cfd8d1284b7d94b7adb.jpg', 'you are the guardian of a group of lost beetles. At each stage, the beetles approach two pictures. One is a safe path forward, but the other is a trapdoor into the abyss. Your mission is to decipher the hint—a piece of a vegetable or an animal—to figure out which path is safe. If you misunderstand the clue, you won\'t be able to reach the finish line. Every choice matters in this charming world of clever puzzles. Are you ready to lead your little bugs to safety?', 'Puzzle', 4, 'publish', '2026-04-19 08:51:06'),
(137, 'Knit Rescue', '9e6715da90154d94b29dbd21f8258873', 'https://html5.gamedistribution.com/9e6715da90154d94b29dbd21f8258873/', 'assets/thumbs/9e6715da90154d94b29dbd21f8258873.jpg', 'Knit Rescue is an engaging and original puzzle game where you untangle a knitted dragon to save a frightened kitten.\r\n\r\nBut it’s not enough to simply tap the right spools. You must unlock the correct spools and move them in the right direction to stop the dragon in time.\r\n\r\nPlan your moves, follow the arrows, and solve each level using logic and strategy. Knit Rescue is the perfect casual puzzle game for fans of brain games, logic puzzles, and strategy games.', 'Puzzle', 5, 'publish', '2026-04-19 08:51:17'),
(138, 'Water Sort - Collections', '9ceb5732c253496e8589ac28574e0a81', 'https://html5.gamedistribution.com/9ceb5732c253496e8589ac28574e0a81/', 'assets/thumbs/9ceb5732c253496e8589ac28574e0a81.jpg', 'Sort, pour, and relax! Complete each level by filling bottles and unlock beautiful collectible images. Test your logic, calm your mind, and build your own gallery as you master the art of sorting water!', 'Puzzle', 8, 'publish', '2026-04-19 08:51:19'),
(139, 'Sakura Branch', 'ead527ea936247fb991a0fb52499b2d7', 'https://html5.gamedistribution.com/ead527ea936247fb991a0fb52499b2d7/', 'assets/thumbs/ead527ea936247fb991a0fb52499b2d7.jpg', 'The &quot;Sakura Branch&quot; is an interesting and beautiful puzzle game.\r\n\r\nIn the game you have pieces of a dry branch of a beautiful tree.\r\nTurn them around and put them together.\r\nIf you combine all the pieces, life will return to the branch and it will delight you with beautiful flowers!\r\nIf you are new, you can play on a very small field on which there will be very little branches.\r\nBut if you feel strong enough, you can collect a whole tree on a huge field!', 'Puzzle', 5, 'publish', '2026-04-19 08:51:20'),
(140, 'Escape Again', '6ccf5ab92bf4469ea1988aafaba35ca2', 'https://html5.gamedistribution.com/6ccf5ab92bf4469ea1988aafaba35ca2/', 'assets/thumbs/6ccf5ab92bf4469ea1988aafaba35ca2.jpg', 'Together with the main character of the new online game Escape Again, you will go on a journey through the painted world in search of treasures and adventures. The location in which your hero will be will be visible on the screen in front of you. By controlling his actions you will have to move around the area. Overcoming various obstacles and traps, you will have to help the hero find special magic pins. With their help, he will be able to activate the portal leading to the next level.', 'Puzzle', 5, 'publish', '2026-04-19 08:51:23'),
(141, 'Tetro Merge', '8f07339e65ae4c739e1c406da7c51e26', 'https://html5.gamedistribution.com/8f07339e65ae4c739e1c406da7c51e26/', 'assets/thumbs/8f07339e65ae4c739e1c406da7c51e26.jpg', 'Tetro Merge is a physics-based merge puzzle game where Tetromino blocks come to life.\r\nYou’ll drop Tetrominoes of all shapes—classic, extended, and brand-new originals. When two matching pieces touch, they merge into a bigger, more complex block.\r\nMaster the bounce, plan your stacks, and build powerful combos as the board slowly fills up.\r\nWill you manage your space wisely… or let the blocks overflow?\r\nA perfect blend of strategy, physics, and classic Tetris nostalgia.', 'Puzzle', 5, 'publish', '2026-04-19 08:51:25'),
(142, 'Magic Forest - Merge the Secrets', '0412d111bb7047e88ae28ca9b5ce764e', 'https://html5.gamedistribution.com/0412d111bb7047e88ae28ca9b5ce764e/', 'assets/thumbs/0412d111bb7047e88ae28ca9b5ce764e.jpg', 'The Magic Forest is full of amazing little places!\r\nDo you want to take a walk here?\r\nThen hurry and start your journey!\r\nAnd to make it even more fun, you’ll have company - Masha, a young girl who loves discovering new and mysterious things.\r\nEven if it sometimes means sneaking away from Grandma and missing lunch.', 'Puzzle', 6, 'publish', '2026-04-19 08:51:26'),
(143, 'Math Block', '3696faedf5d14ccfa6abb23379f8a25b', 'https://html5.gamedistribution.com/3696faedf5d14ccfa6abb23379f8a25b/', 'assets/thumbs/3696faedf5d14ccfa6abb23379f8a25b.jpg', 'Math Block is a brain-teasing puzzle game where you slide numbered blocks and operators on a grid to form valid math equations. Match the target value using addition, subtraction, multiplication, and division to earn stars and progress through 500 challenging levels!', 'Puzzle', 7, 'publish', '2026-04-19 08:51:31'),
(144, 'Basket Swap', '41ced8bbf187495d81b565b663f94829', 'https://html5.gamedistribution.com/41ced8bbf187495d81b565b663f94829/', 'assets/thumbs/41ced8bbf187495d81b565b663f94829.jpg', 'Slide into the gray blocks to help you position the ball and grid correctly. If you\'re stuck, click on the arrow in the bottom left corner to undo your last move, or press R to restart the level.', 'Puzzle', 7, 'publish', '2026-04-19 08:51:43'),
(145, 'Dear Island', 'd6b4e05478464bdeb9f4f10f0f967165', 'https://html5.gamedistribution.com/d6b4e05478464bdeb9f4f10f0f967165/', 'assets/thumbs/d6b4e05478464bdeb9f4f10f0f967165.jpg', 'Collect two blocks that match the color of the Match Slot to clear them!\r\nClear them all to finish the stage!\r\nBlocks of different colors can be placed in the Stock.\r\nIf the Stock gets full, it’s game over!', 'Puzzle', 10, 'publish', '2026-04-19 08:51:49'),
(146, 'Bloom Within: A life simulator', '308f223eb05e4b7597ba5adb96701277', 'https://html5.gamedistribution.com/308f223eb05e4b7597ba5adb96701277/', 'assets/thumbs/308f223eb05e4b7597ba5adb96701277.jpg', 'The simulator of a pregnant mother allows you to fully experience the whole process of pregnancy.\r\nIn this anime game you have to play the role of a girl who has a loving husband and a child under her heart, who is waiting for her birth. Take care of yourself, give birth, take care of your baby and raise a healthy baby.', 'Adventure', 3, 'publish', '2026-04-19 08:52:08'),
(147, 'Guns vs Magic', '1d8cf03d22f94c20935c164a9d6adf88', 'https://html5.gamedistribution.com/1d8cf03d22f94c20935c164a9d6adf88/', 'assets/thumbs/1d8cf03d22f94c20935c164a9d6adf88.jpg', 'Step into the shoes of Silvius, a courageous student of magic, as you fight to save the world from the dark powers unleashed by your former mentor, Lucius. Once a wise and benevolent wizard, Lucius has succumbed to the sinister influence of a cursed crystal, turning him into an evil sorcerer intent on dominating the world. Now, it\'s up to you to confront Lucius and his army of enchanted creatures in a battle of wits, power, and courage.', 'Adventure', 6, 'publish', '2026-04-19 08:52:28'),
(148, 'Beat The Zombies', '62a5bfd927984c9a85f01314a21442d9', 'https://html5.gamedistribution.com/62a5bfd927984c9a85f01314a21442d9/', 'assets/thumbs/62a5bfd927984c9a85f01314a21442d9.jpg', 'Beat the Zombies is a vertical action RPG blending strategy and adventure. Explore a dangerous plant-zombie world, fight through stages, and defeat all plant zombies in your way!', 'Adventure', 9, 'publish', '2026-04-19 08:52:29'),
(149, 'Escape School Duel', '29de0276f9474d58a609a813e9a81cdd', 'https://html5.gamedistribution.com/29de0276f9474d58a609a813e9a81cdd/', 'assets/thumbs/29de0276f9474d58a609a813e9a81cdd.jpg', 'Escape School Duel is a fast, funny, and tense escape challenge set inside a school that does not want to let you leave. Play solo to chase your best time, or go 2 player and turn every hallway into a race for freedom. One moment you are dodging traps, the next you are trying to slip past the principal in a long corridor or outsmart a teacher waiting near the classroom. Every section has its own danger, so learning the school layout is part of the strategy.', 'Adventure', 7, 'publish', '2026-04-19 08:52:30'),
(150, 'Avenger Guard', 'c89b6590d54245c390eb27cc7d8048c9', 'https://html5.gamedistribution.com/c89b6590d54245c390eb27cc7d8048c9/', 'assets/thumbs/c89b6590d54245c390eb27cc7d8048c9.jpg', 'Dark forces have destroyed your homeland—rise as the Avenger Guard! Merge heroes to unlock power, fortify defenses, and take vengeance. Lead your legendary squad to repel waves of enemies, upgrade through fusion, and reclaim what’s yours. Will you be the last line of defense?', 'Adventure', 5, 'publish', '2026-04-19 08:52:32'),
(151, 'Rainbow Friends Hide And Seek', '193427c7c07b4ef3a1d43e7fd7fd901d', 'https://html5.gamedistribution.com/193427c7c07b4ef3a1d43e7fd7fd901d/', 'assets/thumbs/193427c7c07b4ef3a1d43e7fd7fd901d.jpg', 'Rainbow Friends Hide And Seek is an exciting and fast-paced hide-and-seek adventure game set in a colorful yet dangerous rainbow world. Step into this thrilling role-playing experience, choose your role, and get ready for an unforgettable adventure.', 'Adventure', 4, 'publish', '2026-04-19 08:52:34'),
(152, 'Snow Rider Obby Parkour', '1d74e75b8da74767938d3310255b4bd3', 'https://html5.gamedistribution.com/1d74e75b8da74767938d3310255b4bd3/', 'assets/thumbs/1d74e75b8da74767938d3310255b4bd3.jpg', 'Snow Rider Obby Parkour is a fast-paced snowboard adventure where reflexes, timing, and control matter. Play solo or with a friend in split-screen mode and experience different snow challenges across multiple game modes. Whether you want to beat distance records, explore a massive open world, or race down dangerous mountains, this game offers a complete snowboarding experience.\r\n\r\nMaster your snowboard, perform double jumps, and unlock amazing gear to customize your character!', 'Adventure', 6, 'publish', '2026-04-19 08:52:36'),
(153, 'Cute cat\'s adventures', '43f18d2061fb44b58971b70842a6e45d', 'https://html5.gamedistribution.com/43f18d2061fb44b58971b70842a6e45d/', 'assets/thumbs/43f18d2061fb44b58971b70842a6e45d.jpg', 'An adventure game for girls about a cat, with whom you have to go in search of kittens. Colorful levels await you, filled with traps, obstacles and secrets, as well as dangerous enemies who will try to prevent you from completing your main goal.', 'Adventure', 3, 'publish', '2026-04-19 08:52:38'),
(154, 'Superheroes and the Wand', 'a0e71a6336ed4173b09cc76d1a3ef4a2', 'https://html5.gamedistribution.com/a0e71a6336ed4173b09cc76d1a3ef4a2/', 'assets/thumbs/a0e71a6336ed4173b09cc76d1a3ef4a2.jpg', 'You will play as a Wand character who had a strange dream about a sorcerer. Soon, in reality, the sorcerer from Stickman dream appears in the city and begins to do evil. Wand, together with the Superheroes, decide to teach the sorcerer a lesson. But not everything is so easy to do. The following superheroes are waiting for you: Blushing, Green Man, Bobo, Cudgel, Bruise, Flyer, Captain Captain and others. Among the enemies will be the Wizard, Anrik, the Clown and others.', 'Adventure', 4, 'publish', '2026-04-19 08:52:40'),
(155, 'Obby Prison Run', '79a0fe62ed874a58903a9bc33aab2136', 'https://html5.gamedistribution.com/79a0fe62ed874a58903a9bc33aab2136/', 'assets/thumbs/79a0fe62ed874a58903a9bc33aab2136.jpg', 'Obby Prison Run is an intense obstacle course game where escape is the only option—and survival is everything. Sprint, leap, and dodge through deadly traps and twisted takes on classic childhood games. Outsmart your rivals and stay ahead in the race for freedom, where every second counts and only the sharpest make it out alive.', 'Adventure', 5, 'publish', '2026-04-19 08:52:44'),
(156, 'Sausage Man Shooting Adventure', 'e00fde5e6256468f8abad8669c3f89f6', 'https://html5.gamedistribution.com/e00fde5e6256468f8abad8669c3f89f6/', 'assets/thumbs/e00fde5e6256468f8abad8669c3f89f6.jpg', 'Dive into a hilarious and action-packed adventure. Sausage Man Shooting Adventure is a fast-paced side-scrolling shooting game where you control a crazy, energetic sausage hero and blast through waves of enemies. Run forward, dodge traps, jump platforms, and shoot enemies with nonstop excitement! Collect airdrops to increase your damage.', 'Adventure', 7, 'publish', '2026-04-19 08:53:03'),
(157, 'Forest Survivor Rougelike', '6a739956a35f4584944baf5224e485a2', 'https://html5.gamedistribution.com/6a739956a35f4584944baf5224e485a2/', 'assets/thumbs/6a739956a35f4584944baf5224e485a2.jpg', 'Forest Survivor Roguelike is an addictive simulator adventure game that throws you into a dangerous forest. Only the strongest survivor can survive. From the very first moment, you must fight, explore, and adapt to stay alive in this intense roguelike world. Every step in the forest is a new challenge.', 'Adventure', 6, 'publish', '2026-04-19 08:53:06'),
(158, 'Obby Toilet Line', '27214a866f174c7ebdf0089d6b383d9f', 'https://html5.gamedistribution.com/27214a866f174c7ebdf0089d6b383d9f/', 'assets/thumbs/27214a866f174c7ebdf0089d6b383d9f.jpg', 'Obby Toilet Line starts in the most chaotic place imaginable: a gas station restroom line. Around 30 different characters are already waiting, and the queue stretches all the way past the store entrance. Your goal is simple, but the situation is not: earn money while you wait, move up the line, and reach the mysterious toilet at the end.\r\n\r\nThis is not just a “stand still” queue. The game uses an idle-style progression system: the position you’re standing in determines how much you earn.', 'Adventure', 5, 'publish', '2026-04-19 08:53:08'),
(159, 'Gold Miner Classic', '4d5f8d59dcf948ceac8cfda4178f3759', 'https://html5.gamedistribution.com/4d5f8d59dcf948ceac8cfda4178f3759/', 'assets/thumbs/4d5f8d59dcf948ceac8cfda4178f3759.jpg', 'Jump into the most classic gold mining adventure ever! Gold Miner Classic brings you all the excitement of being a real gold miner. Feel into the perfect casual relaxation experience. Your mission is simple but incredibly satisfying.', 'Adventure', 6, 'publish', '2026-04-19 08:53:30'),
(160, 'Pinball VS Zombie', '5cdec698c5ce4e66af14ea5b3968ef08', 'https://html5.gamedistribution.com/5cdec698c5ce4e66af14ea5b3968ef08/', 'assets/thumbs/5cdec698c5ce4e66af14ea5b3968ef08.jpg', 'Dive into Pinball Zombie Defense, the ultimate fusion of pinball chaos and zombie tower defense! Plant defensive flora to create a ricocheting battlefield where high-speed pinballs smash into plants, unleashing bullet barrages on undead waves. Auto-collect sunlight to grow stronger defenses and hold the line—don\'t let a single zombie reach your house!', 'Adventure', 5, 'publish', '2026-04-19 08:53:30'),
(161, 'Survival On Raft Multiplayer', '8617ea5a6ce64ca78dc93c521ef8e9d3', 'https://html5.gamedistribution.com/8617ea5a6ce64ca78dc93c521ef8e9d3/', 'assets/thumbs/8617ea5a6ce64ca78dc93c521ef8e9d3.jpg', 'Begin an exciting survival adventure in Survival On Raft: Multiplayer. Have an addictive survival-adventure simulation on an island. Here, you\'ll be gathering various foods, stones, and other items. Collect ocean resources like wood, leaves and rare items. Sharks in the sea will attack your raft at any moment.', 'Adventure', 6, 'publish', '2026-04-19 08:53:30'),
(162, 'Plant Merge: Zombie War', '9190c99d4aae4e0085a6059478ee3520', 'https://html5.gamedistribution.com/9190c99d4aae4e0085a6059478ee3520/', 'assets/thumbs/9190c99d4aae4e0085a6059478ee3520.jpg', 'In the chaotic world of Merge Plant Zombie War, arm your garden with strategic merges to fend off relentless zombie hordes! Master upgrades, deploy special abilities, and outsmart waves of undead foes in this addictive merge-tower defense adventure. Will your botanical army prevail in the ultimate war for survival? Dive in and merge your way to victory!', 'Adventure', 6, 'publish', '2026-04-19 08:53:32'),
(163, '1945 Air Force Space Shooter', '38ab3871c30c48a3a6a4b1e3e2ce802c', 'https://html5.gamedistribution.com/38ab3871c30c48a3a6a4b1e3e2ce802c/', 'assets/thumbs/38ab3871c30c48a3a6a4b1e3e2ce802c.jpg', 'Prepare for nonstop action in 1945 Air Force: Space Shooter! Inspired by the classic shooter era, this game combines vintage visuals with thrilling bulletstorm gameplay that will test your reflexes and precision.Fly through endless waves of enemy aircraft. Avoid storms of bullets and unleash devastating firepower from your Force fighter.', 'Adventure', 7, 'publish', '2026-04-19 08:53:34'),
(164, 'Drunk But Not Wasted Knight', '51766065cf2a4b7487640fa295b80a99', 'https://html5.gamedistribution.com/51766065cf2a4b7487640fa295b80a99/', 'assets/thumbs/51766065cf2a4b7487640fa295b80a99.jpg', 'Stumble into a moonlit alley and befriend a tipsy yet oddly wise knight in this comedic medieval visual novel. Banter, make choices, and nudge affection as you chase stories, dodge trouble, and unlock quirky endings.', 'Adventure', 6, 'publish', '2026-04-19 08:53:35'),
(165, 'Flower Fairy Adventure Story', '33a41fb522c441da90d1b7172ee94b8b', 'https://html5.gamedistribution.com/33a41fb522c441da90d1b7172ee94b8b/', 'assets/thumbs/33a41fb522c441da90d1b7172ee94b8b.jpg', 'Welcome to Flower Fairy Adventure Story, a casual puzzle game that you can play for free. Flower Fairy lost her wings! Embark on an adventure where you solve each tiny jigsaw, dress up your girl in pretty clothes, and pave the way for the Flower Fairy. Practice your observation, logical thinking, and hands-on ability while enjoying the relaxing and captivating puzzle game.', 'Adventure', 6, 'publish', '2026-04-19 08:53:37'),
(166, 'Red Stickman vs Monster School', 'd1dde7ae11fa4cf7a6c08126c9118f09', 'https://html5.gamedistribution.com/d1dde7ae11fa4cf7a6c08126c9118f09/', 'assets/thumbs/d1dde7ae11fa4cf7a6c08126c9118f09.jpg', 'Red Stickman vs Monster School - stickman game where you need to pick up different weapons and clear levels from mobs from the school of monsters. The game contains\r\n\r\n- 60 levels\r\n- 10 bosses\r\n- Many types of different weapons!\r\n\r\nDid you like the game &quot;Red Stickman vs Monster School &quot;? - Then write a review and play all our games about stickmen.', 'Adventure', 6, 'publish', '2026-04-19 08:53:37'),
(167, 'Stick vs Monster School 2', '22083d0b3576411caa671156a9fe4052', 'https://html5.gamedistribution.com/22083d0b3576411caa671156a9fe4052/', 'assets/thumbs/22083d0b3576411caa671156a9fe4052.jpg', 'Stick vs Monster School 2 is now fighting zombies!\r\n\r\nHe\'s in for fights and epic battles in the world during the zombie apocalypse!\r\n\r\nGame features:\r\n- Make cool shot\r\n- Buy guns\r\n- Fight zombies and bosses!\r\n\r\nDid you like the game &quot;Stick vs Monster School 2&quot;? - Then write a review and play all our games about stickmen.', 'Adventure', 7, 'publish', '2026-04-19 08:53:40'),
(168, 'Mega Shark', '9ff4c1c62da64af98d32fe1a1b44ac0a', 'https://html5.gamedistribution.com/9ff4c1c62da64af98d32fe1a1b44ac0a/', 'assets/thumbs/9ff4c1c62da64af98d32fe1a1b44ac0a.jpg', 'One shark and a sea full of delicious fish. How hungry are you? You’ve got 60 seconds to prove it! Feed nonstop, survive the deepest waters and rely on your shark’s speed, strength and invincibility to complete each hunt. Collect coins and trophies to unlock and explore new stages.', 'Adventure', 6, 'publish', '2026-04-19 08:53:48'),
(169, 'Blox Fruits', 'a0ca95e726b241f2817b028bdb32ea2a', 'https://html5.gamedistribution.com/a0ca95e726b241f2817b028bdb32ea2a/', 'assets/thumbs/a0ca95e726b241f2817b028bdb32ea2a.jpg', 'Embark on an epic adventure across the seas in Blox Fruits, a Roblox MMORPG inspired by the world of One Piece. Choose your path as a Pirate or Marine, master powerful abilities granted by mystical Blox Fruits, and strive to become the strongest player in the game', 'Adventure', 6, 'publish', '2026-04-19 08:53:48'),
(170, 'Noob: Skyblock Survival', '1b4197feadd84f789b63664d439e81f6', 'https://html5.gamedistribution.com/1b4197feadd84f789b63664d439e81f6/', 'assets/thumbs/1b4197feadd84f789b63664d439e81f6.jpg', 'Welcome to the game Noob: Skyblock Survival!\r\n\r\nNoob: Skyblock Survival is a sandbox survival game on an island in the style of Minecraft, where you need to dig blocks.\r\n\r\nFeatures of the game:\r\n- Dig blocks\r\n- Plant trees and wheat\r\n- Survive on a cube island\r\n- Expand your island, and then fight zombies!\r\n\r\nRemember, you are a cool cube digger and you must survive!\r\n\r\nIf you liked our game &quot;Noob: Skyblock Survival&quot;, then rate it and write a review, and also play our other games about Noob.', 'Adventure', 4, 'publish', '2026-04-19 08:53:50'),
(171, 'Blue Hedgehog Hill Dash Ride', '6134a1778c0f4929a68bf7dc9cd51398', 'https://html5.gamedistribution.com/6134a1778c0f4929a68bf7dc9cd51398/', 'assets/thumbs/6134a1778c0f4929a68bf7dc9cd51398.jpg', 'Join a daring blue hedgehog on an epic uphill racing adventure! Race through challenging terrains—from rugged lands to moon hills—using simple controls to speed, jump, and perform stunts. With smooth physics and exciting levels, you’ll climb impossible hills and chase victory. Perfect for fans of racing, stunts, and adventure!', 'Adventure', 7, 'publish', '2026-04-19 08:53:50'),
(172, 'Dolphin Dash', '03be85ef64034d6cb94956ae8511f2bc', 'https://html5.gamedistribution.com/03be85ef64034d6cb94956ae8511f2bc/', 'assets/thumbs/03be85ef64034d6cb94956ae8511f2bc.jpg', 'Launch your dolphin out of the water and smash through obstacles in this fast-paced underwater adventure. Collect coins, defeat bosses, and explore colorful ocean worlds full of surprises!', 'Adventure', 5, 'publish', '2026-04-19 08:53:52'),
(173, 'Stick War Saga', '334714f0c010454faf2248793ba893be', 'https://html5.gamedistribution.com/334714f0c010454faf2248793ba893be/', 'assets/thumbs/334714f0c010454faf2248793ba893be.jpg', 'Prepare for an epic clash in Stick War: Saga, an exciting blend of fighting, action, strategy, and tower defense. Take command of your stickman army and lead them through nervous war campaigns. Mine resources, build your army, and unleash your strategic power to conquer enemy lands.', 'Adventure', 8, 'publish', '2026-04-19 08:53:53'),
(174, 'Hidden Object - Girl and Cat', 'dee3caf78302400c9c9252dddbadff31', 'https://html5.gamedistribution.com/dee3caf78302400c9c9252dddbadff31/', 'assets/thumbs/dee3caf78302400c9c9252dddbadff31.jpg', 'You play as a sweet girl walking through the forest with her cat, Lassie.\r\nOur girl was walking and everything was wonderful: the birds were singing, the flowers were a delight to the eye, and suddenly the cat meowed and ran off into the depths of the forest.\r\nOur girl searched for her cat in the forest for a long time and didn\'t notice how night had fallen. Wandering through the forest, the girl came across an old house. What if our cat ran in there?', 'Adventure', 4, 'publish', '2026-04-19 08:53:54'),
(175, 'Thief Stick Puzzle Man Escape', 'ad50ffe7f40340fb955a2d933b0be10c', 'https://html5.gamedistribution.com/ad50ffe7f40340fb955a2d933b0be10c/', 'assets/thumbs/ad50ffe7f40340fb955a2d933b0be10c.jpg', 'Enjoy a hilarious and brain-twisting adventure in Thief Stick Puzzle: Man Escape. It’s a mix of stickman comedy, clever puzzle levels, and funny escape challenges that will keep you hooked for hours! You play as a sneaky thief stickman trying to escape from tricky situations. To survive, you’ll need to solve smart brain teaser puzzles. For example, finding the correct path through a maze to obtain treasure, or bypassing a cutting machine to save a puppy.', 'Adventure', 4, 'publish', '2026-04-19 08:53:58'),
(176, 'Hidden Objects Story', '11233fb28e134834a682ca49624ec0bd', 'https://html5.gamedistribution.com/11233fb28e134834a682ca49624ec0bd/', 'assets/thumbs/11233fb28e134834a682ca49624ec0bd.jpg', 'Every scene tells a story, waiting for your discovery. Collect coins, unlock hints and piece together secrets buried beneath the surface. The mystery deepens with every level. Stay focused or the secrets slip away forever.', 'Adventure', 4, 'publish', '2026-04-19 08:54:06'),
(177, 'Obby Blox Hook', '387c69e13ef341268e7b659cc2e2311c', 'https://html5.gamedistribution.com/387c69e13ef341268e7b659cc2e2311c/', 'assets/thumbs/387c69e13ef341268e7b659cc2e2311c.jpg', 'Obby Blox Hook is an addictive physics-based platformer where players control the Roblox players swinging through levels using a grappling hook. With smooth animations, challenging obstacles, and fun physics mechanics, the game tests your timing and precision as you swing from one point to another, avoiding obstacles and making daring jumps to reach the finish line.', 'Adventure', 5, 'publish', '2026-04-19 08:54:07');
INSERT INTO `games` (`id`, `title`, `slug`, `iframe_url`, `image_url`, `description`, `category`, `views`, `status`, `created_at`) VALUES
(178, 'Archers Random', 'f4055ea8c0794a50badf82d7ce837eaa', 'https://html5.gamedistribution.com/f4055ea8c0794a50badf82d7ce837eaa/', 'assets/thumbs/f4055ea8c0794a50badf82d7ce837eaa.jpg', 'Archers Random is a fast-paced stickman archery game that tests your reflexes and aim.\r\n\r\nFight endless enemy waves, explore new areas, and earn coins to unlock helmets, armor, and triple arrows. Upgrade speed, damage, health, and arm power, master 12 special arrows like fire, poison, rocket, and electric, face epic bosses, and survive nonstop action.\r\n\r\nPlay solo or challenge a friend in 2 Player mode on the same device for intense head-to-head battles.', 'Adventure', 5, 'publish', '2026-04-19 08:54:07'),
(179, 'Survival in Area 51', '1632d62cc49b4a139f41739a19de37f8', 'https://html5.gamedistribution.com/1632d62cc49b4a139f41739a19de37f8/', 'assets/thumbs/1632d62cc49b4a139f41739a19de37f8.jpg', 'You will play as the character Stas, who works in Area 51. One day, Stas was given a strange task, to find acid and pour it into an unusual device. Then something terrible happened... In Area 51, an explosion occurred underground, and zombies appeared. They began to attack scientists and guards. Your task is to destroy zombies, mercenaries and find a way out of this terrible underground place. The game offers shooting, simple puzzles, a plot, many locations and a final battle.', 'Adventure', 8, 'publish', '2026-04-19 08:54:11'),
(180, 'Survival Island: EVO', 'badfffd6951b4bdfa9b5eab7342496ab', 'https://html5.gamedistribution.com/badfffd6951b4bdfa9b5eab7342496ab/', 'assets/thumbs/badfffd6951b4bdfa9b5eab7342496ab.jpg', 'Play a fun adventure and simulation game in Survival Island: EVO. You are alone on a mysterious island, and the challenge begins: survive, build, and thrive. Gather more resources like food, water, wood, and stone. And craft the tools you need to stay alive. Build your shelter, light a fire, and protect yourself from hunger and wild animals. Explore hidden corners of the island, discover secrets, and unlock new crafting recipes. Become the true survivor.', 'Adventure', 6, 'publish', '2026-04-19 08:54:12'),
(181, 'Brawl Stars Brave Adventure', '9dd243c7b2a243e4b9a7f92a23120c45', 'https://html5.gamedistribution.com/9dd243c7b2a243e4b9a7f92a23120c45/', 'assets/thumbs/9dd243c7b2a243e4b9a7f92a23120c45.jpg', 'Brawl Stars Brave Adventure is a casual battle game designed for brave boys who love fast-paced action and nonstop adventure. Control fearless heroes as you battle enemies, avoid traps, and blast your way through nervous levels. Defeat monsters to constantly upgrade. Choose your skills to ensure your survival or increase your damage! Keep moving to avoid enemy attacks! Complete all levels to win. Get coins to unlock a variety of awesome weapons. Like darts, axes, etc.', 'Adventure', 6, 'publish', '2026-04-19 08:54:17'),
(182, 'Block Parkour Trials', '6f38d609768747a692974c6ef97b2514', 'https://html5.gamedistribution.com/6f38d609768747a692974c6ef97b2514/', 'assets/thumbs/6f38d609768747a692974c6ef97b2514.jpg', 'Block Parkour Trials is a super fun and free-to-play parkour game. Your goal is to reach the portal at the finish line by skillfully jumping over obstacles. Have fun and enjoy the challenge!', 'Adventure', 4, 'publish', '2026-04-19 08:54:25'),
(183, 'Alien Wreckage 1', 'c9b68fc0a50d4085ba406292b1a06470', 'https://html5.gamedistribution.com/c9b68fc0a50d4085ba406292b1a06470/', 'assets/thumbs/c9b68fc0a50d4085ba406292b1a06470.jpg', 'In &quot;Alien Wreckage - Chapter 1&quot; you are a lone space traveler, who explore the deepspace looking for alien artifacts around the universe. Face alien creatures, collect coins and jewels to spend in the game shops, find all the secrets and unlock new powerups.', 'Adventure', 5, 'publish', '2026-04-19 08:54:28'),
(184, 'Journey Of Escape', '9c97a939fdd4400788f2732ba35e7698', 'https://html5.gamedistribution.com/9c97a939fdd4400788f2732ba35e7698/', 'assets/thumbs/9c97a939fdd4400788f2732ba35e7698.jpg', 'Escape games have always been a popular genre among puzzle enthusiasts and adventure seekers. They challenge players to think critically, solve intricate puzzles, and uncover hidden secrets while racing against time. &quot;Journey of Escape&quot; is an immersive collection of escape games designed to test your intelligence', 'Adventure', 5, 'publish', '2026-04-19 08:54:29'),
(185, 'Witchy and the Puzzle Adventures', 'a455fc9c9c324c33a288ead33ad21661', 'https://html5.gamedistribution.com/a455fc9c9c324c33a288ead33ad21661/', 'assets/thumbs/a455fc9c9c324c33a288ead33ad21661.jpg', 'Help the brave Witch to pass all the puzzling tests and find all the seals to shelter them in her cozy forest house. Kittens are lost in the forest, which is full of various traps and dangers, you need to help the Witch to pass all the tests and find all the seals.', 'Adventure', 8, 'publish', '2026-04-19 08:54:32'),
(186, 'Skate Hooligans', 'e06bbab372b741228acea8c3c08aa001', 'https://html5.gamedistribution.com/e06bbab372b741228acea8c3c08aa001/', 'assets/thumbs/e06bbab372b741228acea8c3c08aa001.jpg', 'Help the little hooligans escape from the policeman who is constantly trying to catch them. Try to collect as many bonuses and coins as possible on the road, for which you can buy new coolest skateboards and amazing characters. And do not forget to complete funny tasks, because the number of points you receive depends on this!', 'Adventure', 8, 'publish', '2026-04-19 08:54:35'),
(187, 'The Road Home: Granny Escape', '1ca550a66423424c98c39fcc8cd57ff0', 'https://html5.gamedistribution.com/1ca550a66423424c98c39fcc8cd57ff0/', 'assets/thumbs/1ca550a66423424c98c39fcc8cd57ff0.jpg', 'Step into the chilling world of The Road Home: Granny Escape, a horror escape room experience where every shadow hides danger. Solve puzzles, collect items, and find a way out while being relentlessly hunted by Granny and Grandpa. Use stealth, strategy, and courage to survive this terrifying challenge and make your way to freedom.', 'Adventure', 6, 'publish', '2026-04-19 08:54:38'),
(188, 'Labubu Jetpack Rush', '6408783a54014b7688d5476f695fed8a', 'https://html5.gamedistribution.com/6408783a54014b7688d5476f695fed8a/', 'assets/thumbs/6408783a54014b7688d5476f695fed8a.jpg', 'Fly high in Jetpack Jump with Labubu to survive the escape from the lab! Tap to use the jetpack and release to run . Upgrade your jetpack, your running speed and other upgrades to be able to travel further than before and beat your high score. The further you travel the more money you get!', 'Adventure', 5, 'publish', '2026-04-19 08:54:39'),
(189, 'Egg Adventure: Mirror World', 'ef2d9850b5cd4d71a1a2425f3693c543', 'https://html5.gamedistribution.com/ef2d9850b5cd4d71a1a2425f3693c543/', 'assets/thumbs/ef2d9850b5cd4d71a1a2425f3693c543.jpg', 'Mr. Egg accidentally entered the Mirror World. In this world, all the challenges in each level look the same with Egg Adventure 2, but the ways to pass them are different. Use your wisdom to help Mr. Egg bravely pass every level!', 'Adventure', 6, 'publish', '2026-04-19 08:54:48'),
(190, 'Katana', 'ce1c19c59fae4ecb89c3849f10571760', 'https://html5.gamedistribution.com/ce1c19c59fae4ecb89c3849f10571760/', 'assets/thumbs/ce1c19c59fae4ecb89c3849f10571760.jpg', 'It\'s a first-person Katana game!\r\nSlice all the enemy ninjas into small pieces and save the hostages. Use multiple katana swords and shurikens. Fight epic bosses and complete the levels.', 'Adventure', 7, 'publish', '2026-04-19 08:54:49'),
(191, 'Dan the Man', '3d11dfed72a04e00ae9a43ab3fd49bd6', 'https://html5.gamedistribution.com/3d11dfed72a04e00ae9a43ab3fd49bd6/', 'assets/thumbs/3d11dfed72a04e00ae9a43ab3fd49bd6.jpg', 'With a cracking funny story, action, an awesome upgradeable fighting skills and an epic arsenal of weapons that will make even the most heroic of heroes envious, Dan The Man\'s arcade fight fest has enough enemies and boss fights to satisfy every hardcore Action Platformer enthusiast and every indie game lover.', 'Adventure', 5, 'publish', '2026-04-19 08:54:58'),
(192, 'Scary Teacher 3D Returns', 'c75029d181cb49eaa606d0d72d5fc4a5', 'https://html5.gamedistribution.com/c75029d181cb49eaa606d0d72d5fc4a5/', 'assets/thumbs/c75029d181cb49eaa606d0d72d5fc4a5.jpg', 'Start with the size of a board. A faint sound echoes through the hallway. You freeze, the heart is beating, and the house seems to breathe with you. You are inside the mansion of the old teacher once again.\r\n\r\nIn the 3D fear teacher, every shadow, every echo matters. Your goal is not to escape; it is mischief. But make an error, and you will become its next goal.', 'Adventure', 3, 'publish', '2026-04-19 08:55:01'),
(193, 'Draw Climb Race - The Ultimate Hill Climbing Challenge', 'e8d1ff1a11cb4810948b2e81d51d350c', 'https://html5.gamedistribution.com/e8d1ff1a11cb4810948b2e81d51d350c/', 'assets/thumbs/e8d1ff1a11cb4810948b2e81d51d350c.jpg', 'In Draw Climb Race, you draw shapes to climb hills! Any drawing you make will help you climb up steep hills and tricky paths. If you get stuck, just draw a new shape to keep going. Have fun and test your skills in this easy-to-play, addictive game!', 'Adventure', 6, 'publish', '2026-04-19 08:55:03'),
(194, 'CrazyZombies 3D', '4187d9fa2d5c46788b2c297e88c78639', 'https://html5.gamedistribution.com/4187d9fa2d5c46788b2c297e88c78639/', 'assets/thumbs/4187d9fa2d5c46788b2c297e88c78639.jpg', 'Crazy Zombies 3D is a fast-paced top-down zombie survival shooter with cartoon-style 3D graphics. Use 10+ weapons to fight endless waves of zombies, conquer a town map, and unlock powerful upgrades. Battle 5 zombie types and 4 deadly bosses with unique abilities. Customize your loadout and survive as long as you can. Fun, intense, and addictive—can you survive the apocalypse?\r\n\r\n?- Zombie Survival\r\n?- 10+ Weapons to Master\r\n?️- Conquer the Town\r\n?- Boss Battles\r\n?- Fun, Fast &amp; Addictive', 'Adventure', 6, 'publish', '2026-04-19 08:55:03'),
(195, 'Zombie Survival', 'ea59d60a601041a28afcb6af3dde0bdd', 'https://html5.gamedistribution.com/ea59d60a601041a28afcb6af3dde0bdd/', 'assets/thumbs/ea59d60a601041a28afcb6af3dde0bdd.jpg', 'Play the nervous zombie adventure in Zombie Survival. Explore a dangerous world occupied by zombies. Collect various weapons to attack zombies. Move smartly and set traps to defend yourself from massive zombie waves. Explore abandoned cities, dark alleys, and creepy forests - each level is a new adventure! Challenge big zombie bosses and prove your survival skills under pressure! Collect many useful items to fix your broken tools.', 'Adventure', 5, 'publish', '2026-04-19 08:55:20'),
(196, 'Minecraft Pixel Warfare', '94673205996e4f308045e87794ff6867', 'https://html5.gamedistribution.com/94673205996e4f308045e87794ff6867/', 'assets/thumbs/94673205996e4f308045e87794ff6867.jpg', 'Minecraft Pixel Warfare&quot; is a fast-paced PvP shooter set in blocky, Minecraft-inspired worlds. Players battle in competitive team modes (e.g., Team Deathmatch, Capture the Flag) or free-for-all arenas using guns, grenades, and melee weapons—all with Minecraft’s iconic pixelated visuals. Unlock skins, upgrade weapons, and master maps to dominate the leaderboard!', 'Adventure', 6, 'publish', '2026-04-19 08:55:22'),
(197, 'Gang War: Strike Shooter', 'd2a97a5322cf425b916e30ebed28020d', 'https://html5.gamedistribution.com/d2a97a5322cf425b916e30ebed28020d/', 'assets/thumbs/d2a97a5322cf425b916e30ebed28020d.jpg', 'Welcome to a fast-paced multiplayer shooter! Break out of prison and dive straight into a brutal gang war. Join the Reds or the Blues, capture banks, warehouses, factories, and other city locations. Each captured zone earns you income — spend it on new weapons and character customization!\r\n\r\nPlay with friends, compete for dominance, and survive the dangerous streets. Only strength, strategy, and loyal teammates matter here. An open world full of conflict, shootouts, and endless possibilities.', 'Shooter', 6, 'publish', '2026-04-19 09:00:24'),
(198, 'Zombie Survival Shooter', '53ad84c4f3b440f2b65d5382fadf731f', 'https://html5.gamedistribution.com/53ad84c4f3b440f2b65d5382fadf731f/', 'assets/thumbs/53ad84c4f3b440f2b65d5382fadf731f.jpg', 'Ready for an all-out apocalypse escape? Zombie Survival Shooter throws you straight into a world overrun by zombies. Zombies attack from every direction. Keep moving, dodge smartly, and never stop running. Shoot the digital doors to gain more helpers or boost your attack speed, etc. Use your strategy to choose which digital door to go through.', 'Shooter', 7, 'publish', '2026-04-19 09:00:53'),
(199, 'The Zombie House', 'ddc202e7d252451f8d1344f9f0e455ef', 'https://html5.gamedistribution.com/ddc202e7d252451f8d1344f9f0e455ef/', 'assets/thumbs/ddc202e7d252451f8d1344f9f0e455ef.jpg', 'Protect your home from endless waves of zombies!\r\nDefeat zombies to collect coins and ability drops.\r\nUse coins to upgrade both your player and your house.\r\nEach level makes the zombies stronger.\r\nHow long can you survive?', 'Shooter', 4, 'publish', '2026-04-19 09:01:16'),
(200, 'Marble Blast', '685ccaa7326c42be8aa2076801e82acd', 'https://html5.gamedistribution.com/685ccaa7326c42be8aa2076801e82acd/', 'assets/thumbs/685ccaa7326c42be8aa2076801e82acd.jpg', 'Ready to match, blast, and conquer? This vibrant marble shooter game offers endless fun and challenges that test your skills and strategy. Clear colorful marbles, unlock powerful boosters, and prove you’re the master of marble puzzles! Whether you’re a casual gamer or a puzzle enthusiast, this game delivers excitement like no other.', 'Shooter', 4, 'publish', '2026-04-19 09:01:19'),
(201, 'Road Of Fury 4', '8c7b4c26a7784cacbda79f8510c6256d', 'https://html5.gamedistribution.com/8c7b4c26a7784cacbda79f8510c6256d/', 'assets/thumbs/8c7b4c26a7784cacbda79f8510c6256d.jpg', 'Road Of Fury 4 is a scroller shooter game set in a world of post-apocalypse. Team-up with other nomads, upgrade cars, guns and super-powers and use your skills to fight through 30 levels and 3 bosses.', 'Shooter', 6, 'publish', '2026-04-19 09:01:19'),
(202, 'Battle Zone 2D', 'ca12cc5666a1430aa557452c3fbb0039', 'https://html5.gamedistribution.com/ca12cc5666a1430aa557452c3fbb0039/', 'assets/thumbs/ca12cc5666a1430aa557452c3fbb0039.jpg', 'Immerse yourself in a dynamic 2D top-down shooter. Fight on a vast map, search for weapons, ammo, and gear to survive epic battles. Use strategy, cover, and tactics to become the last survivor. Simple controls, fast-paced matches, and thrilling gameplay make the game accessible to everyone. Test your skills, defeat enemies, and prove that you are the best fighter!', 'Shooter', 7, 'publish', '2026-04-19 09:01:28'),
(203, 'Plants Warfare', '68d223b2b98240a2a41d21b4144e6333', 'https://html5.gamedistribution.com/68d223b2b98240a2a41d21b4144e6333/', 'assets/thumbs/68d223b2b98240a2a41d21b4144e6333.jpg', 'Plants Warfare is a shooting game where you step into the shoes of the cute plants. Aim your projectiles, and take down the zombies with strategic aiming and precision shots. Use the environment to your advantage—ricochet bullets and eliminate multiple targets with the least shots possible! Collect stars, customize your look, and prove you’re the ultimate plant defense.', 'Shooter', 6, 'publish', '2026-04-19 09:01:29'),
(204, 'Pew Pew Dose', '30909e6007a748539e41d75dfec483f4', 'https://html5.gamedistribution.com/30909e6007a748539e41d75dfec483f4/', 'assets/thumbs/30909e6007a748539e41d75dfec483f4.jpg', 'Build the weapon of your dreams and blast through hordes of cute… yet deadly zombie rascals!\r\n\r\nWelcome to a bright and crazy post-apocalypse where only the most creative weapon makers survive. In this arcade 3D mayhem, you start with a simple gun… and end up wielding a monster built from multiple barrels twisted together into insane contraptions!\r\n\r\nCraft without limits: attach barrel to barrel, add magazines, boost firepower, and create unique weapons that would make enemies run away…', 'Shooter', 5, 'publish', '2026-04-19 09:01:32'),
(205, 'Noob vs Zombie Apocalypse: shooting pro', '92e2ea1340a4401bbec402925a611e76', 'https://html5.gamedistribution.com/92e2ea1340a4401bbec402925a611e76/', 'assets/thumbs/92e2ea1340a4401bbec402925a611e76.jpg', 'Post-apocalypse! Noob finds himself alone against zombies. Passing levels, he accumulates coins and picks up weapons.\r\nThere is a grenade launcher, a pistol, an uzi, a shotgun, a machine gun, a laser pistol, a rifle, a laser rifle - and so on!\r\n\r\nNoob vs Zombie Apocalypse: shooting pro is an epic noob game in the world, similar to minecraft fnaf. Noob shoots at zombies with a variety of weapons like a rambo. Noob miner starts his fighting fnaf survival!\r\n\r\nThere are 60 levels and 15 bosses in total!', 'Shooter', 5, 'publish', '2026-04-19 09:02:10'),
(206, 'Last Ufo Defense', 'ed76913882be488e992262a466d3fff2', 'https://html5.gamedistribution.com/ed76913882be488e992262a466d3fff2/', 'assets/thumbs/ed76913882be488e992262a466d3fff2.jpg', 'Last UFO DefenseThe galaxy is no safe place. \r\nAs the last UFO of your kind, you stand alone against endless waves of hostile alien forces determined to wipe you out.\r\nPilot your hovering warship and unleash its full potential:One UFO, endless enemies. \r\nSurvive as long as you can with precise upgrades and tactical choices.\r\nFace relentless alien swarms in an endless survival challenge.You are the final line of defense in a hostile galaxy.\r\nHow long can the last UFO endure?', 'Shooter', 7, 'publish', '2026-04-19 09:02:11'),
(207, 'SWAT Cats Shooter', 'bf6439db0088415593e786e19a04e5b3', 'https://html5.gamedistribution.com/bf6439db0088415593e786e19a04e5b3/', 'assets/thumbs/bf6439db0088415593e786e19a04e5b3.jpg', 'SWAT Cats is an online shooter set in a world where every hero is a battle cat. Ready for purr-fect battle with wild action? Jump in, grab your helmet, and join the fight.', 'Shooter', 4, 'publish', '2026-04-19 09:02:13'),
(208, 'Zombie Horde: Build &amp; Survive', 'b6b0c354a8914a4892c719de3c978537', 'https://html5.gamedistribution.com/b6b0c354a8914a4892c719de3c978537/', 'assets/thumbs/b6b0c354a8914a4892c719de3c978537.jpg', 'Step into the chaos of Zombie Horde: Build &amp; Survive, a free online game where your survival depends on smart defenses and sharp shooting. Play on your phone or computer as you fight off endless waves of the undead. Set up turrets, lay traps, and build barricades to hold the line while unleashing powerful weapons. In this post-apocalyptic world, every second counts—can you keep the horde at bay?', 'Shooter', 8, 'publish', '2026-04-19 09:02:16'),
(209, 'Space.io', '01a2209f6b014104951400328089a30d', 'https://html5.gamedistribution.com/01a2209f6b014104951400328089a30d/', 'assets/thumbs/01a2209f6b014104951400328089a30d.jpg', 'Jump into the cockpit of a powerful spaceship and engage in fast-paced 3D space battles! Face off against 9 other enemy ships in an intense dogfight where only the best pilot survives. Shoot down your opponents before they take you out, climb the rankings, and prove you\'re the ultimate space warrior! Unlock a wide variety of skins to customize your ship and dominate the battlefield in style. Can you claim the top spot?', 'Shooter', 5, 'publish', '2026-04-19 09:02:20'),
(210, 'Chicken Math', '877356dc859c48f3b7e1922a48110439', 'https://html5.gamedistribution.com/877356dc859c48f3b7e1922a48110439/', 'assets/thumbs/877356dc859c48f3b7e1922a48110439.jpg', 'I am Archimedes. I\'ve been trying to solve this difficult problem for a week, and those chickens have stolen my numbers again. Grab the rifle and head to the backyard. Find and retrieve my numbers. Just be careful — I need the correct numbers!', 'Shooter', 6, 'publish', '2026-04-19 09:02:23'),
(211, 'Ammo Rush Master', '4d4a37a2047f42feb66e746959be9177', 'https://html5.gamedistribution.com/4d4a37a2047f42feb66e746959be9177/', 'assets/thumbs/4d4a37a2047f42feb66e746959be9177.jpg', 'Get ready to run, multiply, and blast your way to victory in Ammo Rush Master!\r\nDodge obstacles, choose the right gates, and build the biggest Ammo army of bullets. Then, grab your blaster and unleash a storm of foam darts to smash through targets, enemies, and bosses!', 'Shooter', 5, 'publish', '2026-04-19 09:02:27'),
(212, 'Aliens Hunter', '6259b8781bfe4a1dbcd274ca61837902', 'https://html5.gamedistribution.com/6259b8781bfe4a1dbcd274ca61837902/', 'assets/thumbs/6259b8781bfe4a1dbcd274ca61837902.jpg', 'You are an alien hunter and your mission is to use your abilities to find the aliens hidden in the city and use your gun to accurately shoot the aliens to get rewards. Each round has different aliens hiding in different locations. You have to accurately choose, aim and shoot to complete the level mission.', 'Shooter', 4, 'publish', '2026-04-19 09:02:35'),
(213, 'Murderers VS Sheriffs Duels', 'ae61bf1a3a834b238384329766580768', 'https://html5.gamedistribution.com/ae61bf1a3a834b238384329766580768/', 'assets/thumbs/ae61bf1a3a834b238384329766580768.jpg', 'Love Roblox-style action games? Get ready for the ultimate showdown!\r\n\r\nJump into fast-paced 1v1, 2v2, 3v3, and 4v4 duels where every second counts. Play as a Murderer or a Sheriff, master unique abilities, and outplay your enemies in style.\r\n\r\nIf you enjoy games like Murder Mystery or Arsenal in Roblox, this is made for you!', 'Shooter', 6, 'publish', '2026-04-19 09:02:39'),
(214, 'Zombie Road: Shooter with Destruction', '1669d535753248c39bee2cbf6746f2e5', 'https://html5.gamedistribution.com/1669d535753248c39bee2cbf6746f2e5/', 'assets/thumbs/1669d535753248c39bee2cbf6746f2e5.jpg', 'Grandpa is eager for adventure again! Survive in a harsh zombie world. This time, Grandpa has to save the world from evil zombies. Zombies can drive and shoot! And Grandpa can destroy evil spirits! Fight the most dangerous mutants. Buy cool guns, find unique attachments, assemble your own unique gun and go into battle! Many locations, go through the whole world, from hot deserts to sea battles!', 'Shooter', 5, 'publish', '2026-04-19 09:02:41'),
(215, 'STELLAR GUARDIAN', '68b9d83103d2484583d69df6c5f985e3', 'https://html5.gamedistribution.com/68b9d83103d2484583d69df6c5f985e3/', 'assets/thumbs/68b9d83103d2484583d69df6c5f985e3.jpg', 'Stellar Guardian – Cosmic Defense Force is a fast-paced space shooter where you command powerful ships, unlock upgrades, and defend the galaxy across challenging missions and game modes. to fix the lag you need to keep the PC on a full screen, while on other devices it runs smoothly', 'Shooter', 6, 'publish', '2026-04-19 09:02:46'),
(216, 'AOD - Art Of Defense', '941d9c0be5f24d83a1e5ca336f3e6ae4', 'https://html5.gamedistribution.com/941d9c0be5f24d83a1e5ca336f3e6ae4/', 'assets/thumbs/941d9c0be5f24d83a1e5ca336f3e6ae4.jpg', 'Step into the world of AOD - Art Of Defense, a free online strategy game where your main goal is to stop enemy waves by placing towers in smart locations. Play on your phone or computer and test your skills in this action-packed defense challenge. Every move matters—can you build the perfect defense?', 'Shooter', 8, 'publish', '2026-04-19 09:02:48'),
(217, 'Idle Pop Merge', 'eabe56a091214e9baae5c7545739b53e', 'https://html5.gamedistribution.com/eabe56a091214e9baae5c7545739b53e/', 'assets/thumbs/eabe56a091214e9baae5c7545739b53e.jpg', 'Get ready for endless fun in Idle Pop Merge! Drag and drop characters into the slots to merge them into stronger versions. The more you merge, the more powerful your team becomes. It\'s a simple, addictive game that anyone can enjoy—whether you’re on desktop or mobile. Perfect for players who love puzzle challenges with a strategic twist!', 'Shooter', 5, 'publish', '2026-04-19 09:03:02'),
(218, 'Grandma\'s Last Stand', '74e6969ad0f647c9872a30153f47b8fe', 'https://html5.gamedistribution.com/74e6969ad0f647c9872a30153f47b8fe/', 'assets/thumbs/74e6969ad0f647c9872a30153f47b8fe.jpg', 'Granny is in a hurry to get home and bake some pies. But there\'s one problem - first she needs to bake a few hundred zombies! They\'ll be chasing you in cars and motorcycles, they\'ll have machine guns, rocket launchers, and support drones. But you\'ve got a pretty good arsenal too - from a revolver and machine guns to a minigun and a bazooka. Help Granny get home, roast them all!\r\n\r\nINSTRUCTIONS', 'Shooter', 5, 'publish', '2026-04-19 09:03:04'),
(219, 'Air Strike 2D', '9da40c9b342846f99339b7c4c8a428b7', 'https://html5.gamedistribution.com/9da40c9b342846f99339b7c4c8a428b7/', 'assets/thumbs/9da40c9b342846f99339b7c4c8a428b7.jpg', 'Become a bomber pilot and fly an army airplane in epic air strikes! Drop bombs, destroy tanks, cannons and soldiers, intercept missiles and shoot down drones. Eliminate enemy troops and destroy their military bases. Upgrade your aircraft with deadly weapons and cool gear. Dominate the battlefield from the sky and defeat the villain general in a final airstrike!', 'Shooter', 7, 'publish', '2026-04-19 09:03:13'),
(220, 'Grandma with machine-gun: Apocalypsis', '9814a081a1a4495991bc8634296d5a82', 'https://html5.gamedistribution.com/9814a081a1a4495991bc8634296d5a82/', 'assets/thumbs/9814a081a1a4495991bc8634296d5a82.jpg', 'Granny is in a hurry to get home and bake some pies. But there\'s one problem - first she needs to bake a few hundred zombies! They\'ll be chasing you in cars and motorcycles, they\'ll have machine guns, rocket launchers, and support drones.\r\nBut you\'ve got a pretty good arsenal too - from a revolver and machine guns to a minigun and a bazooka.\r\nHelp Granny get home, roast them all!', 'Shooter', 3, 'publish', '2026-04-19 09:03:13'),
(221, 'Zombie Monster Survivors', '105d61fde9324ffaac5d14f1769bdf1e', 'https://html5.gamedistribution.com/105d61fde9324ffaac5d14f1769bdf1e/', 'assets/thumbs/105d61fde9324ffaac5d14f1769bdf1e.jpg', 'Zombie Monster Survivors is a role-playing game where you will become a brave survivor. Fight against terrifying zombies and monsters in an amazing world. Use your resources wisely and defeat the monsters and zombies that keep coming. Try to survive in this extreme environment. Keep moving and attack large waves of zombies. Collect coins or energy and choose your skills.', 'Shooter', 4, 'publish', '2026-04-19 09:03:17'),
(222, 'Mr Cappuccino Assassino', 'bc1a67b30e674373b2f2af526d63e6e4', 'https://html5.gamedistribution.com/bc1a67b30e674373b2f2af526d63e6e4/', 'assets/thumbs/bc1a67b30e674373b2f2af526d63e6e4.jpg', 'Are you ready to become a hero, Capu Hero, and legend? Solve puzzling challenges, show off your deadly accuracy and take aim at the enemies. Come experience the shooting phenomenon.\r\n\r\nUse your brain in this unique puzzle game. You will need precise aim and laser focus to take down enemies, agents, and many other bad guys you will encounter in the world! \r\n\r\nCollect stars and unlock new Brainrot characters', 'Shooter', 6, 'publish', '2026-04-19 09:03:25'),
(223, 'CS: Chaos Squad', 'dec78e8b416948f19832618a64afb0d7', 'https://html5.gamedistribution.com/dec78e8b416948f19832618a64afb0d7/', 'assets/thumbs/dec78e8b416948f19832618a64afb0d7.jpg', 'CS: Chaos Squad is an exciting 5v5 team-based shooter that demands tactical thinking, teamwork, and quick reflexes. Engage in fast-paced battles where you can purchase weapons and gear each round, allowing you to adapt your strategy on the fly. The ranking system tracks player and team performance, encouraging continuous improvement and competition. Fight for victory, build team synergy, and prove that your squad is the best on the battlefield!', 'Shooter', 5, 'publish', '2026-04-19 09:03:30'),
(224, 'STALKER-Strike', 'a4ca6284c30447e79b6fb81223d1c264', 'https://html5.gamedistribution.com/a4ca6284c30447e79b6fb81223d1c264/', 'assets/thumbs/a4ca6284c30447e79b6fb81223d1c264.jpg', 'STALKER-Strike is a tactical online shooter inspired by CS and Valorant — but set in a deadly Zone filled with anomalies. Fight as stalkers or special forces in fast-paced PvP battles where hazards can shift the tide. Level up, survive traps, and prove your skills. Love CS, Standoff, or Valorant? Then step into the Zone and become a legend in this intense fusion of esports action and danger!', 'Shooter', 6, 'publish', '2026-04-19 09:03:34'),
(225, 'Sniper Wars: Find the Criminal', 'ee89787adb7b4ddcbb3eba00fee19581', 'https://html5.gamedistribution.com/ee89787adb7b4ddcbb3eba00fee19581/', 'assets/thumbs/ee89787adb7b4ddcbb3eba00fee19581.jpg', 'The snipers have begun the battle! Find the villain among the crowd of citizens and eliminate him. Take a rifle and go on a dangerous mission to find the criminal! You have a photo of the criminal and a rifle, find him and eliminate him!', 'Shooter', 7, 'publish', '2026-04-19 09:03:35'),
(226, 'Squid Game: Playground Shooter', '204247304ea246a6814a89e06cc7aa10', 'https://html5.gamedistribution.com/204247304ea246a6814a89e06cc7aa10/', 'assets/thumbs/204247304ea246a6814a89e06cc7aa10.jpg', 'In &quot;Squid Game: Playground Shooter&quot;, every shot triggers a wave of chaos-take down all the Squid Game characters in the level and watch them fly around with crazy physics!\r\n\r\nWhat’s waiting for you:\r\n- Switch guns and enjoy unique effects with every shot.\r\n- Each scene is a new challenge and a chance to create Squid Game-style chaos.\r\n- Explosions, traps, interactive objects\r\n– Instantly recognizable icons!\r\n\r\nDive into the shooting frenzy and ragdoll madness!', 'Shooter', 5, 'publish', '2026-04-19 09:03:37'),
(227, 'Timewalker: Survive!', 'b9bde9f7b60f44b6832384a50000dc72', 'https://html5.gamedistribution.com/b9bde9f7b60f44b6832384a50000dc72/', 'assets/thumbs/b9bde9f7b60f44b6832384a50000dc72.jpg', 'Time Walker: Survive – Embark on a thrilling journey through apocalyptic landscapes in this fast-paced 2D top-down survival game! As a Timewalker, battle relentless hordes of zombies across different eras, fighting for survival against increasingly intense waves of the undead.', 'Shooter', 6, 'publish', '2026-04-19 09:03:54'),
(228, 'Serious Head', '72819ef0b4404b5a8d9bd4530f34938a', 'https://html5.gamedistribution.com/72819ef0b4404b5a8d9bd4530f34938a/', 'assets/thumbs/72819ef0b4404b5a8d9bd4530f34938a.jpg', 'Prepare to defend yourself. Purchase defensive structures, recharge your energy and fight off waves of monsters. Kill bosses and upgrade weapons. Complete the final day and close the portals!', 'Shooter', 6, 'publish', '2026-04-19 09:03:55'),
(229, 'World War 2 Shooter', '5b0d2de3a13a4b6a81b70b6d6768aa7e', 'https://html5.gamedistribution.com/5b0d2de3a13a4b6a81b70b6d6768aa7e/', 'assets/thumbs/5b0d2de3a13a4b6a81b70b6d6768aa7e.jpg', 'World War 2 Shooter is a new first person shooter where you can become a real soldier of World War 2 and fight against enemies! Defeat foes in dynamic battles and be a hero on the battlefield!', 'Shooter', 6, 'publish', '2026-04-19 09:03:55'),
(230, 'Strykon', '59361631a2614fc095ef2a1740e02d78', 'https://html5.gamedistribution.com/59361631a2614fc095ef2a1740e02d78/', 'assets/thumbs/59361631a2614fc095ef2a1740e02d78.jpg', 'Strykon is a mobile FPS game with exciting missions and battles. Play different modes like Deathmatch, Team Deathmatch, and Free-for-All, where your goal is to survive.\r\nChoose from many weapons, like pistols, rifles, shotguns, and snipers. Each gun has its own style. Enjoy great graphics, realistic sound, and easy controls. Earn rewards with the Battle Pass to keep the game interesting. Whether you complete missions or fight enemies, this shooter is full of action anytime, anywhere!', 'Shooter', 5, 'publish', '2026-04-19 09:03:58'),
(231, 'Two Archers: Bow Duel', '017920ea7a7a41cebd5a05bb4f9fa994', 'https://html5.gamedistribution.com/017920ea7a7a41cebd5a05bb4f9fa994/', 'assets/thumbs/017920ea7a7a41cebd5a05bb4f9fa994.jpg', 'Get ready for a great battle at the Archery Tournament, because no one is going to just give up and let you win. With each new battle, your enemies will only become stronger. But you shouldn\'t stay put either. Buy new equipment. A huge selection of different bows will help you defeat your enemies, from simple wooden ones to magical golden bows with incendiary arrows! Earn money by participating in the tournament.', 'Shooter', 4, 'publish', '2026-04-19 09:04:05'),
(232, 'Fox Adventure', 'a8ac99e5ba244f5fb4138880dbee5339', 'https://html5.gamedistribution.com/a8ac99e5ba244f5fb4138880dbee5339/', 'assets/thumbs/a8ac99e5ba244f5fb4138880dbee5339.jpg', 'Is a dynamic endless runner that brings back the spirit of classic arcade games!\r\nRun or Lose! Control a brave fox in a world where danger lurks at every step. Fiery meteors rain down from the sky, and deadly spikes cover the ground. Your reflexes are your best weapon. Jump, dodge, and survive as long as you can!\r\nBuild Your Collection Grab gold coins along the way! Visit the shop to unlock unique looks: become a futuristic Cyber-Fox, put on a Clown costume, wear the Royal robe.', 'Agility', 6, 'publish', '2026-04-19 09:04:26'),
(233, 'Rough Ball', 'bc9e48b8a60142a79b44259398160d98', 'https://html5.gamedistribution.com/bc9e48b8a60142a79b44259398160d98/', 'assets/thumbs/bc9e48b8a60142a79b44259398160d98.jpg', 'Bounce wildly in Rough Ball! Control your cute purple ball across wall-to-wall platforms, dodging spikes, skulls, and deadly drops. Collect shiny coins, unlock free burger skins, and conquer chaotic levels. Don\'t fall down—jump, roll, and thrive in pixel-perfect adventure!', 'Agility', 8, 'publish', '2026-04-19 09:04:49'),
(234, 'Stickman Zombie vs Stickman Hero', 'e28bcc262b6245dc806dba3a43d057ce', 'https://html5.gamedistribution.com/e28bcc262b6245dc806dba3a43d057ce/', 'assets/thumbs/e28bcc262b6245dc806dba3a43d057ce.jpg', 'Stickman Zombie vs Stickman Hero is a stick war game about zombies, stickman, noob and pro who stole lucky block. The zombie boss is chasing them to bring the lucky block back to the roblox world, but the stickman hero escapes, resurrecting his allies along the way/\r\n\r\nGame Features:\r\n- You run away from the zombie boss and then play as him against the animator\r\n- Various zombie, baldi and stickman animations\r\n- The game is similar in style to minecraft, stick war, roblox and noob vs p', 'Agility', 7, 'publish', '2026-04-19 09:04:54'),
(235, 'Stick Master Teleport', 'a497f71f7ff64128bb9f3d4f7a58dddc', 'https://html5.gamedistribution.com/a497f71f7ff64128bb9f3d4f7a58dddc/', 'assets/thumbs/a497f71f7ff64128bb9f3d4f7a58dddc.jpg', 'Jump onto walls, throw knives, and teleport to your enemies ⚔️ to defeat them with a single strike.\r\nProve your ninja reputation by eliminating bad guys before they even notice.\r\nWalk the tough path of a ninja to become a true ninja assassin!', 'Agility', 6, 'publish', '2026-04-19 09:04:57'),
(236, 'Robbie: Stand on the Right Color!', 'ccb9423ce3234ca9a033cf8c3476bdf8', 'https://html5.gamedistribution.com/ccb9423ce3234ca9a033cf8c3476bdf8/', 'assets/thumbs/ccb9423ce3234ca9a033cf8c3476bdf8.jpg', 'Welcome to the vibrant world of speed and reaction!\r\nYou are about to be tested on your attentiveness and lightning-fast decisions. Your task is simple but tricky: step on the right color before the floor disappears beneath your feet!\r\nSuitable for anyone who loves fast, simple, and addictive games.\r\nAre you ready to help Robbie stand his ground?', 'Agility', 6, 'publish', '2026-04-19 09:05:04'),
(237, 'Impostor among us: Escape from prison', '0946201a460c4fd191f32bd497ee6c2a', 'https://html5.gamedistribution.com/0946201a460c4fd191f32bd497ee6c2a/', 'assets/thumbs/0946201a460c4fd191f32bd497ee6c2a.jpg', 'The traitor ended up in a space prison. But the impostor does not plan to stay there for long. You play as an impostor who must go through all the traps, solve puzzles and kill all the enemies on the level. Once the imposter has neutralized all the amogus, he will be able to break out of prison. But the evil among will not let you go into space so easily.\r\n\r\n- 100+ varied and colorful levels.\r\n- To kill the enemy you need to approach him.\r\n- Logic tasks and puzzles!\r\n- Boss battles!', 'Agility', 5, 'publish', '2026-04-19 09:05:06'),
(238, 'NinjaRoof', '6bfd6b77827c418eb5dc2d33be6bc911', 'https://html5.gamedistribution.com/6bfd6b77827c418eb5dc2d33be6bc911/', 'assets/thumbs/6bfd6b77827c418eb5dc2d33be6bc911.jpg', 'NinjaRoof is a fast-paced and addictive arcade game where players control a nimble character jumping from rooftop to rooftop while avoiding deadly obstacles and aiming for the highest score. Test your timing, precision, and reflexes in this endless jumping adventure built with smooth physics and clean visuals.', 'Agility', 7, 'publish', '2026-04-19 09:05:10'),
(239, 'Fly and shoot 1. Italian Bosses', '63db3ede64e343c8a9fb4f91e29b7b08', 'https://html5.gamedistribution.com/63db3ede64e343c8a9fb4f91e29b7b08/', 'assets/thumbs/63db3ede64e343c8a9fb4f91e29b7b08.jpg', 'Nostalgia for 8-bit games. A classic arcade shooter with leveling elements and character selection. Fly and shoot, take down enemies, and blow up and destroy everything in your path. Defeat the boss at the end of each level. Save Laba and earn bonuses for doing so. Each difficulty level is slightly different. Enemies become more aggressive, and the speed increases.', 'Agility', 5, 'publish', '2026-04-19 09:05:15'),
(240, 'Coe Snake', 'b73efc1f47194a4cbb5d0af8b492187b', 'https://html5.gamedistribution.com/b73efc1f47194a4cbb5d0af8b492187b/', 'assets/thumbs/b73efc1f47194a4cbb5d0af8b492187b.jpg', 'Coe Snake brings the classic snake game with new challenges! Collect fruits, dodge meteors, walls, bombs, and balls that move like ping pong. Multiple modes, scenarios, and fruits to choose from. Fast-paced, colorful, and addictive — how far can you go?', 'Agility', 6, 'publish', '2026-04-19 09:05:24'),
(241, 'Strawberry Hero', '500b319ce147450686184de6dd46856b', 'https://html5.gamedistribution.com/500b319ce147450686184de6dd46856b/', 'assets/thumbs/500b319ce147450686184de6dd46856b.jpg', 'Stick your fork and climb to the top! Hold down to keep sticking the fork continuously. If your fork hits a hero or an obstacle, it’s game over! Stick the fork just above the falling hero’s feet to trigger a Super Jump and earn a high score!', 'Agility', 4, 'publish', '2026-04-19 09:05:28'),
(242, 'Obby Modes! Online Mini-Games', '7fb77a35cb98418c9a8b16278e7b74b0', 'https://html5.gamedistribution.com/7fb77a35cb98418c9a8b16278e7b74b0/', 'assets/thumbs/7fb77a35cb98418c9a8b16278e7b74b0.jpg', 'Is a massive online world where three unique modes are waiting for you!\r\n\r\nTake on the challenge of 100 levels of hard obby, compete in crazy races with 5 players, and test your fate on a glass bridge in the spirit of Squid Game!\r\n\r\nCreate your unique character by choosing from over 100 cool skins!\r\n\r\nTeam up with friends using a code in squads of up to 3 people and conquer all modes together!\r\n\r\nReady to show off your agility and strategy? Set records and become a legend!', 'Agility', 9, 'publish', '2026-04-19 09:05:39'),
(243, 'Drunken Fighters', 'd0c31b0603f24b43b33e4b93d13d64bf', 'https://html5.gamedistribution.com/d0c31b0603f24b43b33e4b93d13d64bf/', 'assets/thumbs/d0c31b0603f24b43b33e4b93d13d64bf.jpg', 'Are you ready for an adrenaline-filled fighting adventure?\r\n\r\nStep into the ring in Drunken Fighters’ single-player mode and face opponents that will test your reflexes, or grab a friend and fight in two-player mode on the same device.\r\n\r\nMaster ragdoll physics and boost the thrill with Funny Mod options: Stretch Kick, Stretch Punch, Big Punch, Super Punch, and Big Head or let Random Mode surprise you with chaos!', 'Agility', 4, 'publish', '2026-04-19 09:05:43'),
(244, 'Noob: parkour tricks', 'f97244f04ed44f83bdae1f71c02361cb', 'https://html5.gamedistribution.com/f97244f04ed44f83bdae1f71c02361cb/', 'assets/thumbs/f97244f04ed44f83bdae1f71c02361cb.jpg', 'Welcome to Noob: Parkour tricks!\r\n\r\nThis is a runner and timekiller in the minecraft universe about the adventures of Noob. Do parkour tricks and complete challenges.\r\n\r\nMonster School kicked out Noob, and Herobrine turned him into a Gigachad!\r\n\r\nGame Features:\r\n- Run through the village with trials.\r\n- Do parkour tricks.\r\n- Complete challenges and avoid traps.\r\n- Collect diamonds.\r\n- Unlock new skins.', 'Agility', 6, 'publish', '2026-04-19 09:05:47'),
(245, 'Family Squid Challenge', '806ccd2db43a4bf7a9ebaf31723e2bca', 'https://html5.gamedistribution.com/806ccd2db43a4bf7a9ebaf31723e2bca/', 'assets/thumbs/806ccd2db43a4bf7a9ebaf31723e2bca.jpg', 'Hey Player, bring your friend along and team up in this Squid adventure! There are black and red masked men everywhere, so you must be very careful. Run from them and collect the keys to complete the level. Be cautious — both of you need to survive!', 'Agility', 7, 'publish', '2026-04-19 09:05:47'),
(246, 'Natural disaster survival Obby', '2c98c9a7a3774dcfb5e716f8e2f908e4', 'https://html5.gamedistribution.com/2c98c9a7a3774dcfb5e716f8e2f908e4/', 'assets/thumbs/2c98c9a7a3774dcfb5e716f8e2f908e4.jpg', 'Immerse yourself in an exciting Roblox-style adventure with the game “Natural disaster survival Obby”! \r\n\r\nDynamic maps are waiting for you, where disasters are happening every second - lava flows, floods, tornadoes and much more. Pass the obby trials, dodge the dangers and try to survive the longest! \r\n\r\nPlay online with friends and other players from all over the world. \r\nUnlock stylish skins and unique pets to stand out from the rest.', 'Agility', 4, 'publish', '2026-04-19 09:06:24'),
(247, 'Obby: Gym Simulator, Escape', '4a198f856f07451bb7418eae9a0c4112', 'https://html5.gamedistribution.com/4a198f856f07451bb7418eae9a0c4112/', 'assets/thumbs/4a198f856f07451bb7418eae9a0c4112.jpg', 'Help Obby build up his muscles to escape from the castle!\r\nSwing and get bigger!\r\n\r\nThe game has a rank system.\r\nDefeat bosses, compete with other players for the first place in the ranking!\r\n\r\nSpend cups on eggs, collect all the pets.\r\nThey will help you swing much faster.\r\n\r\nIt\'s up to you to press a barbell, carry weights or lift dumbbells.', 'Agility', 4, 'publish', '2026-04-19 09:06:26'),
(248, 'Lava Jump', 'f3a6224a65b548b79dada0bacc0f5175', 'https://html5.gamedistribution.com/f3a6224a65b548b79dada0bacc0f5175/', 'assets/thumbs/f3a6224a65b548b79dada0bacc0f5175.jpg', 'Lava Jump is a fast-paced parkour platformer set in a deadly lava-filled dungeon! Jump across moving blocks, bounce off boost pads, and ride shifting platforms to survive. Complete more than 25 levels, evade enemies, spikes and other deadly objects and escape from the lava dungeon alive. Collect coins and get new characters to use in your adventure.', 'Agility', 6, 'publish', '2026-04-19 09:06:27'),
(249, 'Survival master: 456 Challenge', 'd01d3715c93c4c149afb4d132e4e43a3', 'https://html5.gamedistribution.com/d01d3715c93c4c149afb4d132e4e43a3/', 'assets/thumbs/d01d3715c93c4c149afb4d132e4e43a3.jpg', 'Surval master: 456 Challenge is a sequel where participants undergo unique survival tests, facing moral dilemmas and dangers. Are you ready for the challenge?', 'Agility', 8, 'publish', '2026-04-19 09:06:28'),
(250, 'Brainrot Hook Swing', '54a667dc8d03480d9191137150cf1f88', 'https://html5.gamedistribution.com/54a667dc8d03480d9191137150cf1f88/', 'assets/thumbs/54a667dc8d03480d9191137150cf1f88.jpg', 'Brainrot Hook Swing is an addictive physics-based platformer where players control the Brainrot swinging through levels using a grappling hook. With smooth animations, challenging obstacles, and fun physics mechanics, the game tests your timing and precision as you swing from one point to another, avoiding obstacles and making daring jumps to reach the finish line.', 'Agility', 4, 'publish', '2026-04-19 09:06:30'),
(251, 'Grocery Shop: Supermarket Game', 'ed33df475992488bbb6b576a6acf6cba', 'https://html5.gamedistribution.com/ed33df475992488bbb6b576a6acf6cba/', 'assets/thumbs/ed33df475992488bbb6b576a6acf6cba.jpg', 'Run and manage your own supermarket in this engaging simulation game. Stock shelves, serve customers, manage inventory, and expand your store to build a successful grocery business. Handle the rush of customers while keeping products organized and priced competitively to maximize profits.', 'Agility', 5, 'publish', '2026-04-19 09:06:35'),
(252, 'Night Club Security', '09d017664cad49e9a36d455b3aa046e5', 'https://html5.gamedistribution.com/09d017664cad49e9a36d455b3aa046e5/', 'assets/thumbs/09d017664cad49e9a36d455b3aa046e5.jpg', 'Immerse yourself in the unique atmosphere of a security guard simulator inspired by the cult game I\'m Security.\r\n\r\nCheck visitors for prohibited items, decide who is worthy of entry and who is not. Your power is absolute, because you are an unlimited security guard! Use your imagination to have fun and unusual &quot;entertainment&quot; with visitors, leaving them without things or even with a couple of bruises. Everything that happens is in your hands.', 'Simulation', 4, 'publish', '2026-04-19 09:07:47'),
(253, 'My Cake Shop: Bake &amp; Serve', 'bd478cd5791e4568a2352f5a03d35ed1', 'https://html5.gamedistribution.com/bd478cd5791e4568a2352f5a03d35ed1/', 'assets/thumbs/bd478cd5791e4568a2352f5a03d35ed1.jpg', 'Run your own sweet bakery in My Cake Shop! Bake and stack colorful donuts, clean messy floors, and serve hungry customers. Expand across the world by unlocking new bakery locations and upgrading machines. Manage crowds, grow your patisserie empire, and become the ultimate idle arcade tycoon!', 'Simulation', 8, 'publish', '2026-04-19 09:07:54'),
(254, 'School simulator: My school', '005de4e1a9064e4191b9cd1aec496550', 'https://html5.gamedistribution.com/005de4e1a9064e4191b9cd1aec496550/', 'assets/thumbs/005de4e1a9064e4191b9cd1aec496550.jpg', 'Welcome to School Simulator: My School! In this game you need to manage your school, open new classrooms, toilets, canteen, hire staff and help students to learn.\r\nThe more classes, the more schoolchildren. The more schoolchildren, the more money. The more money, the more opportunities to develop the school.', 'Simulation', 5, 'publish', '2026-04-19 09:08:23'),
(255, 'Dino Idle Park', 'e60b6dcfbc1e4027a11abc8dc3959669', 'https://html5.gamedistribution.com/e60b6dcfbc1e4027a11abc8dc3959669/', 'assets/thumbs/e60b6dcfbc1e4027a11abc8dc3959669.jpg', 'Dino Idle Park is a relaxing leisure real estate tycoon where you create and develop a dinosaur amusement park. Expand plots, release and display dinosaurs, optimize queues and parks, hire staff, and upgrade investments to increase funds and income. Balance safety, visitor happiness, and research to keep the park thriving even when youre away.', 'Simulation', 11, 'publish', '2026-04-19 09:08:41'),
(256, 'Steal Brainrot Eggs', 'e07da43b39e443738d6a84a4a6255c32', 'https://html5.gamedistribution.com/e07da43b39e443738d6a84a4a6255c32/', 'assets/thumbs/e07da43b39e443738d6a84a4a6255c32.jpg', 'Steal Brainrot Eggs is a competitive action game playable in both 1 Player and 2 Player modes. Players buy eggs from a central conveyor, carry them to their Base, and hatch random Brainrot characters based on egg rarity. Characters generate coins over time, allowing access to higher-tier eggs. Defend your Base from thieves or steal eggs and characters from rivals, customize your character, raise evolving pets, and take part in timed events across the map.', 'Simulation', 6, 'publish', '2026-04-19 09:08:42'),
(257, 'Steal Brainrot Arena', '4592e84523ad49a8b80986c3aa503429', 'https://html5.gamedistribution.com/4592e84523ad49a8b80986c3aa503429/', 'assets/thumbs/4592e84523ad49a8b80986c3aa503429.jpg', 'Steal Brainrot Arena is a fast-paced collection and heist game where every match turns into a battle of wallets, wits, and sneaky steals. Play solo in 1 Player mode or team up and compete in 2 Player mode as you build the ultimate Brainrot lineup. With over 45+ brainrot characters to discover, your goal is simple: buy better Brainrots, earn more, and create the most stacked collection in the arena.', 'Simulation', 7, 'publish', '2026-04-19 09:08:47'),
(258, 'Parking Driver', '60cc69e078184c63bf3568d975c348a4', 'https://html5.gamedistribution.com/60cc69e078184c63bf3568d975c348a4/', 'assets/thumbs/60cc69e078184c63bf3568d975c348a4.jpg', 'Ever struggled to find a parking spot? In &quot;Parking Driver,&quot; you\'ll face tricky parking challenges! From tight parallel parking to complex reverse maneuvers, you need precise control to avoid obstacles and park perfectly in the shortest time. The game features a realistic physics engine and diverse level designs, each testing your patience and skill. Come prove your driving prowess, unlock cool new cars, and conquer every parking lot!', 'Simulation', 7, 'publish', '2026-04-19 09:08:50'),
(259, 'Obby Rainbow Tower', '57de0fa8b9fb4df783e7eb8248ac5e5a', 'https://html5.gamedistribution.com/57de0fa8b9fb4df783e7eb8248ac5e5a/', 'assets/thumbs/57de0fa8b9fb4df783e7eb8248ac5e5a.jpg', 'Obby Rainbow Tower is a fast, winter-themed tower race where every second and every jump matters. Each floor is packed with moving platforms, icy tiles, spinning lava bars, surprise snowstorms and snowball portals that try to knock you into the void.  You can replay the tower as many times as you like, trying to beat your own best time or racing a friend side by side in 2 player mode.', 'Simulation', 8, 'publish', '2026-04-19 09:08:55'),
(260, 'My Arcade Center', '1ae5b8b1590c4119bb5163d98b51be2c', 'https://html5.gamedistribution.com/1ae5b8b1590c4119bb5163d98b51be2c/', 'assets/thumbs/1ae5b8b1590c4119bb5163d98b51be2c.jpg', 'My Arcade Center is a fast-paced management game where you build and expand your own arcade. Earn tokens by day, upgrade machines by night, hire staff, use coin bots, and handle freeloaders and vandals. Unlock new machines, optimize layouts, manage customer behavior, and progress through 9 handcrafted maps for long-term growth.', 'Simulation', 5, 'publish', '2026-04-19 09:08:57');
INSERT INTO `games` (`id`, `title`, `slug`, `iframe_url`, `image_url`, `description`, `category`, `views`, `status`, `created_at`) VALUES
(261, 'Dig out of Prison', '6b91889aa08e40ffbc1c09be1a8e81ce', 'https://html5.gamedistribution.com/6b91889aa08e40ffbc1c09be1a8e81ce/', 'assets/thumbs/6b91889aa08e40ffbc1c09be1a8e81ce.jpg', 'You are a prisoner determined to break free. Dig tunnels with a spoon, shovel, or anything you can find. Discover valuables, trade with fellow inmates and even the guards, and earn the prison’s top currency — toilet paper.\r\n\r\nUpgrade your digging and trading skills, unlock better tools, and speed up your escape. But be careful — plan your moves and avoid drawing attention, because freedom is the prize only for the most cunning.', 'Simulation', 6, 'publish', '2026-04-19 09:09:01'),
(262, 'My Garden Journey', '8d958e45c13a46c38e62805648e7d801', 'https://html5.gamedistribution.com/8d958e45c13a46c38e62805648e7d801/', 'assets/thumbs/8d958e45c13a46c38e62805648e7d801.jpg', 'Grow your dream garden, raise animals, and enjoy peaceful farm life!\r\n\r\nWelcome to My Garden Journey! ?? Start your peaceful farming adventure in My Garden Journey, the ultimate relaxing farming simulator!', 'Simulation', 7, 'publish', '2026-04-19 09:09:04'),
(263, 'Cinema Business - Idle Games', '7cc0378d15b34bcea94a051b0aab0de9', 'https://html5.gamedistribution.com/7cc0378d15b34bcea94a051b0aab0de9/', 'assets/thumbs/7cc0378d15b34bcea94a051b0aab0de9.jpg', 'Build and manage your own cinema empire! \r\nUnlock movie rooms, snack and burger corners to attract more customers.\r\nHire staff, upgrade facilities, and keep your theater running smoothly.\r\nEarn cash even while you’re offline and grow your business.\r\nBecome the ultimate cinema tycoon in this fun idle arcade game!', 'Simulation', 5, 'publish', '2026-04-19 09:09:04'),
(264, 'Burger Empire', '63dd731e83704e13b300deff8109f39a', 'https://html5.gamedistribution.com/63dd731e83704e13b300deff8109f39a/', 'assets/thumbs/63dd731e83704e13b300deff8109f39a.jpg', 'Welcome to Burger &amp; Beans Cafe, the ultimate restaurant-management game where you cook juicy burgers, brew the perfect coffee, and build the eatery of your dreams!\r\n\r\n• Serve Delicious Orders: Flip patties and pour lattes for hungry customers—fast!\r\n• Earn &amp; Upgrade: Collect coins to unlock chic new tables, comfy booths, and vibrant dining areas.\r\n• Customize Your Space: Choose décor, layout, and special menu items to keep guests coming back.', 'Simulation', 5, 'publish', '2026-04-19 09:09:05'),
(265, 'Burger Day', '2b0570c6eec14fd59e3815c3d8b0da85', 'https://html5.gamedistribution.com/2b0570c6eec14fd59e3815c3d8b0da85/', 'assets/thumbs/2b0570c6eec14fd59e3815c3d8b0da85.jpg', 'Burger Day is a fun and fast-paced arcade game that puts you in charge of a busy burger kitchen. Stack ingredients to serve up tasty orders as quickly as possible. Your speed and decision-making skills are tested as customer demands increase. Satisfy hungry customers to unlock fresh challenges and advance through exciting levels.', 'Simulation', 5, 'publish', '2026-04-19 09:09:19'),
(266, 'Grow a Garden: Online &amp; Offline', 'f500d997fe1e4b85a3bdfd0f11002942', 'https://html5.gamedistribution.com/f500d997fe1e4b85a3bdfd0f11002942/', 'assets/thumbs/f500d997fe1e4b85a3bdfd0f11002942.jpg', '&quot;Grow a Garden: Online &amp; Offline&quot; – Become the best farmer!\r\n\r\nPlant, grow, harvest, and earn millions while playing online with other players! Start with a simple plot and turn it into a huge farm with rare and magical plants. Buy seeds from the shop, which refreshes every 5 minutes. Find your plants on the market!', 'Simulation', 6, 'publish', '2026-04-19 09:09:41'),
(267, 'ASMR Girl: Livestream Mukbang', 'b96b71b611274b38a1de99b6ac82318c', 'https://html5.gamedistribution.com/b96b71b611274b38a1de99b6ac82318c/', 'assets/thumbs/b96b71b611274b38a1de99b6ac82318c.jpg', 'Step into the world of ASMR Girl: Livestream Mukbang, where you take on the role of an adorable mukbang streamer! Get ready to indulge in delicious food, satisfy your cravings, and share the experience with your viewers in a cozy, interactive livestream. The more you eat and engage, the more you earn!', 'Simulation', 4, 'publish', '2026-04-19 09:09:43'),
(268, 'Student and Teacher', 'c373cffa43d94eb4bef26b941fc46073', 'https://html5.gamedistribution.com/c373cffa43d94eb4bef26b941fc46073/', 'assets/thumbs/c373cffa43d94eb4bef26b941fc46073.jpg', 'The school is not ready for you!\r\nBroken laptops, chairs in splinters, the dining room is looted!\r\nRevenge is a dish served in the form of chaos!\r\nForget about the silent protest – only crushing anarchy!\r\nMake your classmates regret it!\r\nThe teacher is in a panic!\r\nThe head teacher is furious!\r\nThe main thing is not to get caught and avenge the setup!', 'Simulation', 6, 'publish', '2026-04-19 09:10:02'),
(269, 'Shark Chomp Chase', '6c87066d2e774bafbafbe7d00652712a', 'https://html5.gamedistribution.com/6c87066d2e774bafbafbe7d00652712a/', 'assets/thumbs/6c87066d2e774bafbafbe7d00652712a.jpg', 'Play Shark Chomp Chase free online and jump into a fast-paced browser game you can play instantly with no download and no install. This unblocked game loads fast and runs smoothly at school or home, making it perfect for quick breaks. Hunt, grow, and survive as you master each chase in a fun, skill-based challenge that feels like a light brain game. Mobile-friendly and built for desktop and mobile, it’s a free online game that’s easy to start and hard to put down.', 'Simulation', 6, 'publish', '2026-04-19 09:10:28'),
(270, 'Tap Tap Builder', '1b57d99609cc4775a30d56c036b8796d', 'https://html5.gamedistribution.com/1b57d99609cc4775a30d56c036b8796d/', 'assets/thumbs/1b57d99609cc4775a30d56c036b8796d.jpg', '&quot;Tap Tap Builder invites you to build the city of your dreams and become its mayor! But before leaning back in a comfortable boss\'s chair, you\'ll have to roll up your sleeves and do some work. Want to build a skyscraper? Tap-tap and you\'re done! Not enough money? Tap-tap and earn some! A fire broke out? Tap-tap and save your people!\r\n\r\nLet\'s start working right now, tap-tap the PLAY button!', 'Simulation', 9, 'publish', '2026-04-19 09:10:32'),
(271, 'Chinese Food Chef DuDu', '510f69e44889402d821cb969c9f32656', 'https://html5.gamedistribution.com/510f69e44889402d821cb969c9f32656/', 'assets/thumbs/510f69e44889402d821cb969c9f32656.jpg', 'Are you a fan of Chinese food? Do you want to discover the mystery of delicious Chinese cuisine? You do not want to miss this cooking game - Chinese Food Chef DuDu. Here, you have the chance to learn different recipes of traditional Chinese food, such as dumplings, rice dumplings, and zongzi. Win the heart of the little monkey with your delicious Chinese food!', 'Simulation', 5, 'publish', '2026-04-19 09:10:32'),
(272, 'Sea Lords', '3a0e41cb80d041e5bd058bc1bc7bb273', 'https://html5.gamedistribution.com/3a0e41cb80d041e5bd058bc1bc7bb273/', 'assets/thumbs/3a0e41cb80d041e5bd058bc1bc7bb273.jpg', 'Set sail for success in Sea Lords - the fun idle tycoon simulation game where you\'re the master of the seas. Start with a small fishing port and gradually build your global shipping empire! Manage ships, upgrade docks, hire captains, and automate your logistics as you conquer new routes and earn riches - even while you\'re offline! It\'s time to prove your skills as the next sea lord! Buy and upgrade ships to boost your delivery speed and cargo capacity.', 'Simulation', 5, 'publish', '2026-04-19 09:10:34'),
(273, 'Dr. Parking', '422657dda2114e0396930f72755b6092', 'https://html5.gamedistribution.com/422657dda2114e0396930f72755b6092/', 'assets/thumbs/422657dda2114e0396930f72755b6092.jpg', 'Ready to test your parking skills? Welcome to Dr. Parking - the super addictive car simulation game designed for all the boys who love a true driving challenge. In the game, you will drive various types of vehicles. Traverse the obstacle-laden parking lot and change corners and park your car precisely in the designated spot. And keep an eye out for keys. Each level is a test of your precision, patience, and driving instinct.', 'Simulation', 7, 'publish', '2026-04-19 09:10:50'),
(274, 'Uncle Hit: Punch the Dummy', 'e3c98c62b82749a7b0b5d5de77a9ef8e', 'https://html5.gamedistribution.com/e3c98c62b82749a7b0b5d5de77a9ef8e/', 'assets/thumbs/e3c98c62b82749a7b0b5d5de77a9ef8e.jpg', 'Uncle Hit: Punch the Dummy is a fast-paced action game where you take out your frustration on a relentless, annoying dummy. With quick reflexes and nonstop punches, you’ll unleash a flurry of blows in simple, satisfying bursts. Stay sharp, keep hitting, and enjoy every moment of chaotic stress relief wrapped in hilarious impact.', 'Simulation', 4, 'publish', '2026-04-19 09:10:52'),
(275, 'Italian Brainrot Bike Rush', 'c23f50871019481f99d1ce3d56571dfd', 'https://html5.gamedistribution.com/c23f50871019481f99d1ce3d56571dfd/', 'assets/thumbs/c23f50871019481f99d1ce3d56571dfd.jpg', 'Hop on for chaotic fun in Italian Brainrot Bike Rush, a meme-filled obby bike platformer. Pick from 5 absurd meme legends and ride through floating platforms, deadly traps, and wild jumps. Play 5 levels across 3 modes—Normal, Challenge, and One Life. Collect coins, unlock checkpoints, and conquer brainrot chaos. Perfect for fans of meme-based bike racing and Italian brainrot platformers!', 'Simulation', 6, 'publish', '2026-04-19 09:10:53'),
(276, 'Childcare Master Online', 'ac3e4bc439294078a71f3409721dd5ad', 'https://html5.gamedistribution.com/ac3e4bc439294078a71f3409721dd5ad/', 'assets/thumbs/ac3e4bc439294078a71f3409721dd5ad.jpg', 'Get ready to become a parenting superstar in Childcare Master Online! This wonderful casual simulation game is all about playing the role of a top parenting expert. As soon as you start the game, you\'ll find yourself in a lively daycare center with adorable kids. What\'s your mission? Give them love and care! First, you need to create a warm environment.', 'Simulation', 6, 'publish', '2026-04-19 09:11:04'),
(277, 'The Stone Miner', '88b06ccedba844769676f840cbb47a4a', 'https://html5.gamedistribution.com/88b06ccedba844769676f840cbb47a4a/', 'assets/thumbs/88b06ccedba844769676f840cbb47a4a.jpg', 'Become the ultimate mining tycoon in The Stone Miner! Drive your powerful mining machine through various fantasy terrains. Crush, collect and smash stones like never before! Steer your mine cart through rocks of different colors and materials and enjoy the exhilarating experience of stone mining. Sell collected stones for gold, and unlock new areas full of rare materials and surprises! Upgrade your vehicle to mine faster and deeper, turning your gear into a true beast!', 'Simulation', 5, 'publish', '2026-04-19 09:11:09'),
(278, 'Stick Hero Battle', '99ab97268bab44708cd9c5c204ccc8e9', 'https://html5.gamedistribution.com/99ab97268bab44708cd9c5c204ccc8e9/', 'assets/thumbs/99ab97268bab44708cd9c5c204ccc8e9.jpg', 'Stick Hero Battle is a fast-paced and explosive action fighting game that throws you straight into intense battle arenas. The game features easy-to-learn controls with deep combat mechanics. Control a fearless stick hero and fight your way through waves of enemies using powerful attacks, smart movement, and perfect timing.', 'Battle', 6, 'publish', '2026-04-19 09:11:21'),
(279, 'Summon Tribe', '5ec9e8ec63514f8482ddb37be8774851', 'https://html5.gamedistribution.com/5ec9e8ec63514f8482ddb37be8774851/', 'assets/thumbs/5ec9e8ec63514f8482ddb37be8774851.jpg', 'Summon Tribe is a simple merge-and-defense game where you combine identical units to create stronger ones to stop enemies. It’s easy, mostly for passing time, and it also supports idle play.', 'Battle', 3, 'publish', '2026-04-19 09:11:28'),
(280, 'Monster Slayers', '7493d2deadd944e7a4c268203e29903d', 'https://html5.gamedistribution.com/7493d2deadd944e7a4c268203e29903d/', 'assets/thumbs/7493d2deadd944e7a4c268203e29903d.jpg', 'Monster Slayers is a single‑player mobile roguelike RPG where you must survive endless waves of monsters all by yourself. Every run is a new chance to build the perfect hero, outplay growing hordes, and prove that one warrior can stand against an entire army.', 'Battle', 5, 'publish', '2026-04-19 09:11:31'),
(281, 'Craft of Wars', '99b5f30d028d40df825363d98fa5831f', 'https://html5.gamedistribution.com/99b5f30d028d40df825363d98fa5831f/', 'assets/thumbs/99b5f30d028d40df825363d98fa5831f.jpg', 'The war between the Reds and the Blues has never been more epic than in Craft of Wars! In this cubic game, you\'ll fight for strategic points on the map using a classic combat system similar to the one found in older versions of Minecraft. Prepare for intense sword and bow duels, TNT explosions, tactical use of potions, and the legendary golden apples that will help you survive the fiercest battles.', 'Battle', 5, 'publish', '2026-04-19 09:11:34'),
(282, 'Catch a Fish Obby', 'ac47a3b950d74509922e2c1724a4ed20', 'https://html5.gamedistribution.com/ac47a3b950d74509922e2c1724a4ed20/', 'assets/thumbs/ac47a3b950d74509922e2c1724a4ed20.jpg', 'Catch a Fish Obby is a chaotic collector raider set in a bright obby world full of Fish and Brainrot Fish characters. Build a money making base with your favorite sea creatures, sneak into rival bases to steal their fish, and protect your own tank from greedy bots and other players.', 'Battle', 5, 'publish', '2026-04-19 09:11:37'),
(283, 'Duo Family Santa', 'fc03dd1d102445f682db4f25284ac990', 'https://html5.gamedistribution.com/fc03dd1d102445f682db4f25284ac990/', 'assets/thumbs/fc03dd1d102445f682db4f25284ac990.jpg', 'Steve and Alex need to race against each other. The one who holds the Lucky Block wins the game. Hold onto the Lucky Block until the time runs out to win the game. You can earn money by collecting socks and you can also earn money by defeating your friend. You must be very careful; steal the Lucky Block from your friend and keep it until the time is up.', 'Battle', 4, 'publish', '2026-04-19 09:11:49'),
(284, 'Steal Car Duel', 'e3f4448cc0514fbaa84f157982da157d', 'https://html5.gamedistribution.com/e3f4448cc0514fbaa84f157982da157d/', 'assets/thumbs/e3f4448cc0514fbaa84f157982da157d.jpg', 'Step into a high-energy world of engines, rivalry, and fast reflexes. Steal Car Duel is a competitive action game that evolves the idea of Steal a Brainrot into a car-based experience filled with duels, rare collectibles, and endless upgrades!\r\n\r\nRace, collide, and steal your way to the top. Build your own garage, earn coins and tickets, and outsmart rivals to prove who rules the arena. Each match combines skill, timing, and strategy as you fight for dominance in Solo or 2 Player mode.', 'Battle', 5, 'publish', '2026-04-19 09:11:53'),
(285, 'Steal Brainrot Duel', '31628f3b940847189cb0cea3d943abe0', 'https://html5.gamedistribution.com/31628f3b940847189cb0cea3d943abe0/', 'assets/thumbs/31628f3b940847189cb0cea3d943abe0.jpg', 'Steal Brainrot Duel is a fast, competitive collector-raider where you hunt for the best brainrot characters, defend your base from thieves, and outsmart rivals in Solo or 2 Player mode. Start with simple picks like Noobini Pizzanini, then grind your economy to unlock rare and legendary favorites such as Tralalero Tralala, Cocofanto Elefanto, and Graipussi Medussi. Build income, raid others, protect your stash, and style your obby avatar with hats, glasses, backpacks, wings, outfits, and pets!', 'Battle', 5, 'publish', '2026-04-19 09:11:57'),
(286, 'Men Vs Gorillas', '3d7e461fb28a47cab835037f8c024fae', 'https://html5.gamedistribution.com/3d7e461fb28a47cab835037f8c024fae/', 'assets/thumbs/3d7e461fb28a47cab835037f8c024fae.jpg', 'Men vs Gorilla – The Ultimate Evolution Battle!\r\n\r\nStep into the wild showdown of Man vs Gorilla!\r\nUpgrade your human’s strength, damage, and health to survive the rising fury of the jungle’s strongest beast. ?\r\n\r\nEach level brings a tougher gorilla, smarter attacks, and intense battles but also bigger rewards!\r\nUse your earnings to level up your power, evolve your fighter, and dominate every fight!', 'Battle', 6, 'publish', '2026-04-19 09:12:00'),
(287, 'Challenge Your Friends', '4e22050914184629af6a2b27f5de5820', 'https://html5.gamedistribution.com/4e22050914184629af6a2b27f5de5820/', 'assets/thumbs/4e22050914184629af6a2b27f5de5820.jpg', 'Challenge yourself! With seven different games, you can experience thrilling moments whether you\'re playing solo or competing against your friends. Drunken Duel, Tug The Table, Stick Duel, Milk The Cow, and many more games are waiting for you! Plus, to make the competition even more fun, you can choose exciting dares to make  the matches unforgettable! For those who prefer solo play, 6 games are ready to keep you entertained! Step into this world of fun and enjoy the thrill of competition!', 'Battle', 6, 'publish', '2026-04-19 09:12:10'),
(288, 'Stickman Kombat 2D', '6d3928f393774157a7aed692f08ee011', 'https://html5.gamedistribution.com/6d3928f393774157a7aed692f08ee011/', 'assets/thumbs/6d3928f393774157a7aed692f08ee011.jpg', 'Adrenaline unleashed! Rage, speed, and chaos collide in explosive 2D battles. Feel every hit — and dive into the madness. Are you ready?', 'Battle', 4, 'publish', '2026-04-19 09:12:15'),
(289, 'Match Fighter', '56b5cb9b86014d5f8bf726ca5c4ff06e', 'https://html5.gamedistribution.com/56b5cb9b86014d5f8bf726ca5c4ff06e/', 'assets/thumbs/56b5cb9b86014d5f8bf726ca5c4ff06e.jpg', 'Match Fighter is a vibrant match-3 fighting game where classic martial arts meet puzzle action! Play as a skilled warrior and take on a series of powerful opponents. Match tiles to strike and unleash special moves in intense one-on-one duels. Every combo you make fuels your fighting spirit. Outsmart your enemies, climb the ranks, and prove yourself as the ultimate martial arts champion!\r\n\r\nCan you match your way to victory?', 'Battle', 5, 'publish', '2026-04-19 09:12:30'),
(290, 'Wheel in the face', '424a1c4970c045b7b07e238e76804ca8', 'https://html5.gamedistribution.com/424a1c4970c045b7b07e238e76804ca8/', 'assets/thumbs/424a1c4970c045b7b07e238e76804ca8.jpg', 'Jump behind the wheel of a furious combat vehicle and rush into battle! Lightning-fast battles await you in closed arenas: ram enemies, dodge traps, use deadly weapons and win deadly fights.\r\n\r\nChoose your style: cut your opponents with a sword, shoot them with a shotgun or burn them to the ground with a flamethrower!\r\n\r\nUpgrade cars, weapons and wheels, earn money and raise your rank.', 'Battle', 5, 'publish', '2026-04-19 09:12:33'),
(291, 'SquidGame.io', '8256a6e4d51c45c6abe055782066efed', 'https://html5.gamedistribution.com/8256a6e4d51c45c6abe055782066efed/', 'assets/thumbs/8256a6e4d51c45c6abe055782066efed.jpg', 'Engage in free multiplayer survival! Compete in 7-minute minigames against 30 rivals. Based on the hit Netflix show, test your skills and strategy. Fail a challenge, get eliminated by Pink Soldiers! Adapt and outmaneuver to survive. Will you be the last one standing?', 'Battle', 4, 'publish', '2026-04-19 09:12:34'),
(292, 'Draw Weapon Fight Party', '7409155d0a5d42408f913f58f566b8af', 'https://html5.gamedistribution.com/7409155d0a5d42408f913f58f566b8af/', 'assets/thumbs/7409155d0a5d42408f913f58f566b8af.jpg', 'In Draw Weapon - Fight Party, you can draw your own weapons. Feel free to write your weapon, but keep an eye on the amount of ink left. Your creativity determines your combat style. Enter the 3D battle arena and fight against other opponents in an action-packed showdown. Draw precisely, craft the ultimate weapon, and crush your opponents to become the ultimate warrior.', 'Battle', 4, 'publish', '2026-04-19 09:12:44'),
(293, 'Sprunki Space Challenge', '3d70efa767214c7a8006ca79261a1c1c', 'https://html5.gamedistribution.com/3d70efa767214c7a8006ca79261a1c1c/', 'assets/thumbs/3d70efa767214c7a8006ca79261a1c1c.jpg', 'Get ready to soar through the stars in Sprunki Space Challenge an intergalactic online adventure where brave kids take flight to save the galaxy. This wild space ride throws you into the cockpit of a zippy space rover where danger lurks in every asteroid and rocket burst. But worry not: Sprunki is here to lead the charge. It is all about timing, reflexes, and sky-high jumps that send you sailing straight into the action.', 'Battle', 8, 'publish', '2026-04-19 09:12:45'),
(294, 'Brawler Man: Fist of Fury', 'c307f8e811cf4af4b023c1eb894c5e83', 'https://html5.gamedistribution.com/c307f8e811cf4af4b023c1eb894c5e83/', 'assets/thumbs/c307f8e811cf4af4b023c1eb894c5e83.jpg', 'Hooligans have taken over the city streets. Join the battle for order in the city!\r\n\r\nYou are a street fighter and want to protect your city from the invasion of hooligans! You will have to visit every corner of the city. Clear the streets of criminals and hooligans with the help of your fighting skills! Deliver cool blows, combine blows to get crazy techniques! In this battle, every blow is important, train to fight back against hooligans and their Bosses.', 'Battle', 5, 'publish', '2026-04-19 09:12:47'),
(295, 'Helicopter Battle Steve 2 Player', 'db903c04abc24de3b61cc1983dea4486', 'https://html5.gamedistribution.com/db903c04abc24de3b61cc1983dea4486/', 'assets/thumbs/db903c04abc24de3b61cc1983dea4486.jpg', 'Get on the helicopter and choose either the blue or red player. Destroy your friend’s helicopter to win the game.Winning is simple: just don’t let your helicopter crash! Jump and shoot to defeat your opponent. To beat the red or blue player, you must play your best. The player whose helicopter explodes the most will lose the game.', 'Battle', 8, 'publish', '2026-04-19 09:12:49'),
(296, 'Battler', 'a921c3e70c884464a0c6fc7e3d6f97b6', 'https://html5.gamedistribution.com/a921c3e70c884464a0c6fc7e3d6f97b6/', 'assets/thumbs/a921c3e70c884464a0c6fc7e3d6f97b6.jpg', 'Immerse yourself in the world of tactical card battles, where your victory depends on the right choice and combinations of skills! You are fighting against decks of treacherous enemies. Choose one of three unique characters and immerse yourself in exciting battles. Use the character editor to fine-tune your character, adding unique abilities.', 'Battle', 6, 'publish', '2026-04-19 09:12:51'),
(297, 'Army Fight 3d', 'c360b3d8953441208dfe90b3e6976c09', 'https://html5.gamedistribution.com/c360b3d8953441208dfe90b3e6976c09/', 'assets/thumbs/c360b3d8953441208dfe90b3e6976c09.jpg', 'Begin the nervous army battles in Army Fight 3D. Here you need strategic thinking and quick reflexes.In this fun action battle game, you aim to build a powerful army. Defend your base, and defeat the enemy. Start by creating and upgrading your army.', 'Battle', 6, 'publish', '2026-04-19 09:13:06'),
(298, 'Zombie Redemption', '60fe1469f0cd4b4a8de22879939d5db7', 'https://html5.gamedistribution.com/60fe1469f0cd4b4a8de22879939d5db7/', 'assets/thumbs/60fe1469f0cd4b4a8de22879939d5db7.jpg', 'Zombie Redemption is an action-survival game set in a world where a failed experiment has turned most of humanity into zombies. Players earn gold by defeating zombies, which can be used to unlock stronger weapons. However, zombies also attack, making quick reflexes and strategic thinking essential for survival. Combining elements of strategy, action, and survival, this game offers an unforgettable adventure in the fight to save the world.', 'Battle', 4, 'publish', '2026-04-19 09:13:21'),
(299, 'Paint Rush', '388f01ff1f7242718e9d232681e32b3d', 'https://html5.gamedistribution.com/388f01ff1f7242718e9d232681e32b3d/', 'assets/thumbs/388f01ff1f7242718e9d232681e32b3d.jpg', 'White houses are boring. Bring the colors in and paint everything in seconds. Complete every level painting all white spaces. Swipe left, right, up and down and fill all the empty spots on Paint Rush', 'Art', 4, 'publish', '2026-04-19 09:13:36'),
(300, 'Chicken Banana Quest', 'ba23931cd64944a6ba5dc162f70c1684', 'https://html5.gamedistribution.com/ba23931cd64944a6ba5dc162f70c1684/', 'assets/thumbs/ba23931cd64944a6ba5dc162f70c1684.jpg', 'Help the Chicken and Banana to solve all puzzle quest and find the play button. Use your skills to solve the puzzles before the lives run out and complete all levels with the less possible clicks', 'Art', 4, 'publish', '2026-04-19 09:13:41'),
(301, 'Cheerful Plumber', 'f2bec0af787d426ca63dc7ee3faf877f', 'https://html5.gamedistribution.com/f2bec0af787d426ca63dc7ee3faf877f/', 'assets/thumbs/f2bec0af787d426ca63dc7ee3faf877f.jpg', 'Greetings, young artist. Do you like video games and creativity? Then this game is for you! Color video game characters: a princess, a cheerful plumber, a dragon and others! Choose different colors on the main and secondary palette. Play and color! Take a screenshot and share the result with your friends!', 'Art', 3, 'publish', '2026-04-19 09:13:42'),
(302, 'Diamond mosaic', 'fa525c7020fb4e848fb3b18a850fb773', 'https://html5.gamedistribution.com/fa525c7020fb4e848fb3b18a850fb773/', 'assets/thumbs/fa525c7020fb4e848fb3b18a850fb773.jpg', 'Ready to create your own masterpiece from a scattering of diamonds on your screen? Come to our mosaic!  Fill images with diamond scatter!', 'Art', 4, 'publish', '2026-04-19 09:13:56'),
(303, 'Tung Sahur Coloring', 'e65cb0c069e341c5a6827825f65784b9', 'https://html5.gamedistribution.com/e65cb0c069e341c5a6827825f65784b9/', 'assets/thumbs/e65cb0c069e341c5a6827825f65784b9.jpg', 'Tung Sahur Coloring is a colorful joyride just waiting to happen! This super fun coloring game for kids turns every blank page into a chance to sparkle with creativity. Grab your virtual crayons and get ready to dive into the world of Tung Sahur, where imagination runs wild and colors know no rules. From cheerful characters to wacky shapes, each page is your personal canvas. Fill it with the wildest colors you can think of—green suns, purple trees, rainbow hats—anything goes here!', 'Art', 3, 'publish', '2026-04-19 09:13:57'),
(304, 'Your dream room', 'e9e797905bd34f719fa592901bd4284e', 'https://html5.gamedistribution.com/e9e797905bd34f719fa592901bd4284e/', 'assets/thumbs/e9e797905bd34f719fa592901bd4284e.jpg', 'Do you dream of creating the perfect room? \r\nIn this game you will become a real interior designer! \r\nHave fun, experiment and turn an empty space into a cozy dream corner.\r\nChoose wallpaper, flooring and furniture in different styles. Decorate the room with stylish accessories, add coziness!\r\nChoose the color scheme and arrange items as you like.\r\nExperiment with design, create unique interiors and enjoy the process!\r\nStart creating your dream room now!', 'Art', 4, 'publish', '2026-04-19 09:13:57'),
(305, 'Tap Car', '6e167cdefdf244bc97955ca7ecec4edf', 'https://html5.gamedistribution.com/6e167cdefdf244bc97955ca7ecec4edf/', 'assets/thumbs/6e167cdefdf244bc97955ca7ecec4edf.jpg', 'Unveil stunning car masterpieces by solving image puzzles. Every tap reveals more of the picture—can you uncover them all? A must-play for car enthusiasts and puzzle lovers alike!\r\n\r\nWould you like a few more variations depending on the tone you\'re aiming for (like more casual, exciting, or elegant)?', 'Art', 5, 'publish', '2026-04-19 09:13:59'),
(306, 'sprunki character maker OC', 'a78fb8feefd848489aa683bd6253ec5b', 'https://html5.gamedistribution.com/a78fb8feefd848489aa683bd6253ec5b/', 'assets/thumbs/a78fb8feefd848489aa683bd6253ec5b.jpg', 'The Sprunki Character Maker OC is an interactive tool that allows users to create their own unique characters within the Sprunki universe. Featuring a wide range of customization options, assets, and design tools, it empowers players to craft characters that match the game’s distinctive art style and themes. This experience encourages creativity, self-expression, and deeper engagement with the Sprunki community', 'Art', 3, 'publish', '2026-04-19 09:14:05'),
(307, 'Nutcracker New Years Adventures', 'f42a105055a846978d6446710ea9e3b6', 'https://html5.gamedistribution.com/f42a105055a846978d6446710ea9e3b6/', 'assets/thumbs/f42a105055a846978d6446710ea9e3b6.jpg', 'Welcome to the world of a fairy tale, where two princesses are preparing for a series of winter holidays. Each of the princesses is working on creating her own unique New Year\'s outfit, inspired by Hoffmann\'s mystical fairy tales and Tchaikovsky\'s classical ballet. Immersing themselves in the atmosphere of New Year\'s magic, players will be able not only to dress princesses, but also to develop their sense of style. Get ready for an unforgettable adventure and create your own New Year\'s image!', 'Art', 3, 'publish', '2026-04-19 09:14:20'),
(308, 'Girls Fun Nail Salon', '5c224155cef441709556af0f2033faa0', 'https://html5.gamedistribution.com/5c224155cef441709556af0f2033faa0/', 'assets/thumbs/5c224155cef441709556af0f2033faa0.jpg', 'Girls Fun Nail Salon is a fun Makeover game. This game is designed for girls who love fashionable nail art. This game not only has vivid sound effects and images but also smooth animations. Its\r\ngameplay is also very simple. You need to design nail art suitable for different customers, and they will give you scores, just like real customers. In the game, you can not only experience the fun of cutting and polishing nails but also the fun of designing fashionable nail art. Come and try it.', 'Art', 5, 'publish', '2026-04-19 09:14:38'),
(309, 'Ocean Kids Back To School', '0a4b7dfd0f75461f84e79b9878b25302', 'https://html5.gamedistribution.com/0a4b7dfd0f75461f84e79b9878b25302/', 'assets/thumbs/0a4b7dfd0f75461f84e79b9878b25302.jpg', 'Welcome to Ocean Kids Back to school. It’s back to school time for these Kids. Can you help them get ready for their first day of classes? They’ll need to pick some cool outfits, new hairstyles, accessories, and school supplies too in this online dress-up and design game for girls. After you’re all done, help them to repair their vespa. Play and have fun!', 'Art', 2, 'publish', '2026-04-19 09:14:39'),
(310, 'FaceChart', 'ef9188a4df8f4981b79e19d17d96c963', 'https://html5.gamedistribution.com/ef9188a4df8f4981b79e19d17d96c963/', 'assets/thumbs/ef9188a4df8f4981b79e19d17d96c963.jpg', 'Do you dream of creating wild, fabulous looks like your favorite artists on social media? Dive into the enchanting realm of Face Chart! Wondering what a face chart is? It\'s your chic canvas to plan the next jaw-dropping, glamorous look. Grab a piece of paper and let it be your pocket-sized playground—experiment with new colors you hesitated to wear, pick and mix diverse designs for an endless array of possibilities.', 'Art', 3, 'publish', '2026-04-19 09:14:40'),
(311, 'Girl Coloring Dress Up Games', '09a624e26307450dbae6322916ac4b21', 'https://html5.gamedistribution.com/09a624e26307450dbae6322916ac4b21/', 'assets/thumbs/09a624e26307450dbae6322916ac4b21.jpg', 'Brand new girl games are already waiting for you! Start creating your own coloring pages by dressing up dolls and painting pictures for backgrounds. You’ll get hundreds of color options, textures and patterns, glitter and gradients. Create your coloring book from scratch, color dresses, and improve your clothes designer skills. If you like drawing that’s the free coloring apps you’ve been looking for!\r\n\r\n?️Creative Coloring Games for Girls?\r\n\r\n✪ Play as a doll designer: select hair, dress up, and pick accessories\r\n✪ Design clothes: use gradients, textures, and patterns\r\n✪ Combine stylish looks and haircuts like in famous girl games\r\n✪ Color without numbers and paint with glitter\r\n✪ Create coloring pages: move and change dolls and backgrounds\r\n✪ Zoom in and out for better results\r\n✪ Makeover dolls and backgrounds\r\n✪ Paint wallpaper for your phone in fun color games \r\n✪ Take pictures right in the game and share them with friends easily\r\n✪ Free coloring book offline with many options', 'Art', 5, 'publish', '2026-04-19 09:14:42'),
(312, 'College Girl Coloring Dress Up', '5ef3a8696884434c8b833fad0ec60911', 'https://html5.gamedistribution.com/5ef3a8696884434c8b833fad0ec60911/', 'assets/thumbs/5ef3a8696884434c8b833fad0ec60911.jpg', 'BFF high school fashion makeover: coloring book &amp; cool dress up games for girls!\r\nNew college girls dress up game &amp; coloring book is here for you! Dress up the most popular high school girls, create their whole look, paint and color. These cool coloring pages and clothes design features made especially for fashion girls. Begin total fashion makeover with our girl dress up games!\r\n\r\nDesign outfits like a fashionista: dress up, choose hairstyle, necklaces and other amazing accessories such as skirts and dresses. Select a color and click on the fragment you want to color, when the painting of college girl is created, start drawing and coloring, become BFF fashion clothes designer.\r\n\r\nTake screenshots, save as wallpaper, and share cute coloring pages with your friends and family absolutely for free.', 'Art', 4, 'publish', '2026-04-19 09:14:45'),
(313, 'Draw Bridge Challenge', 'c0d7138391e14de091894c3e19b2c30b', 'https://html5.gamedistribution.com/c0d7138391e14de091894c3e19b2c30b/', 'assets/thumbs/c0d7138391e14de091894c3e19b2c30b.jpg', 'Drag to create a path and guide the car to the goal! You can only draw the line once, be careful not to break the car! To become a good bridge builder, you just need to drag with one finger to draw a bridge that is stable enough for the car to reach flags. You can draw a bridge on only one line, so make sure safety comes first.', 'Art', 4, 'publish', '2026-04-19 09:14:50'),
(314, 'Smash DIY Slime - Fidget Slimy', '08ebcd93ad554559806a39355d90039e', 'https://html5.gamedistribution.com/08ebcd93ad554559806a39355d90039e/', 'assets/thumbs/08ebcd93ad554559806a39355d90039e.jpg', 'A relaxing and sticky game where you can create your own Slimes, smash and pull them right on the screen, collect collections of Popits and tap on them, besides, a lot of mini-games from puzzles to runners are waiting for you!', 'Art', 5, 'publish', '2026-04-19 09:15:02'),
(315, 'DOP2 Erase part in Love Story', '0cd5bc375f984e71b1401331f96024c9', 'https://html5.gamedistribution.com/0cd5bc375f984e71b1401331f96024c9/', 'assets/thumbs/0cd5bc375f984e71b1401331f96024c9.jpg', 'Who is hiding in the closet or in the bathroom? \r\nErase the detail and find out all the secrets of a love couple! Each level is a new story where you need to erase the extra detail to solve the puzzle and help the lovers. Can you complete all the tasks? Help the couple save their love! The game is full of humor and unexpected twists that will make you smile and laugh!', 'Art', 3, 'publish', '2026-04-19 09:15:13'),
(316, 'Dress Up Games &amp; Coloring Book', '4b3f788121b04770983affe98c53b3e7', 'https://html5.gamedistribution.com/4b3f788121b04770983affe98c53b3e7/', 'assets/thumbs/4b3f788121b04770983affe98c53b3e7.jpg', 'Coloring games for girls: start dressing up &amp; create your own coloring pages\r\nCool combo of dressing and coloring games offline! Dress up dolls, pick backgrounds and your coloring pages are ready. Use glitter, gradient, and different patterns to color pictures, change any detail and create beautiful wallpapers in this fashion girl coloring book. New creative painting games you’ve been looking for! ???\r\n\r\nBecome a new doll designer. Create your own doll, dress up and makeup, choose hairstyles and accessories, then select the background. When the coloring page is created, start painting. Learn to combine colors and patterns, make your picture shine with glitter and gradient. It’s not that easy, but you can get a real masterpiece in the end. These girly games help you relax and teach you to be creative. Super interesting for those who love painting and drawing!\r\n\r\nDress up Games for Girls + Glitter Color Book', 'Art', 4, 'publish', '2026-04-19 09:15:14'),
(317, 'Color Page ASMR', '587fde03cc194e068fb51437cff221e1', 'https://html5.gamedistribution.com/587fde03cc194e068fb51437cff221e1/', 'assets/thumbs/587fde03cc194e068fb51437cff221e1.jpg', 'Color Page ASMR is a very casual painting game, suitable for all ages to spend time. Pick up a brush, follow the tutorial in the game to paint and paint the corresponding color. Interested in showing off your skills?', 'Art', 4, 'publish', '2026-04-19 09:15:17'),
(318, 'Hatching Nursery Kids Virtual Pet Game', '07aa3a6c02374035a3e31b91c3d156d6', 'https://html5.gamedistribution.com/07aa3a6c02374035a3e31b91c3d156d6/', 'assets/thumbs/07aa3a6c02374035a3e31b91c3d156d6.jpg', 'Are you curious what is inside that big weird egg?! Then hatch it and find out! These eggs are full of cute and amazing baby creatures that you have to feed and help them grow. How you can get the food for them?! It’s simple, you just have to play games and get foods as the reward! Let’s see how many of these cute animals you can help to fully grow!', 'Art', 4, 'publish', '2026-04-19 09:15:27'),
(319, 'Draw and Save The Car', '1a7374c124f140709a7b1131e340bc65', 'https://html5.gamedistribution.com/1a7374c124f140709a7b1131e340bc65/', 'assets/thumbs/1a7374c124f140709a7b1131e340bc65.jpg', 'Use your imagination and draw a bridge to help the car trying to reach its destination. As the levels progress, different dangers and obstacles will come your way. That\'s why you have to make more strategic drawings. You can unlock new and more powerful cars with the coins you earn after the missions. A long adventure begins with a total of 200 different levels.', 'Art', 4, 'publish', '2026-04-19 09:15:30'),
(320, 'Draw and Save Stickman', 'edf291a5aa964081a3d20ed12bb0e005', 'https://html5.gamedistribution.com/edf291a5aa964081a3d20ed12bb0e005/', 'assets/thumbs/edf291a5aa964081a3d20ed12bb0e005.jpg', 'Want to test your IQ, creativity or drawing skills? Looking for a new, unique puzzle game? Draw and Save Stickman is the game you need! Make drawings to keep various dangers and traps away from Stickman. You will need to think differently in each level. Let\'s guess where the danger will come from and start drawing the shield!', 'Art', 5, 'publish', '2026-04-19 09:15:39'),
(321, 'Super Pinball', '3f17d3ae6ff14b3e9cdd4ecc31a10d89', 'https://html5.gamedistribution.com/3f17d3ae6ff14b3e9cdd4ecc31a10d89/', 'assets/thumbs/3f17d3ae6ff14b3e9cdd4ecc31a10d89.jpg', 'This is a fun and relaxing game. Here you will launch it against a black background\r\n\r\nA small ball with different shapes can be smashed to obtain higher scores. However, you should pay attention not to let the bricks pass your final bottom line, otherwise the game will fail and start again! At the same time, you can also get all kinds of strange props in the game. Some props can even help you increase the number of balls, so that you can more easily get scores, and finally get higher scores. In addition, physical billiards have very high requirements on the geometric mathematics of players, because you need to calculate the rebound behavior of the ball after the collision point, and then calculate the maximum number of collisions, so that more bricks can be broken!', 'Art', 5, 'publish', '2026-04-19 09:15:41'),
(322, 'Protect My Dog', '49051d436ca64098aedb317a6a7b3ebe', 'https://html5.gamedistribution.com/49051d436ca64098aedb317a6a7b3ebe/', 'assets/thumbs/49051d436ca64098aedb317a6a7b3ebe.jpg', 'Protect My Dog is a fun casual puzzle game. The aim of the game is to protect our cute dog from bee attacks. For this, you must create a defensive drawing line at the levels. You should also protect your dog from lava, thorns and different environmental hazards. Fighting the Bees will continue for 50 Levels and things will get a little more difficult with each level.', 'Art', 3, 'publish', '2026-04-19 09:15:43'),
(323, 'Hair Shuffle', '9a590ce6d07f46ebafa10e4ff927c701', 'https://html5.gamedistribution.com/9a590ce6d07f46ebafa10e4ff927c701/', 'assets/thumbs/9a590ce6d07f46ebafa10e4ff927c701.jpg', 'Hair Shuffle is wonderful platform game which you shuffle twins\' hair and trying to avoid obstacles to reach to the end. At the end, you need to make twins\' hair similar to requested above.', 'Art', 3, 'publish', '2026-04-19 09:15:46'),
(324, 'Mosaic Artimo', 'bc7d51fbb767485f9808d319b3077901', 'https://html5.gamedistribution.com/bc7d51fbb767485f9808d319b3077901/', 'assets/thumbs/bc7d51fbb767485f9808d319b3077901.jpg', 'This adventure will keep your interest to solve each puzzle! Beautiful art, interested puzzles and game hero will provide you unforgettable pleasure. Try it now!', 'Art', 3, 'publish', '2026-04-19 09:15:56'),
(325, 'Home Design Miss Robins home Makeover', '01931dc824f845a58e107a42bad3ca00', 'https://html5.gamedistribution.com/01931dc824f845a58e107a42bad3ca00/', 'assets/thumbs/01931dc824f845a58e107a42bad3ca00.jpg', 'Design beautiful homes in bright and sunny places and solve hundreds of fun match 3 puzzles in a light and fun match 3 home makeover game.\r\n\r\nMeet Miss Robins, a young bright designer, and help design the decor and furniture to renovate beautiful houses.\r\n\r\n- Hone your design skills by designing the home decor and furniture.\r\n- Match candy and create power-ups\r\n- Lot\'s of match-3 levels to enjoy\r\n- Light and Fun Gameplay', 'Art', 4, 'publish', '2026-04-19 09:15:57'),
(326, 'Drawmaster', '26a8ee30c6514d58aac378091ddcc526', 'https://html5.gamedistribution.com/26a8ee30c6514d58aac378091ddcc526/', 'assets/thumbs/26a8ee30c6514d58aac378091ddcc526.jpg', 'Draw master is puzzle game in which you have to draw path for weapon and kill the enemy. Make sure you hit the enemy right. With more than 20+ unique weapons and 30+ different levels can you complete all levels?.The game is fun and the graphics are visually rich. Enrich your idea and creativity and complete the game.', 'Art', 5, 'publish', '2026-04-19 09:16:05'),
(327, 'Santa Claus Coloring Book', '04824fd414f343979bd0bee415453eac', 'https://html5.gamedistribution.com/04824fd414f343979bd0bee415453eac/', 'assets/thumbs/04824fd414f343979bd0bee415453eac.jpg', 'This is a Santa Claus Coloring Book, where he exercise her imagination and motor skills while having fun meeting different Santa Claus characters. In this game you will find 18 different pictures which have to be colored. You have 15 different colors to choose. You can also save the colored image. Have fun!', 'Art', 5, 'publish', '2026-04-19 09:16:05'),
(328, 'Jewels Blitz Legends', '36cb9c95a60244d4899f6d79210e7f4d', 'https://html5.gamedistribution.com/36cb9c95a60244d4899f6d79210e7f4d/', 'assets/thumbs/36cb9c95a60244d4899f6d79210e7f4d.jpg', 'Embark on a dazzling adventure in Jewels Blitz Legends, the epic sequel to the beloved Match 3 hit! Travel through ancient Inca temples, uncover mystical secrets, and match colorful gems to unlock treasures. Explore Machu Picchu, complete hundreds of challenging levels, and take on exciting daily missions and weekly events. Collect gold, magical artifacts, and experience stunning visuals in this addictive journey through the heart of ancient legend!', 'Match-3', 3, 'publish', '2026-04-19 09:17:35'),
(329, 'VegaMix Da Vinci Puzzles', '1a249236f03f474db586aeba1abafae0', 'https://html5.gamedistribution.com/1a249236f03f474db586aeba1abafae0/', 'assets/thumbs/1a249236f03f474db586aeba1abafae0.jpg', '&quot;VegaMix Da Vinci Puzzles&quot; is a match-3 adventure with quests and an interactive story. After a time-machine failure, Alice, Vika, and Lesha end up in Renaissance Italy and meet Leonardo da Vinci. To return home, they must help him finish his inventions, recover lost blueprints, and uncover secrets hidden in his workshop while exploring the art-filled cities and palaces of 15th-century Italy.', 'Match-3', 6, 'publish', '2026-04-19 09:17:38'),
(330, 'Popping Candies', '9e025535bdda42b584e24aa0a503e7d3', 'https://html5.gamedistribution.com/9e025535bdda42b584e24aa0a503e7d3/', 'assets/thumbs/9e025535bdda42b584e24aa0a503e7d3.jpg', 'Match and crush candies to achieve goals in this addictive puzzle game! Swap adjacent candies to form rows of three or more and clear the board. Create special candies like striped, wrapped, or color bombs to enhance your progress. Overcome obstacles like chocolate and blockers while completing each level\'s unique objectives. Be mindful of your limited moves! Use boosters for extra assistance and advance through challenging levels to unlock new stages.', 'Match-3', 5, 'publish', '2026-04-19 09:17:45'),
(331, 'Magic Christmas Tree Match-3', 'cd71a6d56b514239b279f07f7cb7694f', 'https://html5.gamedistribution.com/cd71a6d56b514239b279f07f7cb7694f/', 'assets/thumbs/cd71a6d56b514239b279f07f7cb7694f.jpg', 'Magic Christmas Tree Match-3 is a free New Year\'s match-3 game where you\'ll complete vibrant levels, create combinations of three or more, earn bonuses, and help the heroes decorate the festive town. Solve match-3 puzzles, combine elements, use power-ups, explosions, and super combos to complete tasks faster and advance the story.', 'Match-3', 6, 'publish', '2026-04-19 09:17:47'),
(332, 'Puppy Treat Sorting', 'f79ec8ef8c0c4f13955eb0dc9017dc65', 'https://html5.gamedistribution.com/f79ec8ef8c0c4f13955eb0dc9017dc65/', 'assets/thumbs/f79ec8ef8c0c4f13955eb0dc9017dc65.jpg', 'Puppy Treat Sorting is a Sorting game where you must grab and sort identical bones to create a new and bigger one. Puppies will fall automatically into the arena; what you must do is drag the puppies around and choose them into identical ones.', 'Match-3', 6, 'publish', '2026-04-19 09:17:49'),
(333, 'Athena Match 2', '4d700fb4689d48e2ad0f5072300cdb11', 'https://html5.gamedistribution.com/4d700fb4689d48e2ad0f5072300cdb11/', 'assets/thumbs/4d700fb4689d48e2ad0f5072300cdb11.jpg', 'Athena Match 2 - the epic sequel returns! Join the goddess Athena on a new mythical journey through ancient Greece. Match 3 or more legendary artifacts to restore temples and unlock the secrets of the gods. Enjoy stunning visuals, immersive sound, and hundreds of new levels packed with daily missions and challenges. Step into the world of Greek mythology and prove your match-3 skills in this divine adventure!', 'Match-3', 6, 'publish', '2026-04-19 09:17:52'),
(334, 'VegaMix Match-3 Village', '8c1bfbc5d6814c8aa3061061e050b8b4', 'https://html5.gamedistribution.com/8c1bfbc5d6814c8aa3061061e050b8b4/', 'assets/thumbs/8c1bfbc5d6814c8aa3061061e050b8b4.jpg', 'A cozy match-3 with a heartfelt story! ? Visit grandma in the village — she’s a true star with fun tales from her youth. Play classic match-3 levels, earn stars and complete quests for villagers. Bright puzzles, touching stories, colorful graphics and daily bonuses await you. Perfect for short sessions and relaxing breaks. ? For fans of match-3 with plot, coziness and helping heroes.', 'Match-3', 5, 'publish', '2026-04-19 09:18:03'),
(335, 'Fruit Jam - Merge Puzzle Game', '13b79da649a6446bbbb25c483925ffe7', 'https://html5.gamedistribution.com/13b79da649a6446bbbb25c483925ffe7/', 'assets/thumbs/13b79da649a6446bbbb25c483925ffe7.jpg', 'Fruit Jam - Merge Puzzle Game\r\nSwipe fruits, blast combos &amp; solve hundreds of juicy match-3 puzzles! Fun for all ages with vibrant graphics, daily rewards, offline play &amp; no time limits. ?? Perfect for quick play or long sessions. Match, crush &amp; enjoy!\r\n\r\nPlay now and test your brain!', 'Match-3', 5, 'publish', '2026-04-19 09:18:05'),
(336, 'Labubu and Treasures: Fun Adventure', 'c44d8e4a1bff47078b37e07867553f8c', 'https://html5.gamedistribution.com/c44d8e4a1bff47078b37e07867553f8c/', 'assets/thumbs/c44d8e4a1bff47078b37e07867553f8c.jpg', 'Collect bright combinations, pass hundreds of levels together with amazing characters from the Labubu universe! In this exciting Match-3 puzzle you will find bright adventures, interesting puzzles and fluffy magic.', 'Match-3', 10, 'publish', '2026-04-19 09:18:26'),
(337, 'Tile Adventure', '070c685168914e579a3e604bad0307a1', 'https://html5.gamedistribution.com/070c685168914e579a3e604bad0307a1/', 'assets/thumbs/070c685168914e579a3e604bad0307a1.jpg', 'A fun and satisfying tile-matching puzzle game! Match tiles in sets of three, clear the board, and enjoy a relaxing, brain-teasing experience. With smooth gameplay, colorful visuals, and levels that gradually increase in challenge, it’s perfect for anyone who loves casual puzzles. (Inspired by the classic Mahjong layout, but with a fresh, modern twist!)', 'Match-3', 7, 'publish', '2026-04-19 09:18:27'),
(338, 'Grill It All', '8ee478f78c3f4973999ba63ea328248b', 'https://html5.gamedistribution.com/8ee478f78c3f4973999ba63ea328248b/', 'assets/thumbs/8ee478f78c3f4973999ba63ea328248b.jpg', 'Grill it all is a cooking-themed match-3 puzzle game. Play as a grill expert, matching identical skewers to complete orders. Strategically arrange ingredients like fish, leeks, and meatballs on grills. Test your observation and speed while using upgrade tools for strategic depth!', 'Match-3', 4, 'publish', '2026-04-19 09:18:28'),
(339, 'Kingdom match', '2a19100d0eae469e8e61d8ee7697cb6c', 'https://html5.gamedistribution.com/2a19100d0eae469e8e61d8ee7697cb6c/', 'assets/thumbs/2a19100d0eae469e8e61d8ee7697cb6c.jpg', 'Kingdom match is a competitive match-3 game with castle decoration options! Complete levels, compete with other players and build the best castle!', 'Match-3', 4, 'publish', '2026-04-19 09:18:30'),
(340, 'Royal Garden Match', 'b511303e158f4d15b58484a5558dd173', 'https://html5.gamedistribution.com/b511303e158f4d15b58484a5558dd173/', 'assets/thumbs/b511303e158f4d15b58484a5558dd173.jpg', 'Welcome to Royal Garden Match! You’ve inherited a grand Royal Castle and a once-beautiful garden—now it’s up to you to bring its beauty to life! Solve exciting match-3 puzzles by combining exquisite royal flowers, fruits, and plants to unlock powerful boosters. With hundreds of challenging levels, unique royal characters, and a magical journey ahead, there\'s always something new to discover. Can you make the royal garden flourish? Play now and start your enchanting adventure!', 'Match-3', 5, 'publish', '2026-04-19 09:18:41');
INSERT INTO `games` (`id`, `title`, `slug`, `iframe_url`, `image_url`, `description`, `category`, `views`, `status`, `created_at`) VALUES
(341, 'Jewel Dress Up', 'db4c9e081b1b4bff80d62bfc4004c496', 'https://html5.gamedistribution.com/db4c9e081b1b4bff80d62bfc4004c496/', 'assets/thumbs/db4c9e081b1b4bff80d62bfc4004c496.jpg', 'Each puzzle brings you closer to unlocking fabulous fashionable combinations. Use power-ups to overcome challenges and to express your style, all while enjoying a relaxing and engaging gameplay. Can you create the perfect look?', 'Match-3', 6, 'publish', '2026-04-19 09:18:43'),
(342, 'Merge Fusion', '8c128dee9cdc4ac0bad3ebdde8602d4a', 'https://html5.gamedistribution.com/8c128dee9cdc4ac0bad3ebdde8602d4a/', 'assets/thumbs/8c128dee9cdc4ac0bad3ebdde8602d4a.jpg', 'Merge Fusion is an entertaining and addictive casual game where you combine and evolve items to create superior versions. The goal is to drag and merge identical items, triggering new fusions and unlocking more challenging levels as you progress. The game features simple, relaxing gameplay that is perfect for unwinding. Experience the satisfaction of watching your creations grow progressively in complexity as you explore new possibilities with each merge.', 'Match-3', 9, 'publish', '2026-04-19 09:18:50'),
(343, 'Tiles Matching', '7e02319e692c47b0b0eb47ba3f153f37', 'https://html5.gamedistribution.com/7e02319e692c47b0b0eb47ba3f153f37/', 'assets/thumbs/7e02319e692c47b0b0eb47ba3f153f37.jpg', 'Free online game Tiles Matching - play in the browser without downloading. It is suitable for the development of logic for both adults and children - an ideal timekiller.\r\nTiles Matching is a puzzle game combining the game mechanics of Mahjong and Three in a Row (Match-3). A logical educational game for children and adults. With each level, the difficulty increases - not everyone can complete the game the first time. Challenge your intelligence.', 'Match-3', 5, 'publish', '2026-04-19 09:18:56'),
(344, 'Shelf Sweep', '1877552b08c9460fbf9a7257c1cd484c', 'https://html5.gamedistribution.com/1877552b08c9460fbf9a7257c1cd484c/', 'assets/thumbs/1877552b08c9460fbf9a7257c1cd484c.jpg', 'Get ready to tidy up the shelves in Shelf Sweep!\r\nDive into a fun and addictive sorting puzzle game where your goal is to clean up messy shelves layer by layer. Only the outermost layer of items is visible—clear them by matching three identical items, and reveal the hidden treasures beneath!', 'Match-3', 5, 'publish', '2026-04-19 09:18:58'),
(345, 'Kings and Queens Match 2', '33c4942945a2451189610f4effdda4eb', 'https://html5.gamedistribution.com/33c4942945a2451189610f4effdda4eb/', 'assets/thumbs/33c4942945a2451189610f4effdda4eb.jpg', 'Kings and Queens Match 2 is one of the most anticipated Match 3 sequels! This long-awaited second chapter features 2,500+ incredible levels full of magic and adventure. Join Princess Bella on a magical adventure, matching jewels and crowns to uncover hidden treasures. Create powerful boosters like Royal Bombs, hammers, and arrows to clear obstacles and win big. Stunning graphics and an enchanting soundtrack bring the kingdom to life. Get ready for a royal journey full of fun and surprises!', 'Match-3', 6, 'publish', '2026-04-19 09:18:59'),
(346, 'Mushroom Fever Match 3', 'cd0511c805e64eee88e6268af506d4c3', 'https://html5.gamedistribution.com/cd0511c805e64eee88e6268af506d4c3/', 'assets/thumbs/cd0511c805e64eee88e6268af506d4c3.jpg', 'Immerse yourself in the magical forest with Mushroom Fever - Match 3! Bright and cheerful mushrooms replace traditional crystals, adding a fresh twist to the classic match-3 genre. This game will bring you hours of thrilling fun and bursts of excitement!\r\n\r\nMatch groups of three or more mushrooms, complete engaging tasks, and unlock new levels! Each level brings unique puzzles and fresh challenges. The more matches you make, the more points and bonuses you’ll earn!', 'Match-3', 5, 'publish', '2026-04-19 09:19:03'),
(347, 'Shelf Shift Match', 'd677b28414fb4a69a13ed9ee99e30865', 'https://html5.gamedistribution.com/d677b28414fb4a69a13ed9ee99e30865/', 'assets/thumbs/d677b28414fb4a69a13ed9ee99e30865.jpg', 'Test your strategy and speed in Shelf Shift Match! Shift items on the shelves to create perfect matches of three, clearing the way to reveal hidden shadowed items. But beware—unwise moves can block your shelves, leaving no space to shift and leading to game over! If you\'re stuck, use the shuffle button to mix things up and find new matches.', 'Match-3', 6, 'publish', '2026-04-19 09:19:05'),
(348, 'Royal Jewels Match', '96dbf0d0323d48399eeea3a131b63c5a', 'https://html5.gamedistribution.com/96dbf0d0323d48399eeea3a131b63c5a/', 'assets/thumbs/96dbf0d0323d48399eeea3a131b63c5a.jpg', 'Matching jewels has never been so much fun! Unlock unique levels, participate in special events and take on surprising challenges. Collect coins with your matches and show off your decorating skills. Earn crowns as you progress and become a true master of the game!', 'Match-3', 5, 'publish', '2026-04-19 09:19:07'),
(349, 'Triple Sort 3D Home Design', '0cd9b933e1bc4b749615ebad5fb0933c', 'https://html5.gamedistribution.com/0cd9b933e1bc4b749615ebad5fb0933c/', 'assets/thumbs/0cd9b933e1bc4b749615ebad5fb0933c.jpg', 'Welcome to the world of Triple Sort 3D: Home Design, where matching meets decorating! Dive in the puzzle-solving with and begin crafting a virtual space of your dreams. Get ready to transform ugly and cluttered rooms  into clean and cozy spaces! Discover the perfect blend of challenges, creativity, and an epic makeover journey that awaits you!', 'Match-3', 3, 'publish', '2026-04-19 09:19:14'),
(350, 'MergeDuel.io', '05017bab2dbe4802968bf84231e08e24', 'https://html5.gamedistribution.com/05017bab2dbe4802968bf84231e08e24/', 'assets/thumbs/05017bab2dbe4802968bf84231e08e24.jpg', 'Merge Duel is a fast-paced 1v1 battle game where strategy and quick decisions lead to victory. Merge and upgrade your cannons to summon powerful units and counter your opponent in real time. Every match challenges your tactical skills as you adapt to new enemies and situations. Climb the ranks, dominate the leaderboard, and enjoy vibrant visuals, smooth controls, and intense duels from start to finish.', '.IO', 4, 'publish', '2026-04-19 09:19:49'),
(351, 'Obby Tower', '62e8b351034b46129fedb50065e06680', 'https://html5.gamedistribution.com/62e8b351034b46129fedb50065e06680/', 'assets/thumbs/62e8b351034b46129fedb50065e06680.jpg', 'Climb. Think. Survive.\r\n\r\nAscend a towering obstacle course filled with tricky jumps, moving platforms — and surprise math challenges! Combine your parkour skills with quick thinking to make it to the top.\r\n\r\nPerfect for players who love obbies and want to test both reflexes and brainpower.', '.IO', 4, 'publish', '2026-04-19 09:19:57'),
(352, 'Squid Game: Craft Runner', '144a9eab31c445c0b65818ed02eede8a', 'https://html5.gamedistribution.com/144a9eab31c445c0b65818ed02eede8a/', 'assets/thumbs/144a9eab31c445c0b65818ed02eede8a.jpg', 'Join the fun in Squid Game Subway Craft! Craft your way through obstacles and race along the railway tracks in a Minecraft-style world. Face exciting challenges, meet cool characters, and show your skills as you survive the ultimate test in this action-packed game inspired by Squid Game!&quot;\r\n\r\nLet me know if this works for you!se!', '.IO', 6, 'publish', '2026-04-19 09:20:11'),
(353, 'Online Cats Multiplayer Park', 'c59beda2a8c4425ea9e24ffa16158386', 'https://html5.gamedistribution.com/c59beda2a8c4425ea9e24ffa16158386/', 'assets/thumbs/c59beda2a8c4425ea9e24ffa16158386.jpg', 'Come to run, jump, guess, and race as a cute but competitive kitty in Online Cats - Multiplayer Park. It’s a real-time multiplayer chaos arena. Here are seven modes you can choose from. In Grab A Shabby Ball, for example, you will have to compete with your opponents and try to touch the ball to get points.', '.IO', 4, 'publish', '2026-04-19 09:20:15'),
(354, 'Meme challenge.io', '26f7528ce46f432da71a87d5851a1649', 'https://html5.gamedistribution.com/26f7528ce46f432da71a87d5851a1649/', 'assets/thumbs/26f7528ce46f432da71a87d5851a1649.jpg', '&quot;Meme Challenge.io&quot; is straight-up chaos.\r\nIt’s you vs. the wildest, most unhinged character names ever like Spaghetti Tualetti and Bombardino Crocodilo. Tap fast, think faster, and don’t get caught slippin’. It’s giving brain-lag.\r\nOnly real ones can vibe their way to the Wcup.', '.IO', 6, 'publish', '2026-04-19 09:20:17'),
(355, 'Last to leave circle Obby', '44cdf08900984b67a0b6573902b7439b', 'https://html5.gamedistribution.com/44cdf08900984b67a0b6573902b7439b/', 'assets/thumbs/44cdf08900984b67a0b6573902b7439b.jpg', 'Last to leave circle Obby - is a dynamic online game in the style of Roblox, where only the most dexterous and persistent can win! Exciting obby challenges, dangerous traps and intense battles with other players are waiting for you. Going outside the circle means you\'re out, and the circle is getting smaller and smaller!\r\n\r\nTense obby challenges that will test your reaction and agility.\r\nRoblox-style game with unique multiplayer.\r\nAbility to compete with friends and players from all over the world.', '.IO', 4, 'publish', '2026-04-19 09:20:18'),
(356, 'Agents io', '9ef3636ea95a4d2486dcfe05bc8393e1', 'https://html5.gamedistribution.com/9ef3636ea95a4d2486dcfe05bc8393e1/', 'assets/thumbs/9ef3636ea95a4d2486dcfe05bc8393e1.jpg', 'Play Agents.io online! Eliminate other agents, grow your team, and dominate the arena in this free game.\r\nAgents.io is a multiplayer action game where you control a lone agent and battle against others in an open arena. As you eliminate enemies, they join your team, allowing you to grow your squad and become stronger. The more agents you collect, the easier it is to dominate your opponents. Use smart tactics, avoid bigger squads, and climb to the top of the leaderboard!', '.IO', 5, 'publish', '2026-04-19 09:20:25'),
(357, 'Car Simulator 3d &amp; Car game 3d', 'ce2245d90f74418d9cc9c29d22d3d5ce', 'https://html5.gamedistribution.com/ce2245d90f74418d9cc9c29d22d3d5ce/', 'assets/thumbs/ce2245d90f74418d9cc9c29d22d3d5ce.jpg', 'In this school car parking simulator, you get to drive in the different car driving arenas skillfully with the various parking method and driving skills. Your love for 3d parking games will help you to play all levels and perform great driving in this offline parking game.', '.IO', 3, 'publish', '2026-04-19 09:20:27'),
(358, 'Mega Escape Car Parking Puzzle', 'd2a90fa6ac4b4aa88f8149ce8f8012f1', 'https://html5.gamedistribution.com/d2a90fa6ac4b4aa88f8149ce8f8012f1/', 'assets/thumbs/d2a90fa6ac4b4aa88f8149ce8f8012f1.jpg', 'A fun and compelling puzzle board game called Parking Jam. It\'s more than just parking; it\'s an enjoyable driving adventure that will advance you. Parking lot traffic jams, difficult parking conditions, irate seniors, and more. Play one of the best parking board games, earn rewards and unlock skins, solve harder and harder puzzles, decide which car to move to find smooth departs without hitting anybody or anything, characteristics.', '.IO', 4, 'publish', '2026-04-19 09:20:34'),
(359, 'Real Motorbike Super Hero Stunt 3D', 'cee4c00a8cb348cd8bf5e1f8e61b5513', 'https://html5.gamedistribution.com/cee4c00a8cb348cd8bf5e1f8e61b5513/', 'assets/thumbs/cee4c00a8cb348cd8bf5e1f8e61b5513.jpg', 'In this bike racing game performs insane stunts to impress. In bike stunts game you can show different type of stunts like jumping in the air and drifting as stunts man. Ride your bike in motorbike simulator 3d city environment while doing a stunt as a great biker for bike lovers.', '.IO', 7, 'publish', '2026-04-19 09:20:34'),
(360, 'Oil Tanker Transport Truck', 'd0776351a85944e6b2b7aede6cb19683', 'https://html5.gamedistribution.com/d0776351a85944e6b2b7aede6cb19683/', 'assets/thumbs/d0776351a85944e6b2b7aede6cb19683.jpg', 'Let\'s go on to ride with an oil tanker transporter truck across all the continents like the Euro, Asia, and America oil transporter truck game has real features in the Euro and American cargo systems of the fuel truck.', '.IO', 4, 'publish', '2026-04-19 09:20:36'),
(361, 'Color Race Obby', '7503d2eb0f044c0ba76a6360230c32bb', 'https://html5.gamedistribution.com/7503d2eb0f044c0ba76a6360230c32bb/', 'assets/thumbs/7503d2eb0f044c0ba76a6360230c32bb.jpg', 'Color Race Obby is an exciting game inspired by Roblox and Obby. Compete with players online on a field of colored blocks. Enter the race and become the champion! Join the fun!', '.IO', 3, 'publish', '2026-04-19 09:20:42'),
(362, 'Tsunami Race', '2e2d22d1aa92421397c32b1802be416d', 'https://html5.gamedistribution.com/2e2d22d1aa92421397c32b1802be416d/', 'assets/thumbs/2e2d22d1aa92421397c32b1802be416d.jpg', 'Have you ever faced the thrill of escaping a giant tsunami? In this action-packed game, you’ll choose from a variety of unique characters and race to stay ahead of your opponents. The game offers three exciting modes: outrun a tsunami in Tsunami Race, dodge flying fruits in Fruit Run, and slide to glory in Water Slides—knocking down opponents and collecting boosters along the way. Only the fastest and most strategic players will emerge as champions!', '.IO', 7, 'publish', '2026-04-19 09:20:45'),
(363, 'Mini Shooters', '4237b433eb5c4698a31e0cd0203fbbfa', 'https://html5.gamedistribution.com/4237b433eb5c4698a31e0cd0203fbbfa/', 'assets/thumbs/4237b433eb5c4698a31e0cd0203fbbfa.jpg', 'Mini Shooters: Experience fast-paced 2D action! Customize your loadout with a variety of powerful weapons. Dominate the battlefield with strategic movement and precise aim. Test your skills in thrilling deathmatch modes.', '.IO', 6, 'publish', '2026-04-19 09:20:54'),
(364, 'Mega Ramp Bike Racing Tracks', '726c74267da445daa18e9ad111a332c4', 'https://html5.gamedistribution.com/726c74267da445daa18e9ad111a332c4/', 'assets/thumbs/726c74267da445daa18e9ad111a332c4.jpg', 'Are you a real bike driver? Get this moto racing simulator from the bike simulator games and prove yourself as the best bike rider. Show your bike racing skills on the ramp in this unique bike driving game. It is the No.1 bike game from the free motorcycle games. Perform dangerous stunts on high sky impossible tracks and drive bike on crazy impossible tracks. Control the motorcycle in city superhero motorbike racer to become the ultimate bike rider.', '.IO', 5, 'publish', '2026-04-19 09:21:06'),
(365, 'Stack Battle.io', '82863b4af4f74252b2094a621cca159c', 'https://html5.gamedistribution.com/82863b4af4f74252b2094a621cca159c/', 'assets/thumbs/82863b4af4f74252b2094a621cca159c.jpg', 'It is a fun and casual puzzle. In the game, the game screen is fresh and simple, and the cute cartoon style is very eye-catching. The biggest highlight is the addition of tower defense battles to the brick-moving gameplay. The game level is very rich, and the gameplay is very simple. \r\nYou can control the movement of the character by pressing and sliding on the screen.\r\nWhat the player has to do is to control the character to collect the bricks on the map, stack the bricks and send them to your base. When there are enough bricks, your base will be upgraded and the area will be expanded and the number of tower defenses will be increased. \r\nWhen the enemy enters the range of your tower defense, you will be attacked. \r\nOn the contrary, when you enter the range of the enemy tower defense, you will also be attacked. whichever side is attacked and dies first will fail the game, otherwise it will succeed.\r\nPlayers who like brick-moving games come and download it.', '.IO', 5, 'publish', '2026-04-19 09:21:09'),
(366, 'Hungry Snake Io', 'a6195768e1d945678a79772c2e5dfc1f', 'https://html5.gamedistribution.com/a6195768e1d945678a79772c2e5dfc1f/', 'assets/thumbs/a6195768e1d945678a79772c2e5dfc1f.jpg', 'Hungry Snake.io is a classic game. Here you can try three game modes, Endless mode, Toilet Man, and Monster Brawl. Please note that there can be no collision between worms! In addition, our team takes user experience very seriously, we are always happy to improve the game so that every player can have a better gaming experience, if you encounter any difficulties during the game, please feel free to leave us a message!', '.IO', 6, 'publish', '2026-04-19 09:21:11'),
(367, 'Tank Battle.io', '02143684ea9943a691c58002542929fb', 'https://html5.gamedistribution.com/02143684ea9943a691c58002542929fb/', 'assets/thumbs/02143684ea9943a691c58002542929fb.jpg', 'Players can control the tank to perform various exciting missions and defeat the enemy. Players will have to synthesize a variety of weapons for tanks.\r\nThere are many tanks in the game that you can choose according to your preference. While completing the task, you must avoid obstacles at any time, and also constantly resist fire from enemy tanks\r\nEach level mode has a different difficulty that you can choose from.\r\n\r\nThe higher the level, the higher the stable income received.', '.IO', 4, 'publish', '2026-04-19 09:21:21'),
(368, 'Playground- Parkour', 'a401b3d40e884162b61632a0b9b257b5', 'https://html5.gamedistribution.com/a401b3d40e884162b61632a0b9b257b5/', 'assets/thumbs/a401b3d40e884162b61632a0b9b257b5.jpg', 'Jump and break bones, destroy enemies and unlock new levels! Ragdoll physics is what you need for parkour lovers. Train, participate in the battle and upgrade your hero! You will enjoy the game if you are a lover of the playground and stick games. Run, jump and maim the heroes. Ragdoll-style physics is what you love. Deals damage and unlock new levels! Stick and Ragdoll fans will be happy.', '.IO', 3, 'publish', '2026-04-19 09:21:30'),
(369, 'Fish Stab Getting Big', 'c8eb4b1fce564669b18ac49107fe0e8a', 'https://html5.gamedistribution.com/c8eb4b1fce564669b18ac49107fe0e8a/', 'assets/thumbs/c8eb4b1fce564669b18ac49107fe0e8a.jpg', 'These fishes have knives in their mouth and they are trying to kill each other with it. Try to kill as many as fishes and try to make your fish the biggest in the ocean. Each kill will give you a score and you and your sword will grow according to it. You can embark on this adventure with your friend in 1 Player and 2 Player game mode. Pick your game mode and fish, and let the action begin in the ocean.', '.IO', 6, 'publish', '2026-04-19 09:21:44'),
(370, 'Pixel Village Battle 3D.IO', '2ac89d5904024d89a9220203b764892f', 'https://html5.gamedistribution.com/2ac89d5904024d89a9220203b764892f/', 'assets/thumbs/2ac89d5904024d89a9220203b764892f.jpg', 'This is a shooting game that takes place in the countryside. It is divided into two teams: red and blue. They will be resurrected after each death. The team that kills more enemies wins. Let\'s play together.', '.IO', 5, 'publish', '2026-04-19 09:21:50'),
(371, 'Jixora – Jigsaw Solitaire Puzzle', 'c22dd33f66654986bf42e494c5934308', 'https://html5.gamedistribution.com/c22dd33f66654986bf42e494c5934308/', 'assets/thumbs/c22dd33f66654986bf42e494c5934308.jpg', 'Jixora is a relaxing jigsaw solitaire puzzle game where you piece together beautiful artwork. Journey through 100 unique levels with increasing difficulty, or unlock Free Play mode to replay your favorites with custom grid sizes. Race against the clock to earn stars, use strategic power-ups like Hints and Time Freezes, and immerse yourself in a cinematic atmosphere with soothing music.', 'Strategy', 5, 'publish', '2026-04-19 09:22:58'),
(372, 'Kaboom Miner', 'd43ed595d14e47a1ac6a4ff7456fd3b5', 'https://html5.gamedistribution.com/d43ed595d14e47a1ac6a4ff7456fd3b5/', 'assets/thumbs/d43ed595d14e47a1ac6a4ff7456fd3b5.jpg', 'A fast-paced logical arcade inspired by classic Boulder Dash, but taken to the next level with massive chain explosions.\r\nYour goal is simple—but dangerous: destroy all 50 explosive crates. Use falling stones, carefully placed bombs, and clever terrain manipulation to trigger devastating chain reactions. Every move matters. Push stones, move crates, build bridges from bricks, and even trap the Ghost before finishing it off.', 'Strategy', 5, 'publish', '2026-04-19 09:23:01'),
(373, 'Aqua Sort: Water Color Puzzle', '7a83d41c26c54898892c807492494f21', 'https://html5.gamedistribution.com/7a83d41c26c54898892c807492494f21/', 'assets/thumbs/7a83d41c26c54898892c807492494f21.jpg', 'Dive into the relaxing world of Aqua Sort: Water Color Puzzle! Your goal is simple: sort the colored liquids into the flasks until each flask contains only one color. With over 1000 levels and unique modes like Color Fusion, Mystery, and Time Trial, this puzzle game will test your logic and patience. Unlock new themes and achievements as you play!', 'Strategy', 6, 'publish', '2026-04-19 09:23:03'),
(374, 'Radical Rappelling', 'ebe47e4a2ba74df39ab40cb9f0d09705', 'https://html5.gamedistribution.com/ebe47e4a2ba74df39ab40cb9f0d09705/', 'assets/thumbs/ebe47e4a2ba74df39ab40cb9f0d09705.jpg', 'Feel the rush and hold on tight as Radical Rappelling is back!\r\n\r\nJoin Rip and Roxy as you rappel down mountains at breakneck speed using your rapid reflexes.\r\n\r\nPull off death-defying tricks by ricocheting between launch pads, riding rainbows and rocketing over obstacles in the most redonkulous adventure ever.\r\n\r\nRack up coins and complete rockin’ missions to unlock sweet new gear for Rip and Roxy, the most fearless risk-takers on the planet.', 'Strategy', 6, 'publish', '2026-04-19 09:23:12'),
(375, 'Rocket Fest', 'd3f1005739584e1294bc7474ce166340', 'https://html5.gamedistribution.com/d3f1005739584e1294bc7474ce166340/', 'assets/thumbs/d3f1005739584e1294bc7474ce166340.jpg', 'Control the rocket to collect energy or other useful props along the way, and bomb the target at the end! This is a casual stress relief game.', 'Strategy', 4, 'publish', '2026-04-19 09:23:24'),
(376, 'JUMPER', '70f45225c4364584abc12fd8f7504c78', 'https://html5.gamedistribution.com/70f45225c4364584abc12fd8f7504c78/', 'assets/thumbs/70f45225c4364584abc12fd8f7504c78.jpg', 'Bounce your way to record-breaking heights in JUMPER! Dodge epic traps, collect unique power-ups, and enjoy upgraded visuals as you climb higher and higher.\r\n\r\nUnlock adorable skins and earn achievements as you master your jumps. Whether you\'re aiming for the top or just chilling, JUMPER offers a relaxing platform-hopping experience packed with charm.', 'Strategy', 4, 'publish', '2026-04-19 09:23:43'),
(377, 'Sort Tiles', '5d6e368f1b55466aa897cb7f0c67419c', 'https://html5.gamedistribution.com/5d6e368f1b55466aa897cb7f0c67419c/', 'assets/thumbs/5d6e368f1b55466aa897cb7f0c67419c.jpg', 'Sort Tiles: Tap Away is a fun and addictive puzzle game where you move tiles, clear the board, and reveal hidden pictures. It’s simple to learn but offers endless logic challenges that keep your brain active. Perfect for fans of tile puzzles, logic games, and relaxing brain teasers.\r\n\r\nKey Features:\r\nUnique puzzle mechanics — move tiles in the arrow’s direction and solve logic puzzles step by step.\r\nHidden images — every cleared puzzle board reveals a new picture.', 'Strategy', 4, 'publish', '2026-04-19 09:23:44'),
(378, '3D Chess Master', 'd8dea5d83d1c4132a119fabedbc60bd6', 'https://html5.gamedistribution.com/d8dea5d83d1c4132a119fabedbc60bd6/', 'assets/thumbs/d8dea5d83d1c4132a119fabedbc60bd6.jpg', '3D Chess Master – The ultimate 3D chess experience! Enjoy stunning three-dimensional graphics while testing your strategy skills. Challenge your friends in head-to-head matches or take on powerful AI opponents in the most immersive chess game yet.', 'Strategy', 6, 'publish', '2026-04-19 09:23:49'),
(379, 'My Tiny Market', '4a0b780699b44c9cac8dfbda58a0dd04', 'https://html5.gamedistribution.com/4a0b780699b44c9cac8dfbda58a0dd04/', 'assets/thumbs/4a0b780699b44c9cac8dfbda58a0dd04.jpg', 'In My Tiny Market, you\'re the boss of your very own supermarket. Manage your time and resources well to find the perfect balance between all your tasks: restock shelves, serve customers and keep everything running at full speed!', 'Strategy', 4, 'publish', '2026-04-19 09:24:00'),
(380, 'Neighborhood Defense', 'aac365d8418b460f80a27e6b1c0e05fa', 'https://html5.gamedistribution.com/aac365d8418b460f80a27e6b1c0e05fa/', 'assets/thumbs/aac365d8418b460f80a27e6b1c0e05fa.jpg', 'Neighborhood Defense is a dynamic tower defense strategy game where your mission is to protect your neighborhood from waves of zombies. Diverse maps with multiple exits, different types of enemies, and limited tower spots make each match unique. Upgrade your towers, combine their abilities, and plan your tactics carefully to stop the horde and prevent them from breaking through.', 'Strategy', 8, 'publish', '2026-04-19 09:24:01'),
(381, 'Ship Out', '233db5ed35e349469befd32b73b157a9', 'https://html5.gamedistribution.com/233db5ed35e349469befd32b73b157a9/', 'assets/thumbs/233db5ed35e349469befd32b73b157a9.jpg', 'The harbor’s a mess! Ships of all sizes and colors are stuck in a massive jam. Pay attention to their direction, plan your moves, and clear the chaos! Need help? Use special power-ups to sail through tougher levels.', 'Strategy', 6, 'publish', '2026-04-19 09:24:02'),
(382, 'Squid Game Hunter', '80df807ffe8a4f41b30c2e647d3567e2', 'https://html5.gamedistribution.com/80df807ffe8a4f41b30c2e647d3567e2/', 'assets/thumbs/80df807ffe8a4f41b30c2e647d3567e2.jpg', 'Step into the thrilling world of Squid Game – a fast-paced game for stealthy and strategic players that takes you on a wild adventure as a hunter with a deadly knife. With multiple Squid games enemies to kill, challenging missions to complete, and rewards to collect, this game will test your skills and keep you on the edge of your seat.', 'Strategy', 5, 'publish', '2026-04-19 09:24:29'),
(383, 'Squad Assembler', '7003abf25cb3479eb3a8e0b5a02a3db6', 'https://html5.gamedistribution.com/7003abf25cb3479eb3a8e0b5a02a3db6/', 'assets/thumbs/7003abf25cb3479eb3a8e0b5a02a3db6.jpg', 'Assemble a cool squad and see who wins!\r\nCombine items to improve the fighters\' equipment! Combine weapons and armor, buy loot boxes with new weapons!\r\nYou can create cool, unique characters, each of which will have certain skills! Buy parts for your fighters, change their arms, torso, head! Create real cyborgs to defeat the enemy! Merge armor and weapons, increase the levels and characteristics of items. Hire cool heroes who will help you in tough battles.', 'Strategy', 7, 'publish', '2026-04-19 09:24:31'),
(384, 'Cat Rescue', '75e97aad438a47718dfd50f8e7e4fa87', 'https://html5.gamedistribution.com/75e97aad438a47718dfd50f8e7e4fa87/', 'assets/thumbs/75e97aad438a47718dfd50f8e7e4fa87.jpg', 'Protect the cat from dragon invasions through strategic sort puzzle combat. As enemies display colored patterns, your cannon must sort puzzle sequences to match their hues. Click the correctly colored cannon to obliterate matching dragon sections. Each precise cannon shot slows their advance toward the cat! Repeat until dragon threats vanish, but remember: rescue missions demand speed and sort puzzle accuracy!', 'Strategy', 5, 'publish', '2026-04-19 09:24:33'),
(385, 'Family Idle Farm: Build &amp; Harvest', 'eb01559f442a4f34a3cdb9a96bba7339', 'https://html5.gamedistribution.com/eb01559f442a4f34a3cdb9a96bba7339/', 'assets/thumbs/eb01559f442a4f34a3cdb9a96bba7339.jpg', 'Play Family Idle Farm: Build &amp; Harvest free online and grow your dream farm in a cozy browser game you can play instantly with no download and no install. Plant crops, raise animals, and upgrade your land in a relaxing strategy experience that feels like a light brain game of smart planning. This unblocked game loads fast and runs smoothly at school or home. Fully mobile-friendly and optimized for desktop and mobile, it’s a free online game perfect for quick breaks or laid-back farming anytime.', 'Strategy', 5, 'publish', '2026-04-19 09:24:35'),
(386, 'Stickman Guys Defense', '46be65604ed04bc8808506bcaacd0a9a', 'https://html5.gamedistribution.com/46be65604ed04bc8808506bcaacd0a9a/', 'assets/thumbs/46be65604ed04bc8808506bcaacd0a9a.jpg', 'Stickman Guys Defense is an action-packed tower defense game where you must protect your base from endless waves of enemies! Command a team of brave stickman warriors, place them strategically, and upgrade their abilities to stop the invasion. From archers to sword fighters, build the ultimate defense and survive each level!\r\n\r\nCan you defend your land and become the ultimate Stickman commander?', 'Strategy', 6, 'publish', '2026-04-19 09:24:41'),
(387, 'Kingdom Puzzles', '45408603e10348e78d7fb508fc729216', 'https://html5.gamedistribution.com/45408603e10348e78d7fb508fc729216/', 'assets/thumbs/45408603e10348e78d7fb508fc729216.jpg', 'Kingdom Puzzle is a relaxing brain game where you see a grid with different colored regions. Your goal is to place one king in each region while following the rules. Each region can have only one king, and kings cannot be in the same row or column. They also cannot be next to each other, meaning the nearest tiles must be empty. To win the level, you must place all kings correctly. Placing a king in the wrong spot reduces your points.', 'Strategy', 5, 'publish', '2026-04-19 09:24:51'),
(388, 'Unlock the Bolts', '689cb6438daf4299b8c2915adc2955ed', 'https://html5.gamedistribution.com/689cb6438daf4299b8c2915adc2955ed/', 'assets/thumbs/689cb6438daf4299b8c2915adc2955ed.jpg', 'Unlock the Bolts is a challenging puzzle game where you carefully remove screws to solve mechanical puzzles. Each level tests your logic and precision as you figure out the correct order to unlock the bolts. In special levels, the stakes are even higher—you must free trapped animals by unlocking the right bolts! With satisfying mechanics and engaging challenges, this game will keep you thinking and entertained. Can you master every puzzle and rescue the animals in need?', 'Strategy', 7, 'publish', '2026-04-19 09:25:08'),
(389, 'С21A', 'c3d539dd153f4ae5aec8057a2b4ccadf', 'https://html5.gamedistribution.com/c3d539dd153f4ae5aec8057a2b4ccadf/', 'assets/thumbs/c3d539dd153f4ae5aec8057a2b4ccadf.jpg', 'The endless card game &quot;C21A&quot; is an exciting combination of classic blackjack and addictive strategy. In this game, your goal is to collect cards to score 21 points. But be careful not to overdo it or you will lose! The game offers endless opportunities to develop and improve your skills.\r\nThe game &quot;C21A&quot; is a great way to pass your time and test your skills in card games.', 'Care', 3, 'publish', '2026-04-19 09:25:18'),
