(421, 'Head Soccer Arena', '4c6790dc7ba5480ba7c1b619bdefdd3f', 'https://html5.gamedistribution.com/4c6790dc7ba5480ba7c1b619bdefdd3f/', 'assets/thumbs/4c6790dc7ba5480ba7c1b619bdefdd3f.jpg', 'Head Soccer Arena takes you into a fast-paced football world! Play 2-player matches on the same device, dive into quick games, or rise through 15 leagues in Career Mode. Win matches, collect coins and diamonds, and upgrade your power-ups—ice, lightning, anvil, big head, and more! Unlock new characters and dominate the field with strategy, skill, and speed. Every match is a step toward football glory!', 'Football', 4, 'publish', '2026-04-19 10:22:56'),
(422, 'Football Heads 2025', '8d6f5a0f38c94c6b8a013ac330e85c3c', 'https://html5.gamedistribution.com/8d6f5a0f38c94c6b8a013ac330e85c3c/', 'assets/thumbs/8d6f5a0f38c94c6b8a013ac330e85c3c.jpg', 'Unlock your potential and prove your skills. Outplay your opponents using powerful kicks and unique power-ups. Finally let them know who is the boss with the emotes system - become a football legend today!', 'Football', 3, 'publish', '2026-04-19 10:23:10'),
(423, 'Strike It!', '3a9479344a1d43a29ded5f92ac519664', 'https://html5.gamedistribution.com/3a9479344a1d43a29ded5f92ac519664/', 'assets/thumbs/3a9479344a1d43a29ded5f92ac519664.jpg', 'A cool game where you need to shoot down all the little men so that they fly in different directions! Bright locations and a lot of challenging tasks are waiting for you! Show accuracy and foresight: everything depends on the trajectory of the blow!', 'Football', 3, 'publish', '2026-04-19 10:23:23');
INSERT INTO `games` (`id`, `title`, `slug`, `iframe_url`, `image_url`, `description`, `category`, `views`, `status`, `created_at`) VALUES
(424, 'Kick Zombie Voodoo', 'dd9c630557ca4c568d28db1a08bab8f4', 'https://html5.gamedistribution.com/dd9c630557ca4c568d28db1a08bab8f4/', 'assets/thumbs/dd9c630557ca4c568d28db1a08bab8f4.jpg', 'Welcome to Kick Zombie Voodoo, a thrilling action and brain-burning game. Take on the role of a fearless zombie hunter and prepare to battle hordes of undead creatures. Armed with powerful weapons and tools, your ultimate goal is to destroy the last zombie and save humanity from the impending apocalypse. Will you manage to escape?', 'Football', 4, 'publish', '2026-04-19 10:23:31'),
(425, 'Football Kickoff', '4a13848d5f2d4051a34deda6e5d84d10', 'https://html5.gamedistribution.com/4a13848d5f2d4051a34deda6e5d84d10/', 'assets/thumbs/4a13848d5f2d4051a34deda6e5d84d10.jpg', 'Some say it is the hardest position in the game of American football and now it is your turn to take the field and show what you got! Kick the football through the goalposts to score. Take careful note of wind, angle and power. Kick your way to the top of the scoreboard and send your team to victory!', 'Football', 5, 'publish', '2026-04-19 10:23:32'),
(426, 'Kick the President', '14e2b4c4cdaa437ead903ebae3504ad4', 'https://html5.gamedistribution.com/14e2b4c4cdaa437ead903ebae3504ad4/', 'assets/thumbs/14e2b4c4cdaa437ead903ebae3504ad4.jpg', 'The President is waiting for you to tease him for a bit. Explode, destroy, fire, shoot, freeze, send the power of the Metal Bar and don\'t even think about stopping! You now have a virtually limitless arsenal: rockets, grenades, automatic rifles, torture instruments… and even a Flamethrower! We present to you Kick the Biden — it’s more than just a game! Want more kicks? Even if you\'re a relatively stress-free person you need to blow off steam at some point or another! Show him the American Power!', 'Football', 5, 'publish', '2026-04-19 10:23:41'),
(427, 'Football Brawl', '65c45480d84a4680a7f322bd548b3cad', 'https://html5.gamedistribution.com/65c45480d84a4680a7f322bd548b3cad/', 'assets/thumbs/65c45480d84a4680a7f322bd548b3cad.jpg', 'Live your football story! Enter the field, and decimate your opponent with various powerful kicks and fun and quirky powerups. Finally, let them know who is the boss with the emotes system - become a football legend today!', 'Football', 4, 'publish', '2026-04-19 10:24:03'),
(428, '2 Player Imposter Soccer', '988efc7108c14675b1fcac7e10102e24', 'https://html5.gamedistribution.com/988efc7108c14675b1fcac7e10102e24/', 'assets/thumbs/988efc7108c14675b1fcac7e10102e24.jpg', 'Are you ready for the exciting duel? If you\'re ready, let\'s get started without wasting time. Because a perfect two player head soccer is waiting for you.\r\n\r\nIn this mini soccer game, you can play against dozens of real players or challenge your friends in 2 player mode. Control the ball by jumping, moving forward and backward. Hit the opposing goal with your best shot! The player who scores the most goals until the final whistle wins the game. This extremely fun game is suitable for children.\r\n\r\nLet\'s start the game, win and become a football star!', 'Football', 3, 'publish', '2026-04-19 10:24:15'),
(429, 'Europe Soccer Cup 2021', '58e42c87c17a40fe8949eb8843c98886', 'https://html5.gamedistribution.com/58e42c87c17a40fe8949eb8843c98886/', 'assets/thumbs/58e42c87c17a40fe8949eb8843c98886.jpg', 'Twenty four best soccer teams in europe are competing to get the first place in the 2020 Europe Soccer Cup, Do you think you can choose a team and do it?', 'Football', 6, 'publish', '2026-04-19 10:24:31'),
(430, '3D Kid Sliding Puzzle', 'ad85d363343e47b5b396d086b9087d82', 'https://html5.gamedistribution.com/ad85d363343e47b5b396d086b9087d82/', 'assets/thumbs/ad85d363343e47b5b396d086b9087d82.jpg', 'We\'ve taken the classic sliding puzzle into a whole new 3D world. Kids will need to slide the scrambled blocks to rearrange them and complete adorable cartoon pictures, such as little animals, vehicles, and fairy-tale characters. The game features vibrant colors and lively 3D models that will immediately capture a child\'s attention. Not only does it provide hours of fun, but it also helps develop a child\'s logical thinking, spatial awareness, and problem-solving skills.', 'Educational', 4, 'publish', '2026-04-19 10:24:56'),
(431, 'Color Water Puzzle', '0ea7b7e7316a47c38ac5c98ddd42ec4a', 'https://html5.gamedistribution.com/0ea7b7e7316a47c38ac5c98ddd42ec4a/', 'assets/thumbs/0ea7b7e7316a47c38ac5c98ddd42ec4a.jpg', 'Color Water Puzzle is a fun and addictive puzzle game! The goal is simple yet challenging: try to sort the colored water in the glasses until all colors are in the same glass.\r\n\r\nIt’s not just a game; it\'s a great way to relieve stress and exercise your logic. With vibrant colors and smooth pouring effects, this is the best choice to kill time and relax your mind.\r\n\r\nAre you smart enough to solve all the levels? Download now and find out!', 'Educational', 4, 'publish', '2026-04-19 10:24:56'),
(432, 'Mind Games: Math Crosswords', 'e0592e6ecdf54ec7b3d67355b0e5a8d2', 'https://html5.gamedistribution.com/e0592e6ecdf54ec7b3d67355b0e5a8d2/', 'assets/thumbs/e0592e6ecdf54ec7b3d67355b0e5a8d2.jpg', 'Mind Games: Math Crosswords is a game to improve your math skills. It is a great way to spend your time. \r\nThe player\'s mission is to save the planet from extinction. The aliens have destroyed all the plants on the planet. However, humans have found a solution. Engineers have built ships that convert brain activity into life-giving energy to grow plants. By solving mathematical problems, you are contributing to the restoration of plants and the regeneration of our planet.', 'Educational', 4, 'publish', '2026-04-19 10:25:01'),
(433, 'Math Lava: Tower Race', '9c760581e6bf486f8a43e1813614f6bd', 'https://html5.gamedistribution.com/9c760581e6bf486f8a43e1813614f6bd/', 'assets/thumbs/9c760581e6bf486f8a43e1813614f6bd.jpg', 'Test your math skills under pressure in Math Lava: Tower Race, a fast-paced Roblox style web game where quick thinking and accurate answers are your keys to survival. Answer math questions correctly to build blocks beneath you, racing against opponents and rising lava. The faster and more accurate you are, the higher you climb!', 'Educational', 5, 'publish', '2026-04-19 10:25:09'),
(434, 'Math Duck', '35e1ca81ddb84e73879bb7671e8902ad', 'https://html5.gamedistribution.com/35e1ca81ddb84e73879bb7671e8902ad/', 'assets/thumbs/35e1ca81ddb84e73879bb7671e8902ad.jpg', 'You play as a fearless duck who battles enemies not with brute force, but with math smarts.\r\n\r\nThe rules are simple but addictive:\r\n- Pick from shuffled number cards and combine them to make 10.\r\n- Each correct match becomes your attack to damage enemies.\r\n- Defeat foes, earn XP, and level up your duck!\r\n\r\nEvery level-up lets you choose from 3 unique upgrades. Each run is different, and your choices shape the way your duck fights.\r\n\r\nSharpen your mind, master the numbers, and guide your duck to victory!', 'Educational', 7, 'publish', '2026-04-19 10:25:13'),
(435, 'Tarcat', '8cd322364cd04efd836221431312f0ca', 'https://html5.gamedistribution.com/8cd322364cd04efd836221431312f0ca/', 'assets/thumbs/8cd322364cd04efd836221431312f0ca.jpg', 'Enter the world of feline destruction with Tarcat, a hilarious casual game where you control a cats paw! Your goal? Smash all targets with quick reflexes and pinpoint accuracy!\r\n\r\nWith just one tap, hit targets, avoid traps, and dominate each level with the style of a true feline destroyer.', 'Educational', 4, 'publish', '2026-04-19 10:25:17'),
(436, 'Math Runner', 'a8870b5a6a76492db5cb8ca599f64843', 'https://html5.gamedistribution.com/a8870b5a6a76492db5cb8ca599f64843/', 'assets/thumbs/a8870b5a6a76492db5cb8ca599f64843.jpg', 'Challenge your mind and reflexes in this fast-paced arithmetic adventure! Solve math problems on the run, dodge obstacles, and race against time to achieve the highest score. Perfect for players of all ages looking to sharpen their math skills while enjoying thrilling gameplay.', 'Educational', 5, 'publish', '2026-04-19 10:25:22'),
(437, 'Brainrot Memory', '0eec782d61e6449ab2e3ecc02272bcad', 'https://html5.gamedistribution.com/0eec782d61e6449ab2e3ecc02272bcad/', 'assets/thumbs/0eec782d61e6449ab2e3ecc02272bcad.jpg', 'Memory Brainrot: Boost Your Brain with Meme Power!\r\n\r\nFlip cards, match pairs, and meet iconic characters from the Italian Brainrot meme universe! Play in a vibrant cartoon world, train your memory, and unlock chaotic fun. With two difficulty levels and dozens of legendary meme heroes to discover, this game is both brain-boosting and hilarious. Dive into pure meme madness and rot your brain... but in the best way! ??', 'Educational', 6, 'publish', '2026-04-19 10:25:26'),
(438, 'DayCare Tycoon', 'd9f930a985ba4d2fb94100f6daeee6b8', 'https://html5.gamedistribution.com/d9f930a985ba4d2fb94100f6daeee6b8/', 'assets/thumbs/d9f930a985ba4d2fb94100f6daeee6b8.jpg', 'Are you ready to build your dream business empire and be a great babysitter in this money tycoon simulator ? Dive into the world of daycare games and experience the joy of managing your own thriving idle tycoon games. From welcoming adorable babies to creating a safe and happy environment, this game offers everything you need to grow your daycare business into a successful venture.', 'Educational', 6, 'publish', '2026-04-19 10:25:30'),
(439, 'Sprunki Mini Games', 'faab3705c7ee4e77902afe18221d7fda', 'https://html5.gamedistribution.com/faab3705c7ee4e77902afe18221d7fda/', 'assets/thumbs/faab3705c7ee4e77902afe18221d7fda.jpg', 'We present you a compilation of several games with the famous characters Sprunki. The first game is the classic Sprunki game but with an expanded orchestra, that is, with 9 singers. In the second game, you are presented with 10 pictures to color. While the third is a game of finding differences where you have 20 levels with 10 differences on each level.', 'Educational', 5, 'publish', '2026-04-19 10:25:40'),
(440, 'Baby Piano Children Song', 'e1cc36b2c6c7411c94a590265ea2d15d', 'https://html5.gamedistribution.com/e1cc36b2c6c7411c94a590265ea2d15d/', 'assets/thumbs/e1cc36b2c6c7411c94a590265ea2d15d.jpg', 'Do you like playing musical instruments? If you love music, we have just the game for you. This educational game offers 5 musical instruments to choose from. They are piano, xylophone, flute, drums, and guitar. You can select the instrument you are interested in playing. Apart from\r\noffering a wide range of instruments, this game lets you choose your favorite music.', 'Educational', 4, 'publish', '2026-04-19 10:25:47'),
(441, 'Bottle challenge', 'a03c94a59c2b4fcb8e3fe862f99f15d6', 'https://html5.gamedistribution.com/a03c94a59c2b4fcb8e3fe862f99f15d6/', 'assets/thumbs/a03c94a59c2b4fcb8e3fe862f99f15d6.jpg', 'This is a puzzle game, the game provides different volumes of the kettle, according to the game level prompts each kettle needs a different magnitude, to reach the required magnitude of the prompt can be cleared', 'Educational', 8, 'publish', '2026-04-19 10:25:48'),
(442, 'Summer Spotlight Differences', '77acc3ee9dbc4458973045f0eba6a7f2', 'https://html5.gamedistribution.com/77acc3ee9dbc4458973045f0eba6a7f2/', 'assets/thumbs/77acc3ee9dbc4458973045f0eba6a7f2.jpg', 'Dive into the sunny and captivating world of Summer Spotlight Differences, a delightful spot-the-difference game that\'s perfect for all ages. This engaging game challenges you to find all 5 differences in each level to advance to the next, offering endless fun and a great way to sharpen your observational skills. Enjoy the challenge and have a blast with this fantastic spot-the-difference game!', 'Educational', 6, 'publish', '2026-04-19 10:25:59'),
(443, 'Clean The Ocean', '5afd99347edd4dbb8d9e73f4caf0db6c', 'https://html5.gamedistribution.com/5afd99347edd4dbb8d9e73f4caf0db6c/', 'assets/thumbs/5afd99347edd4dbb8d9e73f4caf0db6c.jpg', 'Pick up waste, clean up oil spills and heal the oceans bit by bit! Venture out on your own boat, clear out parts of the sea and make sure you recycle everything properly. This game is the perfect way to teach kids about ecology and recycling, or just to pass the time in a mindful way. Level up the ship and leave a lasting legacy on planet Earth.', 'Educational', 4, 'publish', '2026-04-19 10:26:02'),
(444, 'Animegao Kigurumi DIY', 'caa591ddccac4634a6df05fa3c8407ef', 'https://html5.gamedistribution.com/caa591ddccac4634a6df05fa3c8407ef/', 'assets/thumbs/caa591ddccac4634a6df05fa3c8407ef.jpg', 'Welcome to the exciting world of Animegao! Create your own character in animegao style. But first you need to create a mask that will become the basis of the whole image. Then you can choose the makeup, outfits and accessories you like from the available rich wardrobe. Immerse yourself in the magical world of fashion and creativity with our animegao-style dress-up game. Let\'s start this exciting fashion journey together!', 'Educational', 6, 'publish', '2026-04-19 10:26:07'),
(445, 'Mini Planet - Kids &amp; Toddlers Educational Games', 'd44f4b1b23244ebc8d00b2784fffd1e6', 'https://html5.gamedistribution.com/d44f4b1b23244ebc8d00b2784fffd1e6/', 'assets/thumbs/d44f4b1b23244ebc8d00b2784fffd1e6.jpg', 'An amazing planet full of various interesting and unique games and activities! Games that will help your kids learn lots of new things about different subjects while having fun!\r\n\r\nWant to learn the English letters? Eager to learn about domestic and wild animals and even dinosaurs?! That’s nothing! In Happy Planet, there are lots of places that kids can go to and play fun games to learn new things about fruits, colors, vegetables, home appliances, mathematics, vehicles and etc.! \r\n\r\nThis is just the beginning and we have lots of new features in mind that we will add gradually to the game!', 'Educational', 6, 'publish', '2026-04-19 10:26:15'),
(446, 'Clicker Hero', '8f137bff27e24f159677fcba28b2d2f4', 'https://html5.gamedistribution.com/8f137bff27e24f159677fcba28b2d2f4/', 'assets/thumbs/8f137bff27e24f159677fcba28b2d2f4.jpg', 'Click on the screen to defeat the monsters and earn gold in Clicker Hero. Spend your gold to buy and upgrade heroes that deal damage automatically. Then advance to fight tougher monsters that drop more gold. This game keeps going, even when you\'re offline, so come back later to earn and spend even more!', 'Merge', 2, 'publish', '2026-04-19 10:27:07'),
(447, 'Melon Drop: Fruit Merge Master', '32cc670347b540758dfb363a4500023e', 'https://html5.gamedistribution.com/32cc670347b540758dfb363a4500023e/', 'assets/thumbs/32cc670347b540758dfb363a4500023e.jpg', 'Dive deep into the vibrant and enthralling world of fruit-matching with our exciting game, Fruit Merge: Juicy Drop Game! ??? When the same fruits collide, they merge into a larger fruit. Your mission is to smartly pair the same types of fruits to make the biggest possible fruits without letting them overflow from the container. However, as the fruits grow in size, space becomes a premium - managing it effectively is your key challenge. Can you strategize and solve this fruity puzzle?', 'Merge', 4, 'publish', '2026-04-19 10:27:08'),
(448, 'Ice Cube', 'b51341f2f9ab4bc09b23312b5bff30cb', 'https://html5.gamedistribution.com/b51341f2f9ab4bc09b23312b5bff30cb/', 'assets/thumbs/b51341f2f9ab4bc09b23312b5bff30cb.jpg', 'Ice Cubes is a Blast (or Collapse) type Match-3 game. Don\'t be fooled by its cool appearance... this game requires nerves of steel to achieve the best score in just 1 minute and 30 seconds.', 'Merge', 4, 'publish', '2026-04-19 10:27:13'),
(449, 'Merge Pixel', '72b219a0450c465c81f3cd1ebdafb815', 'https://html5.gamedistribution.com/72b219a0450c465c81f3cd1ebdafb815/', 'assets/thumbs/72b219a0450c465c81f3cd1ebdafb815.jpg', 'Attractive characters in dot, pixel style!\r\nCombining the same characters creates a higher level of characters.\r\nRepeat Merge to create a legendary character.', 'Merge', 2, 'publish', '2026-04-19 10:27:28'),
(450, 'Merge Haven', '4a671eb17a2a44e19b18143242c155fc', 'https://html5.gamedistribution.com/4a671eb17a2a44e19b18143242c155fc/', 'assets/thumbs/4a671eb17a2a44e19b18143242c155fc.jpg', 'Merge items to restore the café to its former glory, uncover hidden secrets, and discover its mysterious past. Start merging today to reveal the café\'s enchanting story!', 'Merge', 3, 'publish', '2026-04-19 10:27:37'),
(451, 'Crazy Fruit Merge', 'bc81c0b82dba4e318c9aa206146912f3', 'https://html5.gamedistribution.com/bc81c0b82dba4e318c9aa206146912f3/', 'assets/thumbs/bc81c0b82dba4e318c9aa206146912f3.jpg', 'Looking for the perfect relaxing game? Sometimes all you need is a fun puzzle. Merge fruits, challenge your mind and use power-ups to keep the game flowing. Progress further and aim for the highest score!', 'Merge', 2, 'publish', '2026-04-19 10:27:42'),
(452, 'Merge Brainrot 2', '27e2be0b934544e39d8de96e01fcf851', 'https://html5.gamedistribution.com/27e2be0b934544e39d8de96e01fcf851/', 'assets/thumbs/27e2be0b934544e39d8de96e01fcf851.jpg', 'Drop and merge the new  Italian Brainrot memes!\r\nFrom &quot;Bobrito Bandito&quot; to &quot;Špijuniro Golubiro&quot; and &quot;Burbaloni Lulilolli&quot;, they’re all here.\r\nWhat final Brainrot will you unlock? Dare to find out!', 'Merge', 3, 'publish', '2026-04-19 10:27:50'),
(453, 'Merge Brainrot', 'ea08335b6c9043e7a2403f6d5e8d1664', 'https://html5.gamedistribution.com/ea08335b6c9043e7a2403f6d5e8d1664/', 'assets/thumbs/ea08335b6c9043e7a2403f6d5e8d1664.jpg', 'Drop and merge the most cursed Italian Brainrot memes!\r\nFrom &quot;Trallallero Trallala&quot; to &quot;Tum Tum Tum Saur! and &quot;Boneca Ambalabu&quot;, they’re all here.\r\nWhat final Brainrot will you unlock? Dare to find out!', 'Merge', 4, 'publish', '2026-04-19 10:27:55'),
(454, 'Cubatoria Merge 2048', '4c2e9c50a9654c4f80258793b8390023', 'https://html5.gamedistribution.com/4c2e9c50a9654c4f80258793b8390023/', 'assets/thumbs/4c2e9c50a9654c4f80258793b8390023.jpg', 'Welcome to the exciting world of Cubatoria Merge 2048! This game combines elements of the classic 2048 game with a three-dimensional visual design, which makes it unique and exciting.\r\n\r\nThe game is designed for fans of puzzles, logic games and those who appreciate a creative approach to classic concepts. Cubatoria Merge 2048 promises an exciting immersion in virtual space with the opportunity to enjoy a new visual experience.', 'Merge', 4, 'publish', '2026-04-19 10:28:02'),
(455, 'Merge Magnat - IDeaL Store', 'e92231f3a9c54976a50111b094a99933', 'https://html5.gamedistribution.com/e92231f3a9c54976a50111b094a99933/', 'assets/thumbs/e92231f3a9c54976a50111b094a99933.jpg', 'Welcome to the world of trade, where you can create your own shopping district! In this engaging game, you will build the area by placing various shops and attracting customers who will spend money. Merge similar shops to create higher-level versions that yield more profit. Watch as customers pass by your stores, leaving money while you relax and enjoy the game.', 'Merge', 5, 'publish', '2026-04-19 10:28:08'),
(456, 'Garden Guardians', '9dc10bd82d1b4819859247602b19b802', 'https://html5.gamedistribution.com/9dc10bd82d1b4819859247602b19b802/', 'assets/thumbs/9dc10bd82d1b4819859247602b19b802.jpg', 'Garden Guardians is a casual mobile game that merges strategic tower defense with physics-based ballistics. Players take on the role of a countryside guardian, ‌dragging and combining fruits with unique properties to build cannons‌, which they upgrade to fend off relentless dragon invasions.\r\nWill you let the farmland fall, or will you erect an unbreakable defense with fruit-powered artillery? The joy of the harvest hinges on your firepower!', 'Merge', 3, 'publish', '2026-04-19 10:28:08'),
(457, 'Dice Merge', '7201965a39e8408fbbbb268f14557582', 'https://html5.gamedistribution.com/7201965a39e8408fbbbb268f14557582/', 'assets/thumbs/7201965a39e8408fbbbb268f14557582.jpg', 'Dive into Dice Merge Challenges, a game that blends strategic merging with thrilling destruction!\r\nDice Merge Challenges offers intuitive gameplay that\'s easy to pick up.\r\nBut as you progress, the challenges become more mind-bending!\r\nCombine dice with identical numbers to trigger an explosion creating a new dice with a higher value.\r\nStrategically merge your dice to overpower obstacles and shatter every box! Are you ready to become the ultimate Dice Merge Champion?', 'Merge', 3, 'publish', '2026-04-19 10:28:32'),
(458, 'Italian Brainrot Jigsaw', '3388b07a2043416281e6c33040252ca5', 'https://html5.gamedistribution.com/3388b07a2043416281e6c33040252ca5/', 'assets/thumbs/3388b07a2043416281e6c33040252ca5.jpg', 'Italian Brainrot Jigsaw is a funny puzzle game with the most popular meme characters. You can select one of the fifteen images and then select one of the four modes (16, 36, 64 and 100 pieces). Select your favorite picture and complete the jigsaw in the shortest time possible! Have fun and enjoy!', 'Jigsaw', 8, 'publish', '2026-04-19 10:28:40'),
(459, 'Cute Cat Jigsaw Puzzle', 'fcc8475dec404ce2b2b8754d5f5a22c4', 'https://html5.gamedistribution.com/fcc8475dec404ce2b2b8754d5f5a22c4/', 'assets/thumbs/fcc8475dec404ce2b2b8754d5f5a22c4.jpg', 'Are you a cat lover with a passion for puzzles? If so, get ready for an adorable and engaging adventure with “Cute Cat Jigsaw Puzzle.” This delightful game features 15 levels of feline-themed fun that will captivate your heart and challenge your mind.', 'Jigsaw', 6, 'publish', '2026-04-19 10:28:44'),
(460, 'Squid Game Jigsaw', 'e4017ed802164443a5c7b3e117380a97', 'https://html5.gamedistribution.com/e4017ed802164443a5c7b3e117380a97/', 'assets/thumbs/e4017ed802164443a5c7b3e117380a97.jpg', 'Squid Game Jigsaw is a fun online puzzle game. Drag the pieces into right position using mouse. Solving puzzles is relaxing, rewarding, and keeps your brain sharp. You need to spend $1000 to be able to purchase one of the following pictures. You have three modes for each picture from which the hardest mode brings more money. You have a total of 10 pictures.', 'Jigsaw', 6, 'publish', '2026-04-19 10:28:47'),
(461, 'Granny Jigsaw Puzzle', '5f6af112f4584d65bd065d585e35d369', 'https://html5.gamedistribution.com/5f6af112f4584d65bd065d585e35d369/', 'assets/thumbs/5f6af112f4584d65bd065d585e35d369.jpg', 'Granny Jigsaw Puzzle is a fun horror puzzle game. You can select one of the nine images and then select one of the four modes (16, 36, 64 and 100 pieces). Select your favorite picture and complete the jigsaw in the shortest time possible! Have fun and enjoy!', 'Jigsaw', 7, 'publish', '2026-04-19 10:28:47'),
(462, 'Pop It Jigsaw', '301af62a934543129266c63f3e1d77ee', 'https://html5.gamedistribution.com/301af62a934543129266c63f3e1d77ee/', 'assets/thumbs/301af62a934543129266c63f3e1d77ee.jpg', 'Pop It Jigsaw is a popular puzzle game that combines bubble knocking with Jigsaw puzzles. We have more than 20 cartoon graphics, which can be easily put together. Each level you complete earns you gold, which is used to unlock backgrounds and skins.', 'Jigsaw', 4, 'publish', '2026-04-19 10:28:48'),
