(481, 'Orange Hero Jigsaw', 'ef0a4ead51544f3f82f4f84a25ade6d7', 'https://html5.gamedistribution.com/ef0a4ead51544f3f82f4f84a25ade6d7/', 'assets/thumbs/ef0a4ead51544f3f82f4f84a25ade6d7.jpg', 'Orange Hero Jigsaw is a free online game from the puzzle and jigsaw genre games. You can select one of the 12 images and then select one of the three modes: easy with 25 pieces, medium with 49 pieces and hard with 100 pieces. Have fun and enjoy!', 'Jigsaw', 6, 'publish', '2026-04-19 10:30:14'),
(482, 'Broken Cars Jigsaw', 'd33bb69af77140c1aec9aacb8b2135db', 'https://html5.gamedistribution.com/d33bb69af77140c1aec9aacb8b2135db/', 'assets/thumbs/d33bb69af77140c1aec9aacb8b2135db.jpg', 'This is interesting jigsaw game with five images of broken cars. Choose your favorite image to start to play and choose with how many pieces you want to play in this puzzle game. Use mouse to drag the pieces and to put in right place.', 'Jigsaw', 5, 'publish', '2026-04-19 10:30:15'),
(483, 'Tiger Jigsaw', '94f6f98e9f554ff6a375ffa3f60cc6ff', 'https://html5.gamedistribution.com/94f6f98e9f554ff6a375ffa3f60cc6ff/', 'assets/thumbs/94f6f98e9f554ff6a375ffa3f60cc6ff.jpg', 'Tiger Jigsaw is a fun online puzzle game. Drag the pieces into right position using mouse. Solving puzzles is relaxing, rewarding, and keeps your brain sharp. You need to spend $1000 to be able to purchase one of the following pictures. You have three modes for each picture from which the hardest mode brings more money. You have a total of 10 pictures.', 'Jigsaw', 6, 'publish', '2026-04-19 10:30:23'),
(484, 'On Fire Basketball Shots', '0e8ab73503cb457a8ae6936f464f4344', 'https://html5.gamedistribution.com/0e8ab73503cb457a8ae6936f464f4344/', 'assets/thumbs/0e8ab73503cb457a8ae6936f464f4344.jpg', 'The gym is packed, and the crowd is roaring! The scoreboard\'s ticking down, and your team is trailing. The only way to win is to sink blazing basketball shots from the court. You\'re the star player, but the pressure\'s on—every shot counts, and the hoop\'s rim is red-hot, making each attempt trickier!', 'Basketball', 7, 'publish', '2026-04-19 10:31:12'),
(485, 'Basketball Beans', 'a424ea8e32864377bfd99534ba72eea4', 'https://html5.gamedistribution.com/a424ea8e32864377bfd99534ba72eea4/', 'assets/thumbs/a424ea8e32864377bfd99534ba72eea4.jpg', 'This is a game dedicated to all players who love the game of basketball. Here you can participate in basketball tournaments and play against your opponents. You can control your players to pass and steal the ball. Shoot three-pointers or dunk! Use the rewards to unlock more basketballs and team uniforms. Have fun!', 'Basketball', 6, 'publish', '2026-04-19 10:31:29'),
(486, 'Dude Basket', '2731daf8e1a343c2b5a4e45edd0ff673', 'https://html5.gamedistribution.com/2731daf8e1a343c2b5a4e45edd0ff673/', 'assets/thumbs/2731daf8e1a343c2b5a4e45edd0ff673.jpg', 'Dude Basket is an addictive game designed for cool basketball fans, where you can show off your skills and have fun!\r\nPrepare to experience the joy of playing one of the best Basketball Game with loads of crazy levels to complete.\r\nThe better the player is, the longer the fun would be! Test the real basketball skills and become Dude Basket by practicing hard.\r\nGive your best to hit the target to move onto next level.', 'Basketball', 7, 'publish', '2026-04-19 10:32:05'),
(487, 'Flag Master: World Flags Quiz', '3b80180a914c4db699ee0e0b8840d620', 'https://html5.gamedistribution.com/3b80180a914c4db699ee0e0b8840d620/', 'assets/thumbs/3b80180a914c4db699ee0e0b8840d620.jpg', 'Flag Master is the ultimate test of your flag knowledge and geography skills! Paint and recreate flags, solve jigsaw puzzles, guess capitals, match neighboring countries, and take on a variety of engaging challenges in a fun, fast-paced experience.', 'Quiz', 8, 'publish', '2026-04-19 10:32:12'),
(488, 'Teacher Simulator Christmas Exam', 'a79b2815388140bb8481afced44f2f27', 'https://html5.gamedistribution.com/a79b2815388140bb8481afced44f2f27/', 'assets/thumbs/a79b2815388140bb8481afced44f2f27.jpg', 'Welcome to the funniest and busiest Christmas classroom ever! Teacher Simulator: Christmas Exam is a charming and playful teacher class simulator where you act as a holiday teacher. Manage orders, hand out exam papers, grade tests, etc. Different classes are scheduled on different days of the week, such as art class, geography class, math class, and so on.', 'Quiz', 5, 'publish', '2026-04-19 10:32:18'),
(489, 'Quiz Squid Round', '84be840a39194c2090be4393adeaa7e0', 'https://html5.gamedistribution.com/84be840a39194c2090be4393adeaa7e0/', 'assets/thumbs/84be840a39194c2090be4393adeaa7e0.jpg', 'Dive into the trivia world with Quiz Squid Game. This unique game puts your knowledge of the popular series to test. Not just about general knowledge, but the devil is in the details of this mysterious and thrilling TV show. Get ready to answer questions about plot twists, characters, and little known facts about-in game universe. Impress your friends with your trivia skills and detailed memory of this cinema spectacle.', 'Quiz', 7, 'publish', '2026-04-19 10:32:35'),
(490, 'My Tiny Land', 'c5204f390855459086646797edf67d79', 'https://html5.gamedistribution.com/c5204f390855459086646797edf67d79/', 'assets/thumbs/c5204f390855459086646797edf67d79.jpg', 'An ultra-quiet and super stress-relieving fruit and vegetable matching game with hundreds of types of fruits waiting for you to collect.', 'Quiz', 9, 'publish', '2026-04-19 10:32:38'),
(491, 'Italian Brainrot Quiz', 'd2e5b8969a24463286ba074724014336', 'https://html5.gamedistribution.com/d2e5b8969a24463286ba074724014336/', 'assets/thumbs/d2e5b8969a24463286ba074724014336.jpg', 'Italian Brainrot Quiz is a chaotic meme-guessing game where you match bizarre names to iconic brainrot characters! From Tralalero Tralala to Bombardiro Crocodilo and Tung Tung Tung Sahur – can you guess them all? Each round is a wild ride through surreal Italian meme culture. Laugh, confuse your friends, and become the ultimate Brainrot Champion. Spaghetti logic guaranteed. Ready to play?', 'Quiz', 8, 'publish', '2026-04-19 10:32:41'),
(492, 'Quizmania: Trivia game', '70d8582a335a404a95085fcd2e4be06d', 'https://html5.gamedistribution.com/70d8582a335a404a95085fcd2e4be06d/', 'assets/thumbs/70d8582a335a404a95085fcd2e4be06d.jpg', 'Sharpen your mind across exciting levels. Answer a variety of questions from different topics and use strategic hints to guide your way. As you progress, the difficulty increases, offering a rewarding and challenging experience with every round.', 'Quiz', 6, 'publish', '2026-04-19 10:32:43'),
(493, 'Billionaires', '4739ad11964544fd90677cef5ae48846', 'https://html5.gamedistribution.com/4739ad11964544fd90677cef5ae48846/', 'assets/thumbs/4739ad11964544fd90677cef5ae48846.jpg', 'Play for billions!\r\nThe game involves giving the correct answer by selecting one of the four proposed variants.\r\nThe player must answer all questions correctly to win the main prize!\r\nGood luck! Become a Billionaire and play now!', 'Quiz', 9, 'publish', '2026-04-19 10:32:48'),
(494, 'Would you Rather?', 'a6f3ad3c7b8f4df6b28c3cec4dd4c0df', 'https://html5.gamedistribution.com/a6f3ad3c7b8f4df6b28c3cec4dd4c0df/', 'assets/thumbs/a6f3ad3c7b8f4df6b28c3cec4dd4c0df.jpg', 'Would You Rather is the ultimate group game to play with friends! This party app contains over 120 of the best Would You Rather questions.\r\n✔ Perfect group party game to play with friends.\r\n✔ Great game for playing with groups of friends and family\r\n✔ Works offline making it the perfect road trip game to play in the car\r\n\r\nHundreds of difficult Would You Rather clean and dirty questions await for your friends and family! Can you answer them all?', 'Quiz', 6, 'publish', '2026-04-19 10:32:50'),
(495, 'How many: Quiz game', '6d53e5755f31476fa55d169a74917732', 'https://html5.gamedistribution.com/6d53e5755f31476fa55d169a74917732/', 'assets/thumbs/6d53e5755f31476fa55d169a74917732.jpg', 'How many can win this game? This is the most entertaining trivia game ever\r\n\r\nChallenge yourself with how smart you are. The rules are simple, guess the closest answer or get eaten by a shark or boiled in the hot water! Carefully read the quiz questions and type the correct answer on the board.', 'Quiz', 9, 'publish', '2026-04-19 10:32:54'),
(496, 'Millionaire with Trump', '2b97dbe975204ca698032ce983c519c1', 'https://html5.gamedistribution.com/2b97dbe975204ca698032ce983c519c1/', 'assets/thumbs/2b97dbe975204ca698032ce983c519c1.jpg', 'Trump has a job for you, choose trump as your candidate &amp; answer the right questions. There is no room for mistakes, trump will not bear it.', 'Quiz', 5, 'publish', '2026-04-19 10:33:14'),
(497, 'EG Quiz Games', 'd75ac7739a8f4d5eb93e8b37a6811b4b', 'https://html5.gamedistribution.com/d75ac7739a8f4d5eb93e8b37a6811b4b/', 'assets/thumbs/d75ac7739a8f4d5eb93e8b37a6811b4b.jpg', 'EG Quiz Games is most challenging yet addictive word guessing game. This game is a Real brain teaser indeed.', 'Quiz', 6, 'publish', '2026-04-19 10:33:17');
